export default [{"id":21,"question":"هذه سائلةٌ لها سؤال من شقّين: الشق الأول تقول فيه: عند قدوم العادة الشَّهرية يسبقها بعدَّة أيام بعض الإفرازات المهبلية التي لونها يميل إلى الصُّفرة، وأحيانًا مخلوطة ببعض الدم البسيط، وهي محتارة كما تقول، لا تعرف حكمها، هل تُصلي في هذه الفترة أم تترك الصلاة؟ مع العلم أنه إذا بدأ الدمُ يجلس ستة أيام بعد هذه الإفرازات، وإن عُدَّت هذه مع العادة فسيبلغ تقريبًا خمسة عشر يومًا.","title":"حكم الإفرازات التي تسبق الحيض","answer":"الجواب: هذا يسأل عنه كثيرٌ من النساء، والجواب: أنَّ هذا قد يقع قبل العادة، وقد يقع بعد العادة، فإذا كان قبلها لم يتصل بها فليس بحيضٍ، فإذا رأت الصُّفرةَ والكُدْرةَ وهذه الإفرازات التي قبل العادة بيومٍ أو يومين أو ثلاثة أو أربعة، ثم تنقطع وتزول، ثم تأتي العادة؛ فهذه لا يُعول عليها، ولا تترك الصلاة فيها، بل تُصلي وتصوم وتحلّ لزوجها، وهكذا إذا كانت منفصلةً بعد العادة -بعد الطهر- تأتيها إفرازات -صُفرة وكُدرة بعد العادة- فهذه لا يُعول عليها، ولا يُلتفت إليها، ولا تدع لها الصلاة والصوم، ولا يمتنع منها زوجُها.\nثبت في البخاري عن أم عطية رضي الله عنها قالت: \"كنا لا نعد الكُدرة والصُّفرة شيئًا\"، زاد أبو داود: \"بعد الطُّهْر\"، وهي زيادةٌ مُوضِّحةٌ للمعنى، فالمعنى: أنَّ الصحابيات كن لا يعددن الصُّفرةَ والكُدرة بعد الطهر شيئًا، وهذا يعمُّ الطهر قبل الحيض والذي بعد الحيض، فما كان بعد الطهر قبل مجيء الحيضة وما كان بعد الحيضة كله لا يُعدّ ما دام صفرةً أو كُدرةً، وإن خلطها شيءٌ يسيرٌ من الدم لا عبرةَ بذلك.\nأما إن كانت متصلةً تبدأ بالصُّفرة ثم يجيء الدم مُتَّصلًا فهذه من الحيض، وهكذا بعده متصلةً به، هذه من الحيضة ولو بلغت خمسة عشر يومًا، فهذا من الحيض.","link":"https://binbaz.org.sa/fatwas/2800/حكم-الافرازات-التي-تسبق-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0273.mp3","categories":["الحيض والنفاس"]},{"id":22,"question":"هل انقطاع الدم عن المرأة النّفساء يعني طُهرها، وإن كان يخرج منها بعد انقطاعه غيرُه من ماءٍ ونحوه، ومع ذلك لم تغتسل ولم تُصلِّ؟ وهل يجب عليها قضاء ما فاتها من الصلاة؟ وكيف تقضيها؟","title":"هل تطهر النفساء بمجرد انقطاع الدم؟","answer":"الجواب: النفاس ليس لأقلّه حدٌّ، فإذا طهرت وهي أم عشرة أيام أو عشرين يومًا من الولادة أو ثلاثين يومًا من الولادة فإنها تغتسل وتُصلي، ليس لأقلِّه حدٌّ عند أهل العلم، ورُويت فيه أحاديث عن النبي ﷺ أيضًا؛ أنه وقَّت في ذلك أربعين، إلا أن تطهر قبل ذلك.\nالمقصود أن النِّفاس ليس له حدٌّ من جهة الأقلية، فإذا طهرت لعشرٍ أو لخمسة عشر أو لعشرين أو لشهرٍ أو لأقل أو لأكثر فإنها تغتسل وتُصلي وتصوم وتحل لزوجها، وإن كانت لم تُكمل الأربعين، فالطَّهارة مُعتبرة في هذا، ولو كان معها ماء أبيض، فهذا الماء الأبيض لا يُعتبر نفاسًا، النفاس هو الدم، فإذا طهرت ولكن صار معها سيلان من المياه فهذه لا عبرة بها، مثل: المياه التي تأتي المرأة وهي حامل، فهذه المياه لا تُعتبر حيضًا ولا نفاسًا، فهكذا بعد الوضع لا يُعتبر هذا الماء حيضًا ولا نفاسًا. فلو رجع إليها الدمُ -طهرت لعشرين أو لعشرة أيام، ثم جاءها دمٌ في الحادي والثلاثين- فإنها ترجع إلى النِّفاس على الصحيح: لا تُصلي، ولا تصوم بعد رجوع الدم، والعشرة التي طهرتها صلاتها فيها صحيحة، وصومها فيها صحيح، وإن كانت ما صلَّت فعليها أن تقضي تلك الصَّلوات التي تركتها، تسردها سردًا، لا كما يقول العامَّةُ: الظهر مع الظهر، والعصر مع العصر، لا، تسردها ولو في ضحوةٍ، ولو في ظهرٍ، ولو في ليلٍ، تسردها جميعًا حسب طاقتها، ولا مانع من الاستراحة فيما بين ذلك، كلما نشطت قامت حتى تُؤدي ما فرطت فيه في أيام الطَّهارة.\nفإن كمّلت الأربعين والدم معها فإنها تغتسل، فإن النهاية أربعون، نهاية النفاس على الصحيح أربعون، هذا هو الصواب كما في حديث أم سلمة، فإذا بلغت أربعين ولم تطهر فإنَّها تُعتبر طاهرةً في الحكم، وعليها أن تغتسل وتُصلي وتصوم وتحلّ لزوجها حكمًا، وهذا الدم الذي معها يُعتبر دم فسادٍ: تُصلي معه، وتصوم، وتحل لزوجها، ولكنها لا تتوضأ إلا عند دخول الوقت؛ لقول النبي ﷺ للمُستحاضة: وتوضئي لوقت كل صلاةٍ، هذا الحكم حكم الاستحاضة، لكن إذا وافق العادةَ -عادة النساء في الحيض- جلست لعادة الحيض، فإذا جاء وقت العادة وصادفها هذا الدم فإنها تجلس اعتبارًا بأنه حيضٌ، هذا هو الصواب في هذه المسألة، ونسأل الله للجميع التوفيق.\nوينبغي للمرأة وللرجل أن يسأل أهلَ العلم عمَّا أشكل، ليس في السؤال حياء، يقول الله : وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ [الأحزاب:53]، ويقول جلَّ وعلا: إِنَّ اللَّهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا [البقرة:26]، وتقول أم سليم للنبي ﷺ: يا رسول الله، إنَّ الله لا يستحيي من الحقِّ، فهل على المرأة من غُسلٍ إذا هي احتلمت؟ قال النبيُّ: نعم، إذا هي رأت الماء، فينبغي لمَن جهل شيئًا ألا يسكت، رجلًا كان أو امرأةً، يسأل أهل العلم من طريق الهاتف، فقد يسَّر الله هذه الهواتف رحمةً من الله ، أو من طريق الإذاعة من طريق برنامج \"نور على الدرب\"، وهو برنامج مفيد وعظيم، وأنا أوصي باستماعه، أوصي إخواني وأخواتي باستماع هذا البرنامج، فهو برنامج مفيد، وهو يُذاع بين المغرب والعشاء من \"نداء الإسلام\"، ويُذاع في الساعة التاسعة والنصف من إذاعة القرآن كل ليلةٍ، وهذه من نِعم الله العظيمة، فينبغي أن يُستمع لهذا البرنامج، وأن يُستفاد منه، ومَن أشكل عليه شيءٌ من هذا البرنامج يسأل أيضًا، سواء كان رجلًا أو امرأةً، وهكذا طريق الهواتف مفيد ونافع.\nالمقصود أنَّ الواجب العناية بالعلم والتفقّه في الدين، يقول النبيُّ ﷺ: مَن يُرد الله به خيرًا يُفقهه في الدين، ويُروى عنه ﷺ أنه قال لقومٍ أفتوا بغير علمٍ: ألا سألوا إذ لم يعلموا؟! إنما شفاء العيّ السؤال، وأكبر من هذا قوله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [الأنبياء:7]، ويقول النبيُّ ﷺ: مَن سلك طريقًا يلتمس فيه علمًا سهَّل الله له طريقًا إلى الجنة، هذا فضلٌ عظيمٌ، ولا ينبغي الحياء في هذا المقام، ولا التساهل، ولا الكسل.\nكان الناس أولًا يذهبون على الأقدام، ومن طريق الإبل، ومن طريق الدواب الأخرى؛ يطلبون العلم، وربما سار بعضُهم الأيام الكثيرة في طلب العلم، فكان بعض الصحابة يُسافر المسافات الطويلة من المدينة إلى مصر، وإلى الشام، في حديثٍ واحدٍ، والآن قد يسَّر الله  للسائل أن يسأل وهو في أمريكا، يسأل من أمريكا إلى الرياض، أو إلى مكة، أو إلى مصر، أو إلى غير ذلك من طريق الهاتف في لحظةٍ، في لحظاتٍ، يستفيد وهو في مكانه، وعلى سريره، يسأل ويستطيع أن يكتب لأهل العلم بالبُرُد، فيأتيه الجواب، ويكتب لبرنامج \"نور على الدرب\" فيأتيه الجواب عن المذياع في الأثير، وهو جالسٌ في مجلسه، هذه من نِعَم الله العظيمة.","link":"https://binbaz.org.sa/fatwas/2801/هل-تطهر-النفساء-بمجرد-انقطاع-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0274.mp3","categories":["الحيض والنفاس"]},{"id":24,"question":"ما حكم قراءة القرآن من قِبَل المدرسة للطالبات بدون أن تمسَّ المصحف إلا من وراء منديل إذا كانت غير طاهرةٍ –أي: في وقت الحيض؟ أفيدونا جزاكم الله خيرًا","title":"حكم تلاوة الحائض دون مس المصحف","answer":"الجواب: في هذه المسألة خلافٌ بين أهل العلم كثير، وحكى بعضُهم قول الجمهور أنه لا يجوز لها أن تقرأ وهي حائض أو نُفساء، وذهب جمعٌ من أهل العلم إلى جواز ذلك من دون مسِّ المصحف، وهذا هو القول الأرجح؛ لأنها ليست مثل الجنب، الجنب بإمكانه أن يغتسل ويقرأ في الحال، والجنب ممنوعٌ من القراءة كما في الحديث الصحيح: \"كان النبيُّ ﷺ لا يحجزه شيءٌ عن القرآن إلا الجنابة\"، أما الحائض والنّفساء فمدّتهما تطول، ليستا مثل الجنب، وليس على منعهما دليلٌ واضحٌ.\nفالصواب أنه يجوز لها أن تقرأ عن ظهر قلبٍ من دون مسّ المصحف، ولو دعت الحاجةُ إلى مسِّه من وراء حائلٍ أو إمساك غيرها للمصحف حتى يردَّ عليها فيما تغلط فيه فلا بأس، أما بيدها من دون حائلٍ فلا يجوز مسّ المصحف حتى تتطهر، لكن عن ظهر قلبٍ لا حرج في ذلك.\nوأما حديث أنه ﷺ قال: لا يقرأ الجنبُ والحائضُ شيئًا من القرآن خرجه أبو داود، فهذا حديثٌ عند أهل العلم ضعيفٌ؛ لأنه من رواية إسماعيل بن عياش، عن موسى بن عقبة، وإسماعيل عند أهل العلم ضعيف فيما يرويه عن أهل الحجاز –يعني: غير الشَّاميين.\nفالمقصود أنَّ الحديث في هذا ضعيفٌ، والصواب في هذا أنه لا مانع من قراءة الحائض القرآن عن ظهر قلبٍ: كالمُدرسة، والطالبة في الامتحان، أو في غير ذلك، لكن من دون مسِّ المصحف، فإن دعت الحاجةُ إلى مسِّ مصحفٍ من وراء حائلٍ؛ كالقفازين، أو فوطة، أو منديل صفيق، أو ما أشبه ذلك عند الحاجة، فالأقرب جواز ذلك.","link":"https://binbaz.org.sa/fatwas/2804/حكم-تلاوة-الحاىض-دون-مس-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0277.mp3","categories":["الحيض والنفاس"]},{"id":151,"question":"ماذا يجوز للرجل من زوجته أيام الحيض؟","title":"ماذا يجوز للزوج من زوجته أيام الحيض؟","answer":"الجواب: يجوز للرجل من زوجته كل شيءٍ إلا الجماع، قال النبيُّ ﷺ: اصنعوا كل شيءٍ إلا النكاح، لما قالوا له ﷺ: إنَّ اليهود لا يُجامعون المرأة إذا كانت حائضةً في البيوت، لا يُجامعوها في البيوت يعني: لا يُساكنونها، ولا يأكلون معها، ولا يشربون معها، فقال عليه الصلاة والسلام: اصنعوا كل شيءٍ إلا النكاح، وأنزل الله في ذلك: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ [البقرة:222] يعني: الجماع، أما كونه يُضاجعها وينام معها ويُقبّلها ويضمّها إليه فلا بأس بذلك، إلا الجماع فقط.\nوكانت عائشة رضي الله عنها تشرب من الإناء، ثم يأخذه النبيُّ ﷺ ويضع فمه في موضع فمها، وتتعرّق العظم فيأخذ ذلك أيضًا ويتعرّقه؛ تطييبًا لقلبها، وإيناسًا لها، ومُداعبةً لها.","link":"https://binbaz.org.sa/fatwas/3688/ماذا-يجوز-للزوج-من-زوجته-ايام-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0144.mp3","categories":["الحيض والنفاس"]},{"id":213,"question":"حدَّثني رجلٌ أنه أفطر في مطار الرياض في الطائرة، ولما صعدت الطائرةُ إلى السَّماء رأوا الشمس حمراء لم تغرب، فما حكم إفطاره؟","title":"حكم من أفطر بالمطار ثم رأى الشمس بالجَوّ","answer":"الجواب: الذي يظهر أنَّ إفطاره صحيحٌ؛ لأنه أفطر بغروب الشمس في بلده، فهو بمثابة مَن سافر من الشرق بعدما غربت الشمس حتى وصل إلى بلدٍ في الغرب فيها الشمس لم تغرب، فصومه صحيحٌ؛ لأنه انتهى إلى جوٍّ رفيعٍ ليس جوَّه، بل جوٌّ آخر ليس جوًّا له، فلا يضرّه إفطاره، فهو مفطرٌ صحيحٌ، وصومه صحيحٌ.\nفلو سافر مثلًا من جدة وقد أفطر، ووصل إلى الشام أو إلى مصر ولم تغب الشمس؛ فصومه صحيحٌ، وهكذا غير ذلك: كمَن سافر من تونس بعدما غابت الشمس مُفْطِرًا، فوصل إلى الجزائر أو المغرب ولم تغرب؛ فصومه صحيحٌ، قد انتهى يومه.","link":"https://binbaz.org.sa/fatwas/3994/حكم-من-افطر-بالمطار-ثم-راى-الشمس-بالجو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0220.mp3","categories":["الحيض والنفاس","مسائل متفرقة في الصيام"]},{"id":214,"question":"اختلف الناسُ بالنسبة للإفطار في مدينة الطائف: فمنهم مَن لا يُفطر مع المؤذن، وحجّتهم أنَّ هناك بعض الناس رأى الشمس من الشّفا لم تغرب بعد. هل نُفطر مع الأذان أم نتأخّر للتَّحري؟وهل الطائف مثل الشّفا بالنسبة للغروب؟","title":"حكم إفطار الصائم مع الأذان مع الشك بالوقت","answer":"الجواب: كل محلٍّ له حكمه، الطائف تغيب عليه الشمس قبل مكة؛ لأنه عنها شرق، ففي الجملة متى غابت الشمسُ على أهل الطائف أفطروا، أما مَن كان في الهَدَا أو في الشّفا أو في محلات مرتفعة فليس لهم أن يُفطروا حتى تغيب عنهم الشمسُ هم، ولهم حكمهم، كما أنَّ لأهل غامد وزهران وأهل الإحساء وأهل المنطقة الشرقية وباكستان وغيرها، كلٌّ له حكمه، والبلاد فيها المطمئن، وفيها المرتفع، فالذين في محلِّ الارتفاع وفي الجبال يُفطرون إذا غابت عليهم الشمسُ، والذين في البلاد إذا غابت عنهم الشمسُ أفطروا، ولم يلزمهم أن يُرسلوا إلى الجبال التي حولهم حتى ينظروا: هل غابت الشمس؟ فمتى غابت الشمسُ عنهم وعن بلادهم في مساجدهم ومناراتهم فقد غابت الشمسُ عنهم، وأولئك المُرتفعون في الجبال لهم شأنهم، كأهل الهَدَا وأشباههم.","link":"https://binbaz.org.sa/fatwas/3995/حكم-افطار-الصاىم-مع-الاذان-مع-الشك-بالوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0221.mp3","categories":["الحيض والنفاس","مسائل متفرقة في الصيام"]},{"id":304,"question":"سائلة تقول: فضيلة الشيخ، هل إذا بلغت المرأةُ خمسين سنةً وجاءتها الدورة الشهرية لا تَعْتَبِر بها وتُصلي وتصوم؟ أرجو الإفادة في ذلك.","title":"ما حكم مَن تحيض في عمر الخمسين؟","answer":"الجواب: اختلف العلماءُ في هذا: منهم مَن جعل الحدَّ خمسين سنةً، ومنهم مَن جعله ستين سنةً، وليس على هذا دليلٌ واضحٌ، إلا ما ثبت عن عائشة رضي الله عنها أنها قالت: \"إن المرأة لا تجد في بطنها بعد الخمسين شيئًا\"، وهذا قالته عن اجتهادها.\nوالصواب أنَّ الحيض إذا استمرَّ معها ولم يتغير ولو بعد الخمسين فإنَّها تجلس؛ لعدم الدليل على تحديد المدة، لكن إذا اضطرب عليها بعد الخمسين وتغيرت حاله فهذه علامة الانقطاع، وعلامة أنه غير الحيض، فإذا اضطرب عليها بعد الخمسين فإنه لا يعتبر حيضًا، ويكون هذا من الدلائل على انتهائه، بأن يكون تارةً أحمر، وتارةً أصفر، وتارةً كذا، تارةً يزيد، وتارة ينقص، وتارة يأتي، وتارة لا يأتي، يعني: يضطرب؛ شهر يأتي، وشهر لا يأتي،  شهر خمس، وشهر عشر، وشهر ثمانٍ، بعد الخمسين، تارة أسود، وتارة أحمر، وتارة غير ذلك، يتقلَّب، فهذا دليلٌ على أنه انتهى أمره، فلا تعتبره، وتعتبره دمًا فاسدًا كالاستحاضة؛ تُصلي معه، وتصوم، وتتحفظ بالقطن ونحوه، وتتوضأ لوقت كل صلاةٍ ما دام معها الدمُ، إذا اضطرب عليها وفسد بعد الخمسين.","link":"https://binbaz.org.sa/fatwas/4307/ما-حكم-من-تحيض-في-عمر-الخمسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0354.mp3","categories":["الحيض والنفاس"]},{"id":317,"question":"امرأة دخلت المستشفى لإجراء عملية في رجلها، وكانت عليها العادة الشهرية، فطهرت وهي في المستشفى، فلم تستطع الغسل من الحيض؛ لوجود المُغذيات وغيرها، فتيمَّمت وصلَّت عدَّة أوقاتٍ، فما حكم صلاتها؟ وما الذي يجب عليها؟ وجزاكم الله خيرًا.","title":"ما حكم مَنْ طهرت وتعذّر الغُسل لجراحة؟","answer":"الجواب: إذا كانت لم تستطع الغسل؛ أجزأها التيمم. ولكن إذا كانت تستطيع الغُسل في غير رجلها؛ تغسل رأسها وبدنها كله ما عدا الرِّجل التي فيها المُصيبة. فالواجب عليها الغسل، أما إن كان معها ما يضرُّها معه الغسل من جراحات، أو نصحها الأطباءُ بألا تستعمل الماء مدة العلاج لمرضٍ بها يضرُّه الماء؛ فلا بأس، تيمّمها صحيح، وصلاتها صحيحة. أما مجرد الرِّجْل فالواجب أن تكون الرِّجْلُ تُجَنَّب الماء، ما تُغسل الرِّجْل، ولكن يجب عليها غسل بقية البدن عن الحيض والجنابة، فإذا كانت ما يضرُّها الماء إلا مجرد الرِّجْل فعليها الإعادة، عليها أن تُعيد الصلاة، وعليها أن تغتسل، والرِّجْل إذا كانت عليها جبيرة تمسح على الجبيرة، اللّفافة التي عليها تُمسح كلها ويكفي.","link":"https://binbaz.org.sa/fatwas/4347/ما-حكم-من-طهرت-وتعذر-الغسل-لجراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0368.mp3","categories":["الحيض والنفاس"]},{"id":334,"question":"هل يجوز للمرأة أن تصوم قبل إكمال الأربعين إذا توقَّف الدمُ منها أم تُكمل الأربعين؟","title":"حكم طُهر النفساء قبل الأربعين وتأخره بعدها","answer":"الجواب: متى طهرت وجب عليها الصوم والصلاة وإن كانت في الأربعين، وحلَّت لزوجها، الاعتبار بالطَّهارة، فإذا طهرت دون العشرين أو الثلاثين يومًا تغتسل وتُصلي وتصوم وتحلّ لزوجها ولو ما كملت الأربعين. فإن استمرَّ معها إلى أربعين؛ اغتسلت في الأربعين ولو معها الدم؛ لأنَّ النهاية أربعون، فتغتسل وتُصلي وتصوم وتحلّ لزوجها بعد الأربعين وإن كان معها الدمُ، لكن تتوضأ لكل وقت صلاةٍ، وتتحفظ بقطن ٍونحوه حتى يزول عنها، إلا إذا صادف وقت الحيض، جلست وقت الحيض بعد الأربعين، نعم.","link":"https://binbaz.org.sa/fatwas/4422/حكم-طهر-النفساء-قبل-الاربعين-وتاخره-بعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0387.mp3","categories":["الحيض والنفاس"]},{"id":342,"question":"إذا صمتُ رمضان في هذا البلد، وسافرتُ إلى بلدي قبل العيد بيومٍ واحدٍ فقط، ووجدتهم تبقى لهم يومان من الصيام؛ لأنهم صاموا بعد هذا البلد بيومٍ، فهل أصوم معهم يومًا آخر أم أُفطر كما أفطر أهلُ هذا البلد؟","title":"هل يصوم المسافر ويفطر مع بلد سفره؟","answer":"الجواب: تصوم معهم؛ لأنَّك صرتَ معهم، وصرتَ من جُملتهم، الرسول ﷺ قال: الصوم يوم تصومون، والفطر يوم تُفطرون، تصوم معهم.","link":"https://binbaz.org.sa/fatwas/4430/هل-يصوم-المسافر-ويفطر-مع-بلد-سفره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0395.mp3","categories":["الحيض والنفاس","مسائل متفرقة في الصيام"]},{"id":417,"question":"امرأة صامت يومًا، وبعد إفطارها على التمر والماء وقبل صلاة المغرب جاءتها العادة الشَّهرية، هل جاز صيامها ذلك أم تُعيده؟","title":"حكم من أتتها العادة الشهرية مع وقت الإفطار","answer":"الجواب: نعم، نعم، إذا كانت لم ترَ الدمَ إلا بعد الغروب بعد إفطارها ولو بالماء -المقصود بعد الغروب- فصومها صحيحٌ، ولو جاءتها العادةُ قبل أن تُصلي المغرب، ما دامت غابت الشمسُ وهي لم تأتها العادةُ -لم يخرج منها الدمُ- فصومها صحيحٌ.","link":"https://binbaz.org.sa/fatwas/4835/حكم-من-اتتها-العادة-الشهرية-مع-وقت-الافطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0475.mp3","categories":["الحيض والنفاس"]},{"id":465,"question":"في أثناء الأربعين طَهُرت ثم رجع الدم؟","title":"ما الحكم لو انقطع الدم أثناء الأربعين ثم عاد؟","answer":"الجواب: تجلس ما دام في الأربعين، تجلس.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6190/ما-الحكم-لو-انقطع-الدم-اثناء-الاربعين-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/tohr025.mp3","categories":["الحيض والنفاس"]},{"id":466,"question":"بعض النساء إذا تمت الأربعين تلحقها حيضة؟","title":"ما حكم دم الحيض الذي يلي النفاس؟","answer":"الجواب: إذا جاء دم الحيض في وقتها المعتاد؛ فلا بأس.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6191/ما-حكم-دم-الحيض-الذي-يلي-النفاس","audio":"https://files.zadapps.info/binbaz.org.sa/arb3en026.mp3","categories":["الحيض والنفاس"]},{"id":468,"question":"إذا ولدت المرأة توأمين أو أكثر فما تعتبر في بدء النفاس من الأول أو الثاني أو الثالث؟","title":"ما بداية النفاس لمن ولدت توأمين أو أكثر؟","answer":"الجواب: الأقرب، والله أعلم، أنه من الأول.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6193/ما-بداية-النفاس-لمن-ولدت-توامين-او-اكثر","audio":"https://files.zadapps.info/binbaz.org.sa/neefas028.mp3","categories":["الحيض والنفاس"]},{"id":469,"question":"المرأة إذا أصابها طلق – هل يكون الدم هذا دم نفاس؟","title":"هل الدم الخارج أثناء الطَّلق دم نفاس؟","answer":"الجواب: إذا كان مع الطلق، نعم.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6194/هل-الدم-الخارج-اثناء-الطلق-دم-نفاس","audio":"undefined","categories":["الحيض والنفاس"]},{"id":1030,"question":"أفطرت في أحد السنين على قدري، أو في بعض سنين في الأيام التي تأتي فيها الدورة الشَّهرية، وكنتُ حينذاك صغيرةً، ولم أتمكن من الصيام، والآن أود أن أقضي ما عليَّ من دَين الصيام، ولكن لا أعرف كم عدد الأيام التي عليَّ، فماذا أفعل؟","title":"حكم من أفطرت جهلًا برمضان في صِغَرها","answer":"الجواب: الشيخ: عليك ثلاثة أمور:\nالأمر الأول: التَّوبة إلى الله عن هذا التَّأخير، والنَّدم على ما مضى، وكثرة الاستغفار، والعزم ألا تعودي لمثل هذا؛ لأنَّ الله يقول: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وهذه معصية، والتوبة منها واجب بالنَّدم على الماضي، والإقلاع من ذلك، وعدم العودة إليه.\nالأمر الثاني: البدار بالصوم على حسب الظن، لا يُكلِّف الله نفسًا إلا وسعها، الذي تظنين أنَّكِ تركتيه من الأيام تصومينه: إذا ظننتِ أنها عشرًا تصومين عشرة أيام، وإذا ظننتِ أنها خمسين يومًا تصومين خمسين يومًا، وإن كان أقلّ..... صومي ظنّك عند عدم الجزم، إذا كان ما عندك علمٌ فالظن يكفي.\nالأمر الثالث: إطعام مسكينٍ عن كل يومٍ إذا كنت تقدرين، إذا كان عندك مالٌ وقُدرة تُطعمين عن كل يومٍ مسكينًا من هذه الأيام المؤخَّرة، نصف صاع -كيلو وربع- عن كل واحدٍ، تجمعينها وتُعطينها بعض الفقراء.","link":"https://binbaz.org.sa/fatwas/21098/حكم-من-افطرت-جهلا-برمضان-في-صغرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0894فطرت في الأيام التي تأتيني الدورة وأنا صغيرة ولم أقضي والآن أريد أن أقضي ولا أعرف كم علي؟.mp3","categories":["الحيض والنفاس","قضاء الصيام","قضايا المرأة"]},{"id":1113,"question":"امرأةٌ أفطرت في رمضان بسبب النِّفاس، ومرت سنوات عديدة ولم تقضِ الأيام التي فاتتها جهلًا منها، ما الحكم في مثل هذه الحالة؟","title":"حكم مَن أفطرت في نفاسها ولم تقضِ جهلًا","answer":"الجواب:\nالتي عليها صيام من رمضان بسبب النِّفاس، أو الحيض، أو المرض، أو السفر، وتأخَّرت في الصيام؛ تصوم مع التوبة والنَّدم وإطعام مسكينٍ عن كل يومٍ إذا تأخَّر القضاءُ عن رمضان الذي يلي الشهر الذي تركت الصيام منه، إذا جاء رمضان الآخر وهي لم تصم؛ تصم بعد ذلك وعليها إطعام مسكينٍ عن كل يومٍ مع القدرة، إذا كانت تقدر، أما إنْ كانت فقيرةً لا تستطيع فيكفيها الصوم، تقضي الأيام، قال الله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].\nوهكذا الرجل: إذا تأخَّر الصوم الذي عليه بعدما صحَّ من مرضه، أو قدم من سفره، تساهل حتى جاء رمضان آخر، فإنه يقضي بعد ذلك، وعليه التوبة عن التَّقصير، وعليه إطعام مسكينٍ عن كل يومٍ أخَّره.\nفالرجل والمرأة في هذا سواء، إذا أخَّر إلى رمضان آخر وجب القضاء والتّوبة وإطعام مسكينٍ عن كل يومٍ، مع القُدرة، فإن لم يستطع الإطعام صام وكفاه الصيام.","link":"https://binbaz.org.sa/fatwas/21166/حكم-من-افطرت-في-نفاسها-ولم-تقض-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0962أمرأة أفطرت في رمضان بسبب النفاس مرَّت سنوات ولم تقضي الأيام التي فاتتها جهلاً منها فما الحكم.mp3","categories":["قضاء الصيام","الحيض والنفاس","قضايا المرأة"]},{"id":1140,"question":"ما حكم قراءة القرآن للحائض والنُّفساء، وأحيانًا يُصادف الامتحان مثل هذه الحالات؟","title":"ما حكم قراءة القرآن للحائض والنُّفساء؟","answer":"فيه خلافٌ بين أهل العلم، والصواب أنه يجوز للحائض أن تقرأ القرآنَ عن ظهر قلبٍ، والنفساء كذلك، ولا يجوز أن تُقاس عليها الجُنُب، والجُنُب يتيسر له الاغتسال بسرعةٍ ويقرأ، لكن الحائض والنفساء ليستا كذلك، ليستا مثله، لهن مدَّة، ليس الأمر بأيديهن.\nفالصواب أنه يجوز لهنَّ قراءة القرآن عن ظهر قلبٍ، وهكذا قراءة القرآن من المصحف من وراء حائلٍ أو قفَّازين عند الحاجة إلى ذلك: كمُراجعة مَن تغلط فيه عند الامتحان ونحو ذلك.\nأما حديث لا يقرأ القرآنَ الحائضُ والجنبُ فهو حديثٌ ضعيفٌ عند أهل العلم، والصواب أنَّ هذا خاصٌّ بالجُنب، كان النبي ﷺ لا يحجزه شيءٌ عن القرآن إلا الجنابة، فلا يُقاس على الجنبِ الحائضُ والنفساء؛ لأنهما ليستا مثله، وهما في حاجةٍ إلى قراءة القرآن عن ظهر قلبٍ، وإلى مُراجعته عند الامتحان والاختبار، ولئلا تنساه الحائض والنفساء، ولكن يجوز بواسطة حائلٍ: قفَّازين ونحوهما.","link":"https://binbaz.org.sa/fatwas/21192/ما-حكم-قراءة-القران-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0988ما حكم قراءة القرآن للحائض والنفساء وأحياناً يصادف اختبار؟.mp3","categories":["شروح الحديث","القرآن وعلومه","الحيض والنفاس"]},{"id":1501,"question":"إذا رأت المرأةُ النَّقاء لمدة يوم كامل في أيام عادتها الشهرية، إذا كانت عادتها سبعة أيام فرأت من هذه السبعة يومًا...؟","title":"حكم مَن رأت الطُّهرا يومَا كاملا أثناء عادتها","answer":"الجواب:\nتغتسل وتصلي، وهكذا النفساء إذا رأت يومًا من الطهر تغتسل وتصلي.\nس: في أثناء العادة؟\nج: نعم في أثناء العادة، وفي أثناء النفاس، كله واحد.","link":"https://binbaz.org.sa/fatwas/21600/حكم-من-رات-الطهرا-يوما-كاملا-اثناء-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في طهر المرأة.mp3","categories":["الحيض والنفاس"]},{"id":1614,"question":"سؤال من امرأةٍ تقول: ركبتُ لولبًا، وكانت أيام الدورة ستة أيام، ولا يزال الدم مستمرًّا، وتركت الصلاة مدة خمسة أيام بعد الأيام الأولى، فهي في خلال خمسة أيام لم تُصلِّ، هل تُعيد الصلاة خمسة أيام؟ وهل عليها إثم؟","title":"حكم صلاة المرأة التي زاد الدم عن عادتها","answer":"الجواب:\nهو الأحوط، لها أن تُعيد ما زاد على الدورة، الرسول لما اشتكت إليه النساء أمر مَن اشتكت إليه الدّماء أن تغتسل عند تمام الدورة.","link":"https://binbaz.org.sa/fatwas/21718/حكم-صلاة-المراة-التي-زاد-الدم-عن-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة المرأة التي ينزل منها دم.mp3","categories":["الحيض والنفاس","قضاء الفوائت"]},{"id":1736,"question":"هل يُشرع للنساء رفع الصَّوت بالتلبية؟","title":"ما حكم رفع الصوت بالتلبية للنساء؟","answer":"الجواب:\nبينهنَّ، كل واحدةٍ ترفع صوتها بقدر ما تُسْمِع مَن حولها من نسائها.","link":"https://binbaz.org.sa/fatwas/21843/ما-حكم-رفع-الصوت-بالتلبية-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الصوت بالتلبية للنساء.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":1737,"question":"إذا طهرت الحائضُ قبل مفارقة بنيان مكة، هل يلزمها الرجوعُ للبيت لطواف الوداع؟","title":"حكم من حاضت ثم طهرت قبل طواف الوداع","answer":"الجواب:\nلا، ما يلزمها، إذا خرجت وهي حائض ما عليها شيء.\nس: إذا طهرت؟\nج: ولو طهرت، ما دامت فارقت البلد فالحمد لله.\nس: قبل مفارقة البنيان إذا طهرت هل يلزمها الرجوع لطواف الوداع؟\nج: ما يلزمها الرجوع.","link":"https://binbaz.org.sa/fatwas/21844/حكم-من-حاضت-ثم-طهرت-قبل-طواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا طهرت الحائض قبل خروجها من مكة هل ترجع للبيت لطواف الوداع.mp3","categories":["الطواف بالبيت","الحيض والنفاس","قضايا المرأة"]},{"id":1937,"question":"إذا طلَّق الرجلُ امرأتَه وهي حائض هل يثبت أم لا يثبت؟","title":"ما حكم طلاق الحائض؟","answer":"الجواب:\nإذا كان يعرف ذلك وهي تعرف ذلك؛ فالصحيح أنه لا يقع عند بعض أهل العلم، والجمهور على أنه يقع، لكن الأصح أنه لا يقع؛ لحديث ابن عمر، إذا كان يعلم ذلك.\nس: إذا كان ما يعلم؟\nج: يقع عليه؛ لأنه ما ابتدع، ما تعمَّد بدعةً، إن كان يعلم فقد تعمَّد بدعةً، تعمَّد مُنكرًا فلا يقع، وإذا كان ما يعلم أو حكم به القاضي فإنه يقع، فأكثر القضاة يحكم بهذا، والأصح عند الأقل أنه لا يقع، والجمهور على أنه يقع؛ لأن ابن عمر أمضاه على نفسه.","link":"https://binbaz.org.sa/fatwas/22050/ما-حكم-طلاق-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقع طلاق الحائض.mp3","categories":["الطلاق","الحيض والنفاس"]},{"id":2092,"question":"ما الصواب في دم الحيض؟ هل هو نَجِسٌ أم طاهرٌ؟","title":"هل دم الحيض نَجِسٌ أم طاهرٌ؟","answer":"الجواب:\nهو دم نَجِس؛ فالنبي عليه الصلاة والسلام أمر بغَسْله.","link":"https://binbaz.org.sa/fatwas/22210/هل-دم-الحيض-نجس-ام-طاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم دم الحيض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":2313,"question":"بالنسبة لطلاق الحائض: سواء كان الرجلُ عالمًا بحيضها أو ..؟","title":"حكم طلاق الحائض عالمًا بحيضها أو جاهلًا","answer":"الجواب:\nبشرط أنه يعلم، وإلا فلا إثم عليه، يقع الطلاق، فلا بد أن يكونا صادقين جميعًا.\nس: ابن عمر حسب الطلقة؟\nج: اجتهادًا منه، وهو قول الجمهور.","link":"https://binbaz.org.sa/fatwas/22437/حكم-طلاق-الحاىض-عالما-بحيضها-او-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلاق الحائض عالما بحيضها أو جاهل.mp3","categories":["الطلاق","الحيض والنفاس","قضايا المرأة"]},{"id":2318,"question":"تقول: كنتُ نُفساء، ووقف عني الدمُ بعد عشرين يومًا، فجامعني زوجي في الليل، وصمتُ في النهار، ثم رجع الدمُ مرةً أخرى، فما الذي عليَّ؟","title":"حكم نفساء انقطع دمُها بعد عشرين ثم رجع","answer":"الجواب:\nما عليها شيء، إذا رجع الدمُ تجلس، لا تُصلي ولا تصوم حتى تَطْهُر أو تُكمِل الأربعين، وما دام الجماعُ حصل في الطَّهارة فلا بأس.","link":"https://binbaz.org.sa/fatwas/22442/حكم-نفساء-انقطع-دمها-بعد-عشرين-ثم-رجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كانت نفساء وانقطع الدمُ بعد عشرين يومًا ثم رجع.mp3","categories":["الحيض والنفاس"]},{"id":2460,"question":"رجل عليه وتر وأراد أن يوتر بركعة واحدة فدخل المسجد ليلاً فهل هذه الركعة إذا أدّاها....؟","title":"حكم تحية المسجد لمَن أراد أن يوتر بواحدة","answer":"الجواب:\nلا، يصلي تحية المسجد أولًا ركعتين ثم يوتر، تحية المسجد ركعتان ثم يوتر بواحدة، السنة ركعتان تحية المسجد، ما زاد فليس من تحية المسجد، تطوع.","link":"https://binbaz.org.sa/fatwas/22589/حكم-تحية-المسجد-لمن-اراد-ان-يوتر-بواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد أن يوتر بواحدة بعد أن دخل المسجد.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":2659,"question":"امرأة حجّت وفي طواف القدوم حاضت..... واستمرت هي في أداء المناسك، وكانت قبل الطواف قد أحست بأعراض الحيض وظنت أنها لم تنزل؛ لأنها كانت تشعر بذلك في أيامها الأخرى ولا يأتيها الحيض إلا بعد يوم، ولكن في الحج اختلف ذلك فما حكم حجها؟","title":"حكم مَن حجّت وفي طواف القدوم حاضت","answer":"الجواب: طواف القدوم بَطَل، ويكفيها طواف الإفاضة، إن شاء الله بعدين تصير قارنة، ما دام أنها دخلت بالحج تصير مفردة، وإن كانت دخلت بعمرة ثم لَبَّت بالحج صارت قارنة، طواف القدوم يكون لاغيًا وسعي القدوم، ويبقى لها طواف الإفاضة بعد الحج.  تكون لها قارنة إن لبت بالحج، وإن كانت دخلت بحج مفرد طوافها بعد الحج يكفيها عن طواف القدوم.  وإن كانت دخلت بعمرة يكفيها طواف الإفاضة ويكون عليها دم إقران، تصير قارنة.  وإن كان زوجها أتاها وهي في العمرة تفسد العمرة، عليها أن تكملها بعد الطهر، وإن كانت ما لها زوج ولا أتاها زوج الحمد لله؛ طواف الحج يكفيها؛ لأنها تختلف: إن كانت ملبية بالعمرة تكون قارنة.  وإن كانت لبت بالحج تكون على حالها حج مفرد، ويكون طوافها لاغيًا الطواف الأول، ويكفيها عن طواف الإفاضة.","link":"https://binbaz.org.sa/fatwas/22795/حكم-من-حجت-وفي-طواف-القدوم-حاضت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من حجت وفي طواف القدوم حاضت.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3365,"question":"المرأة الحائض تُغَسّل الميت؟","title":"هل يجوز للمرأة الحائض تغسيل الميت؟","answer":"الجواب: إذا دعت الحاجة لا بأس، والأمر ما فيه شيء، كَمَيّت، تُغَسّل ميتًا، أو زوجها.","link":"https://binbaz.org.sa/fatwas/23532/هل-يجوز-للمراة-الحاىض-تغسيل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تغسل المرأة الحائض الميت.mp3","categories":["غسل الميت وتجهيزه","الحيض والنفاس","قضايا المرأة"]},{"id":3368,"question":"(الحائض) قراءتها وِرْدها ومراجعتها للقرآن؟","title":"حكم قراءة الحائض للقرآن","answer":"الجواب: قراءتها للورد لا بأس، لكن لا تقرأ القرآن، إنما تقرأ وِرْدَها من غير القرآن، وإن قرأت من حفظها من دون مس لا بأس، الصحيح لا حرج من دون مس المصحف.\nس: تقرأ حفظًا؟\nالشيخ: عن حفظها لا بأس، ما هناك دليل على المنع؛ لأن مدة الحيض تطول، ما هو مثل الجنب، تطول، والنفاس كذلك؛ فإذا قرأت فلا حرج على الصحيح لكن من غير مصحف، لكن لو راجعت المصحف لبعض الآيات من دون حائل من وراء قفازين للحاجة؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/23535/حكم-قراءة-الحاىض-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قراءة الحائض للقرآن.mp3","categories":["الحيض والنفاس","قضايا المرأة","القرآن وعلومه"]},{"id":3373,"question":"المرأة إذا ركّبت \"لولب\" ثم نزل معها دم يسير تكون استحاضة أم يكون حيضًا؟","title":"حكم الدم اليسير الناتج عن \"اللولب\" للنساء","answer":"الجواب: تُراجِع العادة، ما جاء في وقت العادة تترك الصلاة فيه، وما جاء في غير العادة فهو استحاضة دم فساد.\nس: تضطرب عادتها مع هذا؟\nالشيخ: ولَوْ، تُراعِي العادة.","link":"https://binbaz.org.sa/fatwas/23541/حكم-الدم-اليسير-الناتج-عن-اللولب-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أركبت المرأة لولب ثم نزل معها دم، هل تكون استحاضة أم يكون حيضا.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3374,"question":"(المستحاضة) لها أن تَجْمَع؟","title":"هل يجوز للمستحاضة جمع الصلاة؟","answer":"الجواب: ولها أن تَجْمَع إذا دعت الحاجة إلى هذا، لها أن تجمع كما أذِن لحمنة.","link":"https://binbaz.org.sa/fatwas/23542/هل-يجوز-للمستحاضة-جمع-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجمع المستحاضة بين الصلاة.mp3","categories":["الطلاق","الحيض والنفاس","قضايا المرأة"]},{"id":3375,"question":"تضطرب العادة بين أن تكون سبعة أيام في الشهر أربع سنين، ثم تتنقل إلى خمسة عشر يومًا أربع سنين أخرى، هل يحصل هذا للنساء؟","title":"حكم المرأة التي تضطرب عادتها","answer":"الجواب: الله أعلم، قد يقع، قد تتغير العادة.\nس: ما  ينقص عن هذا، والدم إذا زاد لأربع سنين أخرى...؟\nالشيخ: تلزمها العادة، ولا تفرّط، النبي ﷺ أمر بلزوم العادة، أن تلزم عادتها، وما زاد فهو استحاضة؛ تصلي، وتصوم، والحمد لله.\nس: تجمع بين الصلاتين إذا اغتسلت، أو مطلقًا؟\nالشيخ: تغتسل مثلما أمر حمنة رضي الله عنها تغتسل للصلاتين، هذا سنة، والواجب الوضوء، لكن الغسل مستحب.\nس: لكن الجمع؟\nالشيخ: تجمع وتغتسل أفضل إذا شق عليها الأمر.\nس: لها أن تجمع بدون اغتسال؟\nالشيخ: الأفضل الغسل، السنة الغسل، وإلا ما هو بواجب، الواجب عليها غسل الحيض فقط.\nس: لكن سؤالي -أحسن الله إليك- عن الجمع؟\nالشيخ: الجمع مع الغسل أفضل، ولو جمعت بدون غسل صح.","link":"https://binbaz.org.sa/fatwas/23543/حكم-المراة-التي-تضطرب-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المرأة التي تضطرب عادتها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3378,"question":"يقول الفقهاء: إذا زادت أيام العادة على المرأة فإنها تُتْبِعها بالعادة فإنْ فَحُشَت الزيادة كانت مستحاضة، إيش الضابط؟","title":"ما ضابط التمييز بين الحيض والاستحاضة؟","answer":"الجواب: النبي ﷺ أمر المرأة أن تمسك العادة مثل ما قال لأم حبيبة: امكثي قدر ما كانت تحبسك حيضتك ثم اغتسلي، وهكذا أمر فاطمة بنت أبي حبيش، وأمر حمنة كذلك تمسك عادتها، والباقي تصلي وتصوم، ولا يسع النساء إلا هكذا؛ لأنهن يضطربن كثيرًا ما يضطرب عليهن الدم اضطرابًا كثيرًا.\nس: لكن أحسن الله إليكم لو زادت عادتها ثم رأت القصة البيضاء بعد الزيادة، عادتها خمس، ثم زادت ثمان، وترى القصة بعد الثمان؟\nالشيخ: هذا محل نظر، قد يقال إن الزيادة المتصلة التي من جنس دم الحيض قد يقال أنها يعفى عنها... يسيرة، لكن ما ينضبط الأمر ما يضبطه إلا مثل ما قال ﷺ لحمنة ولفاطمة بنت أبي حبيش ولأم حبيبة، كلهن قال لهن: امكثن قدر ما كانت تحبسكن حيضتكن ثم اغتسلن؛ لأن هذا هو الذي يضبطهن.","link":"https://binbaz.org.sa/fatwas/23546/ما-ضابط-التمييز-بين-الحيض-والاستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضابط في الحيض والاستحاضة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3379,"question":"إذا طهرت قبل الفجر بنصف ساعة هل يلزمها أن تصلي المغرب والعشاء؟","title":"حكم المغرب والعشاء لمن طَهُرت قبل الفجر","answer":"الجواب: هذا أفتى به جماعة من الصحابة رضي الله عنهم وأرضاهم، مثل لو طَهُرَت في العصر تصلي الظهر والعصر. هذا، وقت الضرورة، وقت العشاء، وقت الضرورة بعد النصف، من جنس العصر.\nس: فتواكم أنتم فيها؟\nالشيخ: تصلي المغرب والعشاء.","link":"https://binbaz.org.sa/fatwas/23547/حكم-المغرب-والعشاء-لمن-طهرت-قبل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهرت قبل الفجر، فهل تصلي المغرب، والعشاء.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3380,"question":"المرأة: الدم الذي تراه بعد الحيضة، هل يُعتدّ به؟","title":"هل تَعْتَدُّ المرأة بالدم الذي تراه بعد الحيضة؟","answer":"الجواب: لا، يصير دم فساد، بعد العادة؛ تتوضأ لكل صلاة.\nس: ولو كان دم حيض؟\nالشيخ: إذا كان بعد العادة هذه تُبتلى النساء بالدماء، والنبي ﷺ حكم بمراعاة العادة؛ حتى يستريح النساء.","link":"https://binbaz.org.sa/fatwas/23548/هل-تعتد-المراة-بالدم-الذي-تراه-بعد-الحيضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تعتد المرأة بالدم الذي تراه بعد الحيضة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3381,"question":"قول عائشة: لا تَعْجَلْنَ حتى تَرَيْنَ القَّصَّة البيضاء...؟","title":"هل القَّصَّة البيضاء علامة للطُّهر من الحيض؟","answer":"الجواب: لا، ما هو بلازم، القَّصَّة البيضاء غالبًا، وإلا المرأة إذا طَهُرَت يكفي، ولو ما جاءتها القصة البيضاء، بعض النساء ما يرين القصة البيضاء....\nإذا رأت الطهر يكفي، ما بقي شيء، إذا رأت... القطنة ونحوها ما رأت فيها شيئًا؛ فالحمد لله.","link":"https://binbaz.org.sa/fatwas/23549/هل-القصة-البيضاء-علامة-للطهر-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العبرة برؤية الطهر في الحيض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3382,"question":"قال بعض فقهاء الشافعية أن الحائض يجري عليها أجر الصلاة في زمن عادتها لعموم حديث أبي موسى: إذا مرض العبد، أو سافر..؟","title":"هل يَجْرِي للحائض أجر الصلاة فترة عادتها؟","answer":"الجواب: ما هو بعيد، ظاهر الأدلة على ذلك، إذا علم الله مِنْ قلبها أنها لولا الحيض لصلت؛ لها أجر المصلين مثل إذا مرض العبد أو سافر كتب الله له ما كان يعمله وهو صحيح مقيم، ومثل قوله في الصحابة الذين تخلفوا يوم تبوك: ما سلكتم واديًا ولا قطعتم شعبًا إلا وهم معكم، وفي اللفظ الآخر: إلا شركوكم في الأجر، حبسهم العذر، فإذا علم الله من قلب الحائض، والنفساء أنه ما منعها إلا هذا فيرجى لها الأجر الكامل.\nس: حديث: ناقصات دين.\nالشيخ: حديث ناقصات عقل ودين ثابت، لكن ما يَمْنَع.","link":"https://binbaz.org.sa/fatwas/23550/هل-يجري-للحاىض-اجر-الصلاة-فترة-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجري للحائض أجر الصلاة في زمن عادتها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3383,"question":"قول البخاري: باب من اتخذ ثياب الحيض سوى ثياب الطهر؟","title":"حكم اتخاذ ثياب للحيض غير ثياب الطُّهر","answer":"الجواب: لا بأس، من باب النظافة والعناية، ثياب جيدة نظيفة حتى لا يصيبها الدماء.\nس : ما يقال أنه سُنَّة لإقرار النبي ﷺ؟\nالشيخ: مُحْتَمِل.","link":"https://binbaz.org.sa/fatwas/23551/حكم-اتخاذ-ثياب-للحيض-غير-ثياب-الطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتخاذ ثياب الحيض سوى ثياب الطهر.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3384,"question":"هل (المستحاضة) يكفيها الوضوء لكل صلاة؟","title":"هل تتوضأ المستحاضة لكل صلاة؟","answer":"الجواب: نعم؛ يكفيها الوضوء لكل صلاة.","link":"https://binbaz.org.sa/fatwas/23552/هل-تتوضا-المستحاضة-لكل-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتوضأ المستحاضة لكل صلاة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3389,"question":"قول ابن عباس: (تغتسل وتصلي، ولو ساعة) يعني ولو طهرت ساعة واحدة بس؟","title":"معنى (تغتسل وتصلي ولو ساعة) للحائض","answer":"الجواب: متى رأت الطهارة يعني، الطهارة العادية.\nس: ولو ساعة؟\nالشيخ: ولو، إذا رأت الطهارة تغتسل وتصلي، هذا المراد.\nس: وإذا عاودها الدم يعني؟\nالشيخ: في العادة تجلس ثم إن كان في غير العادة لا، دم استحاضة.","link":"https://binbaz.org.sa/fatwas/23557/معنى-تغتسل-وتصلي-ولو-ساعة-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقول بن عباس (تغتسل وتصلي، ولو ساعة).mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3390,"question":"رأت المرأة الطهر في أيام عادتها: هل تجلس وتصلي؟","title":"حكم رؤية المرأة الطُّهر في أيام عادتها","answer":"الجواب: تصلي وتصوم إذا رأت الطهر.  مَنْ عَادَتُها ست، وبعد ثلاثٍ رأت الطهارة؛ تغتسل وتصلي وتصوم، فإذا عاد في الست؛ تجلس.","link":"https://binbaz.org.sa/fatwas/23559/حكم-روية-المراة-الطهر-في-ايام-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إذا رأت المرأة الطهر في أيام عادتها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3392,"question":"سائل يسأل يقول: امرأة يأتيها دم أسود يستمر معها ستة أيام قبل حيضها، ثم يأتيها حيضها لمدة سبعة أيام، فهل تصلي وتصوم في الأيام الأُوَل؟","title":"حكم مَنْ يأتيها دم أسود قبل حيضها متصل به","answer":"الجواب: وهو منفصل؟ عادة لها يأتيها هذا متصل مع الحيض؟\nالطالب: الدم أسود ستة أيام قل حيضها، ثم يأتيها حيضها سبعة أيام.\nالشيخ: بينهما فاصل؟\nس: ظاهر سؤاله أنه متصل.\nالشيخ: يأتي يسألني، يحتاج تأمل هذا، إن كان عادة لها كذا فهو عادة لها، وإن كان عارضًا لا، العمدة على عادتها، فإن كان عادة لها مستقيمة: أول الست أسود، ثم بقيته أحمر، مدة مستمرة، تكون عادة لها.\nس: طيب، وإذا كان منفصلًا؟\nالشيخ: إذا كان عارضًا لا، ما يصير عادة لها إذا كان عارض يكون من الاستحاضة.\nس: العارض يصلح عندكم، لو زادت العارض يوم؟\nالشيخ: الذي ما هو بعادة لها يعني.  \nس: أقول عادتها سبعة، ولكن في مرة اتصلت ثمانية، أو ...؟\nالشيخ: ما يضر إذا كان متصل ما بان شيء الأمر سهل لأن عادة النساء تزيد وتنقص كما قالت عائشة: \"لا تَعْجَلن\" لما عرضوا عليها الآثار.","link":"https://binbaz.org.sa/fatwas/23561/حكم-من-ياتيها-دم-اسود-قبل-حيضها-متصل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المرأة التي يأتيها دم أسود قبل حيضها ثم يأتيها حيضها.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3393,"question":"وطء الحائض إذا طهرت قبل الاغتسال؟","title":"حكم وطء الحائض إذا طهرت قبل الاغتسال","answer":"الجواب: لا ما يجوز فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ [البقرة: 222] حتى تطهر فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ [البقرة: 222].\nس: والحالة هذه يلزمها الكفارة؟\nالشيخ: إذا وطأها قبل الغسل نعم.","link":"https://binbaz.org.sa/fatwas/23562/حكم-وطء-الحاىض-اذا-طهرت-قبل-الاغتسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وطء الحائض إذا طهرت قبل الاغتسال.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":3424,"question":"الدم الذي يَسْبِق السَّقْط بأسبوع هل له حكم النفاس؟","title":"ما حكم الدم الذي يَسْبِق السَّقْط بأسبوع؟","answer":"الجواب: لا، ليس له حكم النفاس، دم فساد هذا، إلا الذي مع الطَّلْق.","link":"https://binbaz.org.sa/fatwas/23598/ما-حكم-الدم-الذي-يسبق-السقط-باسبوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدم الذي يسبق السقط بأسبوع هل له حكم النفاس.mp3","categories":["الحيض والنفاس"]},{"id":4415,"question":"المقدار الذي يُتجاوز عنه في الحيض؟","title":"هل يُعفى عن شيء في غسل دم الحيض؟","answer":"الجواب: ما في شيء، النبي ﷺ أمر بغسله كله، ولهذا قال المؤلفُ نبَّه أنه لا يُجزئ عن شيءٍ، بل يجب غسله كله ولو قليلًا، التي مع الحيض يجب غسلها.  إنما يُعفى عن الشيء القليل، مثل: الرعاف، مثل: دم الأسنان، مثل: ما يحصل من العين فيها بعض السيل قليلًا، جراحات قليلة، يُعفى عن اليسير، أما الحيض فأمر النبي بغسله كله.","link":"https://binbaz.org.sa/fatwas/24692/هل-يعفى-عن-شيء-في-غسل-دم-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعفى عن شيء من دم الحيض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4467,"question":"الاستدلال بحديث عائشة: افعلي ما يفعل الحاج إلا أن تطوفي بالبيت على جواز مسّ المصحف بغير طهارة؟","title":"(افعلي ما يفعل الحاج) هل يعمّ مسّ المصحف؟","answer":"الجواب: ما هو بكفء، هذا عام مخصوص، أقول: عام مخصوص، العمومات ما تنقض الخاص، ولا تُبطل الخاص.","link":"https://binbaz.org.sa/fatwas/24745/افعلي-ما-يفعل-الحاج-هل-يعم-مس-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستدلال بحديث افعلي ما يفعل الحاج، إلا أن تطوفي بالبيت على جواز مسّ المصحف.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":4472,"question":"جلوس الحائض في الحرم للضَّرورة؟","title":"حكم جلوس الحائض في الحرم للضَّرورة","answer":"الجواب: الضرورة لها أحكامها، إذا كانت مثلًا ضاعت عن أهلها وتخشى...\nس: إذا كان جماعة معهم حائض، ويأتون الحرم ويتركونها...؟\nج: إذا كانت ضرورةً لا حرج إن شاء الله.","link":"https://binbaz.org.sa/fatwas/24750/حكم-جلوس-الحاىض-في-الحرم-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جلوس الحائض في الحرم للضَّرورة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4475,"question":"المُستحاضة إذا كانت لها عادة مكثت حسب عادتها، وإن لم تكن لها عادة تمكث؟","title":"كم تمكث المستحاضة إذا لم تكن لها عادة؟","answer":"الجواب: ستة أيام، أو سبعة أيام .....؛ لأنَّ عادة النساء غالبًا ستّ، سبع، هذا الغالب.","link":"https://binbaz.org.sa/fatwas/24754/كم-تمكث-المستحاضة-اذا-لم-تكن-لها-عادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المستحاضة إذا لم تكن لها عادة.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4481,"question":"نقض الشعر لغسل الحيض يجب؟","title":"حكم نقض الشعر لغسل الحيض","answer":"الجواب: لا، مُستحبٌّ فقط، ولهذا في حديث أم سلمة عند مسلم: \"أفأنقضه من الحيض؟\" قال: لا، إنما يكفيك أن تحثي.","link":"https://binbaz.org.sa/fatwas/24761/حكم-نقض-الشعر-لغسل-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نقض الشعر لغسل الحيض.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":4486,"question":"إذا كانت المرأةُ عادةً تحيض سبعًا... ثم خالفت فحاضت في شهرٍ ؟","title":"ما تفعل من اختلف عدد أيام حيضها عن عادتها","answer":"الجواب: لا، تجلس لا تُصلي ولا تصوم، تجلس لأجل الزيادة لا تُصلي ولا تصوم .....، وهكذا لو كانت عادتها سبعًا ثم رأت الطَّهارة بعد خمسٍ تغتسل.","link":"https://binbaz.org.sa/fatwas/24766/ما-تفعل-من-اختلف-عدد-ايام-حيضها-عن-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من اختلف عدد أيام حيضها زيادةً أو نقصانًا.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4487,"question":"مباشرة الحائض الأولى تركه؟","title":"حكم مباشرة الحائض","answer":"الجواب: لا بأس بمُباشرتها، كان النبيُّ يُباشرها ﷺ، كانت تنام معه.\nس: كأن الأصل الترك؟\nج: ذاك ما تحت الإزار، ترك ما تحت الإزار أولى، يعني: ينام معها وتلبس الإزار أو السراويل من غير تعرية كاملة.","link":"https://binbaz.org.sa/fatwas/24767/حكم-مباشرة-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مباشرة الحائض.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":4488,"question":"إذا طهرت يا شيخ بأقل من أربعين ثم بعد ذلك رجع الدمُ يسيرًا؟","title":"حكم نفساء طهرت لأقل من أربعين ثم رأت دمًا","answer":"الجواب: اختلف العلماء في ذلك، والصواب أنه يكون نفاسًا، إذا رجع في الأربعين فهو نفاس حتى تكمل، لا تُصلي ولا تصوم.\nس: ما زاد على المدة؟\nج: نعم؟\nس: ما زاد على الأربعين ووافق عادةً؟\nج: يكون عادةً.\nس: يكون من عادتها؟\nج: يكون من عادة الحيض.","link":"https://binbaz.org.sa/fatwas/24768/حكم-نفساء-طهرت-لاقل-من-اربعين-ثم-رات-دما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النفساء إذا طهرت بأقل من أربعين ثم رجع الدمُ يسيرًا.mp3","categories":["الحيض والنفاس"]},{"id":4550,"question":"مكوث النساء في الحرم الآن؟","title":"حكم مكوث النساء في الحرم","answer":"الجواب: النساء كذلك إن كان ما في ضرر، مع التَّستر ومع البُعد عن الفتنة فلا بأس، كما في قصة سعد بن معاذ لما أُصيب في أكحله يوم الخندق ضرب عليه النبيُّ ﷺ خيمةً في المسجد، وكان في المسجد أيضًا امرأة لها خيمة، عندها خيمة في المسجد، ما لها أهل، وأقرَّها النبيُّ في المسجد عليه الصلاة والسلام.  فإذا دعت الحاجةُ إلى ذلك فلا بأس، لكن تكون في محلٍّ مستورٍ .....، وكان بعض نساء النبي ﷺ يعتكفن في المسجد في خيام مستورة، فإذا كان وجود المرأة في المسجد لا ضررَ فيه كخيمةٍ خاصةٍ ..... خاصة، ودعت الحاجةُ إلى ذلك فلا حرج في ذلك .......، لكن لا بد [من] الحذر من إيذاء المسجد، حتى ولو كان بعض الناس يُقيم الأعياد في المساجد، أدركت هذا في هذه البلاد وفي غيرها، يوم العيد يُقدِّمون الطعام في المسجد؛ لأنهم ما عندهم مساكن تتسع للناس .....، فالمسجد أوسع، فإذا جعلوه للطعام وأكلوا فلا بأس عند الحاجة، لكن إذا ..... ألا يقع في المسجد فيه من الأكل.","link":"https://binbaz.org.sa/fatwas/24830/حكم-مكوث-النساء-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مكوث النساء في الحرم.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":4610,"question":"صلاة المرأة في المسجد الحرام أفضل من صلاتها في بيتها؟","title":"هل صلاة المرأة في الحرم أفضل من بيتها؟","answer":"الجواب: بيتها أفضل، وإن صلَّت في المسجد الحرام متأدبةً بدون تجمُّلٍ ولا طيبٍ ولا شيءٍ من المحظورات فلا بأس.","link":"https://binbaz.org.sa/fatwas/24899/هل-صلاة-المراة-في-الحرم-افضل-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما أفضل للمرأة صلاتها في المسجد الحرام أم في بيتها.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":4646,"question":"لو أحرمت المرأةُ بالعمرة ثم جاءها الحيضُ وأرادت أن ترجع إلى بلدها بدون عمرةٍ، يلزمها دمٌ؟","title":"حكم من حاضت في العمرة وتريد الرجوع لبلدها","answer":"الجواب: ليس لها ذلك، لا بد أن تكمل عمرةً، بعدما تطهر تكمل العمرة، تبقى في مكة حتى تكمل، فإن اضطرَّت للخروج تخرج إلى جدة، إلى الطائف، ثم ترجع وتُكمل، إذا صارت مشقة على أوليائها يخرجون إلى جدة أو الطائف أو غيرهما ثم يرجعون.\nس: وإذا خرجت عليها دم؟\nج: لا، ما عليها شيء، ترجع فقط وتكمل، عليها أن تأتي وتُكمل عمرتها.","link":"https://binbaz.org.sa/fatwas/24936/حكم-من-حاضت-في-العمرة-وتريد-الرجوع-لبلدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أحرمت بالعمرة ثم جاءها الحيضُ وأرادت الرجوع إلى بلدها بدون عمرةٍ.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":4672,"question":"المرأة التي تخاف على نفسها العادة هل تشترط عند إحرامها؟","title":"هل تشترط المرأة عند إحرامها إن خافت العادة؟","answer":"الجواب: ما أعلم مانعًا، أما في الحجِّ لا؛ لأنها تنتظر؛ لأنَّ الحجَّ لا بد من الطواف فيه. الحيض محل نظر.. ، لكن ليس ببعيدٍ؛ لأنه قد يُعطلها كثيرًا.  قد يُقال بالحج أيضًا إذا كانت جاءت مُتأخرةً أو متقدمةً، يمديها تطهر، لكن قد تأتي متأخرةً وتخشى من التَّعطيل، وتفوت عليها أشياء، المقصود إذا دعت حاجةٌ إلى الاشتراط لا بأس، الأصل الجواز، النبي قال لضباعة وهي مريضة: حُجِّي واشترطي.","link":"https://binbaz.org.sa/fatwas/24964/هل-تشترط-المراة-عند-احرامها-ان-خافت-العادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تشترط المرأة عند إحرامها إن خافت على نفسها العادة.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":4694,"question":"الحائض تسعى مع دخول المسعى المسجد الحرام؟","title":"حكم سعي الحائض","answer":"الجواب: ولو، ولو، لا بأس، تسعى ولو أنها على غير طهارةٍ، إذا صار الطواف وهي طاهرة فالحمد لله تسعى، ولو أنَّ المسعى داخلٌ ما يضرُّ.","link":"https://binbaz.org.sa/fatwas/24986/حكم-سعي-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في سعي الحائض.mp3","categories":["الحيض والنفاس","السعي","قضايا المرأة"]},{"id":4695,"question":"لو قدَّمت المرأةُ السعي على الطَّواف؟","title":"ما حكم مَنْ قدَّمت السعي على الطَّواف؟","answer":"الجواب: المشروع أن تبقى حتى تطوف، السعي بعد الطواف، وهو يُجزئ على الصحيح، لكن المشروع لها أن تبقى حتى تطهر ثم تطوف وتسعى.\nوصحَّ عنه ﷺ أنه سئل: يا رسول الله، سعيتُ قبل أن أطوف؟ قال: لا حرج، لكن السنة أن المؤمن يطوف ثم يسعى كما فعله النبيُّ ﷺ، والحائض تبقى حتى تطهر، فإذا طهرت طافت وسعت.\nس: حديث السائل ما هو خاصّ بتقديم السعي في الحج؟\nج: الرسول لم يستفصل السائل.","link":"https://binbaz.org.sa/fatwas/24987/ما-حكم-من-قدمت-السعي-على-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم لو قدَّمت المرأةُ السعي على الطَّواف.mp3","categories":["السعي","الحيض والنفاس","قضايا المرأة"]},{"id":4768,"question":"سورة تبارك شفعت لرجل لقراءته أو لحفظه؟","title":"ما معنى ما جاء أن سورة تبارك تشفع لصاحبها؟","answer":"لقراءتها والعمل بها، العمل بما فيها، يعني مع الاستقامة على طاعة الله ورسوله.","link":"https://binbaz.org.sa/fatwas/25129/ما-معنى-ما-جاء-ان-سورة-تبارك-تشفع-لصاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى سورة تبارك شفعت لرجل.mp3","categories":["شروح الحديث","القرآن وعلومه","الحيض والنفاس"]},{"id":4954,"question":"بالنسبة للصفرة والكدرة لو اتصلت بالعادة، من أول العادة صفرة، وكدرة؟","title":"حكم الصفرة والكدرة إذا اتصلت بالعادة","answer":"الجواب: كذلك، إذا كان أول العادة صفرة وكدرة، أو آخرها صفرة وكدرة؛ تصير تبع العادة.\nس: وإذا أتاها الدم بعد الصفرة والكدرة؟\nالشيخ: إذا كان متصلًا يصير عادة لها، النبي ﷺ قال للمستحاضة: امكثي قدر ما كانت تحبسك حيضتك ثم اغتسلي، وكل من شكت إليه، قال: امكثي قدر ما كانت تحبسك حيضتك ثم اغتسلي، وهذا هو الذي ينضبط، فيهن من ينضبط، إذا طال آخر أيامها أما زود يوم أو يومين؛ فهذا يقع للنساء، لا يعجلن حتى يرين الطهر.","link":"https://binbaz.org.sa/fatwas/27525/حكم-الصفرة-والكدرة-اذا-اتصلت-بالعادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصفرة والكدرة إذا اتصلت بالعادة.mp3","categories":["الحيض والنفاس"]},{"id":4958,"question":"هل الكُدْرَة والصُّفْرَة تكون علامة للطُّهر إذا توقف الدم؟","title":"هل الكُدْرَة والصُّفْرَة تكون علامة للطُّهر؟","answer":"الجواب: إذا رأت الصُّفرة بعد الطُّهر ما عليها، هذا مثل البَوْل؛ تَسْتَنْجي وتتوضأ لكل صلاة.","link":"https://binbaz.org.sa/fatwas/27561/هل-الكدرة-والصفرة-تكون-علامة-للطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الكُدْرَة والصُّفْرَة تكون علامة للطُّهر؟.mp3","categories":["الحيض والنفاس"]},{"id":4975,"question":"يقول: هل يصح الغسل من الجنابة إذا كانت الأصابع فيها طلاء؟","title":"حكم الطلاء والجبيرة عند الغُسل والوضوء","answer":"الجواب: إذا كان عليها شيء يُزال، مناكير أو غيره، الملصوقات التي تكون عبثًا ما هي بضرورة تُزال، أما الجبيرة يُمِر عليها الماء، لكن إذا كانت لُصوقات مناكير أو أشياء لصقت بالجلد طين أو عجين يُزال في الغسل والوضوء جميعًا. \nأما إذا كان لعِلة دواء جرح، لعلة أو جبيرة، لاـ يُمِر عليه الماء ويكفي، أو يمسح إذا كان ما يستطيع الماء، يمسح ويكفي مثل ما في الوضوء، أما إذا كانت لُصوقات ما لها لزوم مناكير أو عجين أو طين أو أشباه ذلك؛ فهذه تُزال في الغسل وتُزال في الوضوء جميعًا.","link":"https://binbaz.org.sa/fatwas/28044/حكم-الطلاء-والجبيرة-عند-الغسل-والوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الطلاء والجبيرة عند الغسل والوضوء.mp3","categories":["الغسل","الحيض والنفاس","قضايا المرأة"]},{"id":5182,"question":"ماذا يجوز للرجل من زوجته أيام الحيض؟","title":"ماذا يجوز للرجل من زوجته أيام الحيض؟","answer":"الجواب: يجوز للرجل من زوجته كل شيءٍ إلا الجماع، قال النبيُّ ﷺ: اصنعوا كل شيءٍ إلا النكاح، لما قالوا له ﷺ: إنَّ اليهود لا يُجامعون المرأة إذا كانت حائضةً في البيوت، لا يُجامعوها في البيوت يعني: لا يُساكنونها، ولا يأكلون معها، ولا يشربون معها، فقال عليه الصلاة والسلام: اصنعوا كل شيءٍ إلا النكاح، وأنزل الله في ذلك: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ [البقرة:222] يعني: الجماع، أما كونه يُضاجعها وينام معها ويُقبّلها ويضمّها إليه فلا بأس بذلك، إلا الجماع فقط. وكانت عائشة رضي الله عنها تشرب من الإناء، ثم يأخذه النبيُّ ﷺ ويضع فمه في موضع فمها، وتتعرّق العظم فيأخذ ذلك أيضًا ويتعرّقه؛ تطييبًا لقلبها، وإيناسًا لها، ومُداعبةً لها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/30118/ماذا-يجوز-للرجل-من-زوجته-ايام-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 144.mp3","categories":["الحقوق الزوجية","الحيض والنفاس"]},{"id":5253,"question":"أحسن الله إليكم، أخت تسأل وتقول: ما حكم قراءة القرآن للحائض والنُّفساء، وأحيانًا يُصادف الامتحان مثل هذه الحالات؟","title":"حكم قراءة القرآن للحائض والنفساء للاختبار","answer":"الجواب: فيه خلافٌ بين أهل العلم، والصواب أنه يجوز للحائض أن تقرأ القرآنَ عن ظهر قلبٍ، والنفساء كذلك، ولا يجوز أن تُقاس عليها الجنب، والجنب يتيسر له الاغتسال بسرعةٍ ويقرأ، لكن الحائض والنفساء ليستا كذلك، ليستا مثله، لهن مدَّة، ليس الأمر بأيديهن. فالصواب أنه يجوز لهنَّ قراءة القرآن عن ظهر قلبٍ، وهكذا قراءة القرآن من المصحف من وراء حائلٍ أو قفَّازين عند الحاجة إلى ذلك: كمُراجعة مَن تغلط فيه عند الامتحان ونحو ذلك. أما حديث لا يقرأ القرآنَ الحائضُ والجنبُ فهو حديثٌ ضعيفٌ عند أهل العلم، والصواب أنَّ هذا خاصٌّ بالجنب، كان النبي ﷺ لا يحجزه شيءٌ عن القرآن إلا الجنابة، فلا يُقاس على الجنبِ الحائضُ والنفساء؛ لأنهما ليستا مثله، وهما في حاجةٍ إلى قراءة القرآن عن ظهر قلبٍ، وإلى مُراجعته عند الامتحان والاختبار، ولئلا تنساه الحائض والنفساء، ولكن يجوز بواسطة حائلٍ: قفَّازين ونحوهما.","link":"https://binbaz.org.sa/fatwas/30749/حكم-قراءة-القران-للحاىض-والنفساء-للاختبار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 988.mp3","categories":["الحيض والنفاس","قضايا المرأة","القرآن وعلومه"]},{"id":5362,"question":"امرأة حامل بتوأمين: أحدهما تُوفي وعمره في بطن أمه ثلاثة أشهر، ولكنه سقط من بطن أمه بعد الشهر الرابع، ولم يتبين فيه خلق الإنسان، وبقي الآخر في بطن أمه، فهل الدم النازل مع هذه المرأة دم نفاسٍ أم دم فسادٍ؟","title":"هل تكون نفساء مَنْ أسقطت في الشهر الرابع؟","answer":"الجواب: إذا كان قد تخلَّق فهو دم نفاسٍ، إذا كان قد بانت فيه يد أو رجل أو شيء فهو دم نفاسٍ، أما إذا كان مجرد دم ..... ثلاثة أشهر، ولكن ما بان شيء: لا يد، ولا رجل، ولا رأس، فهذا يُعتبر دم فسادٍ؛ تُصلي وتصوم وتتوضأ لكل صلاةٍ كالمستحاضة. س: الضَّابط في هذا التَّخلق؟ ج: وجود ما يدل على أنه جنين حتى يصير نفاسًا: من رأسٍ أو يدٍ أو رجلٍ أو نحو ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31072/هل-تكون-نفساء-من-اسقطت-في-الشهر-الرابع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima006.mp3","categories":["الحيض والنفاس"]},{"id":5577,"question":"الحائض أليس لها أن تقرأ القرآن؟","title":"هل للحائض أن تقرأ القرآن الكريم؟","answer":"الجواب: فيه خلاف بين أهل العلم: الشيخ تقي الدين رحمه الله وجماعة قالوا: إن خشيت نسيانه قرأت، أو وجبت عليها القراءة على أحد القولين. والأقرب والله أعلم أنها تقرأ؛ لأنها مدتها تطول، مدة الحيض والنفاس تطول، ما هي مثل الجُنُب، ولا تُقاس الحائض على الجنب، فالأقرب والله أعلم أنها تقرأ عن ظهر قلبٍ، هذا هو الأرجح من حيث الدليل؛ تقرأ عن ظهر قلبٍ، وإذا دعت الحاجةُ إلى مراجعة المصحف تُراجعه من وراء قفازين، من وراء حائل، ولا يجوز قياسها على الجنب، الجنب مدته يسيرة، يغتسل وينتهي، والقياس في هذا لا وجهَ له. أما حديث: لا تقرأ الحائضُ ولا الجنبُ شيئًا من القرآن فحديث ضعيف؛ لأنه من رواية إسماعيل بن عياش، عن موسى بن عقبة، وإسماعيل عن الحجازيين ضعيف عند أهل العلم، والقياس فاسد. س: إذا أُبيح لها قراءة القرآن فلماذا لا يُباح لها مسّ المصحف من غير حائلٍ؟ ج: الرسول ﷺ نهى عن مسِّ المصحف لمن عليه حدث، فكيف بالحدث الأكبر؟! مسّ المصحف ممنوع لمن كان عليه حدثٌ أصغر، فالذي عليه حدث أكبر من باب أوْلى. س: الذي يُروى عن حذيفة في تجويز قراءة الحائض والنُّفساء؟ ج: ما أتذكر شيئًا، أقول: ما أعلم شيئًا، لكن الصواب جواز ذلك؛ لأنَّ القياس فاسد، قياسها على الجنب ما يصلح، وليس في النص ما يمنعها، لكن من دون حائلٍ، إذا احتاجت مسَّه يكون من دون حائلٍ.[1]","link":"https://binbaz.org.sa/fatwas/31529/هل-للحاىض-ان-تقرا-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 017.mp3","categories":["الحيض والنفاس"]},{"id":5753,"question":"امرأة حجت متمتعة، وبعد أن قضت العمرة حاضت، وبعد الإفاضة من عرفات طافت بالبيت وهي حائض، فماذا عليها وهي في الثامنة عشرة من عمرها؟","title":"من طافت الإفاضة وهي حائض","answer":"الجواب: عليها أن تعيد الطواف، إذا طافت الحائض تعيد الطواف بنية الحج السابق، تعود إلى مكة مع محرمها، وتطوف طواف الحج بنية الحج السابق الذي مضى، تطوف بطهارة.","link":"https://binbaz.org.sa/fatwas/1095/من-طافت-الافاضة-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_101.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":5769,"question":"امرأة حجت متمتعة، وبعد أن قضت العمرة حاضت، وبعد الإفاضة من عرفات طافت بالبيت وهي حائض، فماذا عليها وهي في الثامنة عشرة من عمرها؟","title":"من طافت الإفاضة وهي حائض","answer":"الجواب: عليها أن تعيد الطواف، إذا طافت الحائض تعيد الطواف بنية الحج السابق، تعود إلى مكة مع محرمها، وتطوف طواف الحج بنية الحج السابق الذي مضى، تطوف بطهارة.","link":"https://binbaz.org.sa/fatwas/1095/من-طافت-الافاضة-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_101.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":5824,"question":"آمل شرح كيفية تكفين الميت بالنسبة للرجل، والأنثى؟","title":"كيفية تكفين الميت رجلا وأنثى","answer":"الجواب: السنة أن يكفن الرجل في ثلاثة أثواب بيض، هذه السنة كما كفن بها النبي ﷺ، وإن كفن في ثوب واحد، ورأسه يعمه، ويستره كفى، وإن كفن في قميص، وإزار، ولفافة جاز، فليس في التكفين حد محدود. إذا كفن في لفافة واحدة، أو لفافتين، أو ثلاث، أو في قميص ولفافة، أو في قميص وإزار ولفافة كله جائز، والحمد لله كله واسع.  ولكن الأفضل مثل ما كفن النبي ﷺ مثل ما أجرى الله لنبيه ﷺ كفنه الصحابة في ثلاث لفائف بيض، أدرج فيها إدراجًا هذا هو الأفضل، وإن كفن في ثوبين، أو في واحد، أو في قميص وإزار؛ فلا بأس. كذلك المرأة تكفن في ثوب واحد يسترها، في لفافة واحدة تسترها، أو في مدرعة ولفافة، أو في مدرعة وإزار ولفافة كله جائز.  وإذا كفنت في خمسة: إزار وخمار وقميص ولفافتين فهذا هو الأفضل، كما ذكر أهل العلم، وجاء في بعض الأخبار الدالة على ذلك.  هذا هو أفضل ما يكون قميص وإزار وخمار ولفافتين للمرأة، وإن كفنت في ثوب واحد، يعني لفافة واحدة يسترها كلها، أو في لفافتين، أو في قميص ولفافة، أو في قميص وخمار ولفافة، فكله طيب، ما في حد محدود، والأمر في هذا واسع.","link":"https://binbaz.org.sa/fatwas/1163/كيفية-تكفين-الميت-رجلا-وانثى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_162.mp3","categories":["غسل الميت وتجهيزه","الحيض والنفاس","قضايا المرأة"]},{"id":5842,"question":"إذا نفست المرأة، ثم طهرت في عشرة أيام، ثم بعد ذلك بأربعة أيام رأت الصفرة، أو الكدرة، فهل تترك الصلاة، أم تستمر، ولا تعد هذه الصفرة شيء، مع العلم أنها في أيام الأربعين؟","title":"حكم الصفرة والكدرة بعد الطهر","answer":"الجواب:  إذا رأت المرأة الطهر بعد عشرة أيام من النفاس، أو بعد خمسة عشر يومًا، أو عشرين يومًا في النفاس؛ فإنها تطهر، وتغتسل، وتصلي، وتحل لزوجها، ولو ما مضى عليها إلا عشرة أيام، إذا طهرت طهارة كاملة، ماء أبيض، أو احتشت بقطن، ونحوه، وخرج نظيفًا؛ فإنها تغتسل، وتصلي، وتصوم، وتحل لزوجها، ولو أنه ما مضى عليها إلا عشرة أيام، أو خمسة عشر يومًا، أو عشرين يومًا؛ لا بأس.  وهكذا الحائض إذا كانت عادتها سبعًا، ثمان، ثم رأت الطهر بعد ثلاثة أيام، أو بعد أربعة أيام؛ تغتسل، وتصلي، والحمد لله؛لأن الدم يزيد، وينقص، ويطول، ويكثر في الحيض، والنفاس. أما إذا رأت صفرة بعد ذلك؛ طهرت طهارة كاملة، ثم رأت صفرة، أو كدرة؛ فإن الصواب أنه لا يعتد بذلك، قالت أم عطية -رضي الله عنها-: \"كنا لا نعد الكدرة، والصفرة بعد الطهر شيئًا\" وقال بعضهم: إلا في وقت العادة، وقت النفاس، ولكن ليس بجيد.  فالصواب: العموم، وأن الصفرة، والكدرة بعد الطهارة لا تعد شيئًا، فلها أن تصلي، وتصوم، وتعتبر الصفرة، والكدرة، كالبول؛ تتنظف منها، وتستنجي منها، ويكفي.","link":"https://binbaz.org.sa/fatwas/1181/حكم-الصفرة-والكدرة-بعد-الطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_177.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":5864,"question":"إذا حاضت المرأة بعد دخول وقت الصلاة، فهل تقضي هذه الصلاة بعد طهرها؟","title":"حكم من حاضت بعد دخول وقت الصلاة","answer":"الجواب: فيه اختلاف بين العلماء، منهم من قال: تقضي، ومنهم من قال: لا تقضي، ومنهم من قال: إذا ضاق الوقت، وتأخرت؛ فقد فرطت، وعليها القضاء، وإذا كان جاء الحيض في أثناء الوقت، أو في أول الوقت، فلم تفرط؛ فالأقرب أنها لا تقضي إلا إذا كنت مفرطة، يعني ضيعت الصلاة، أخّرتها حتى ضاق الوقت، فهذه تقضي على كل حال.  أما إذا كانت ما فرطت، ولكن جاءها الحيض في أثناء الوقت، وهي لم تفرط؛ فالأمر في هذا واسع، إن قضت كما قال بعض العلماء؛ فلا بأس، وإن لم تقضِ؛ فلا حرج -إن شاء الله- لتعدم التفريط.  لكن إذا جاء الطهر في الوقت هذه تقضي على كل حال، إذا طهرت في العصر؛ فإنها تصلي الظهر، والعصر جميعًا، طهرت في العشاء؛ تصلي المغرب، والعشاء جميعًا، أفتى بهذا ابن عباس، وعبدالرحمن بن عوف من الصحابة، وجماعة آخرون من أهل العلم؛ لأنها أدركت الوقت، فتصلي إذا طهرت في العصر تضم إليها الظهر؛ لأنهما وقتان كالوقت الواحد عند العذر، وهكذا إذا طهرت في العشاء تضم إليه المغرب، وتقضيهما جميعًا؛ لأنهما وقت واحد للمعذور.","link":"https://binbaz.org.sa/fatwas/1191/حكم-من-حاضت-بعد-دخول-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_187.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":5877,"question":"لو أنزل المذي يا شيخ؟","title":"حكم خروج المذي والمني من الصائم","answer":"الجواب: المذي ما يضر على الصحيح، المذي ما يضر على الصحيح؛ لأنه يخرج سريعًا، وليس مثل المني، المذي شيء يخرج من الذكر عند تحرك الشهوة، وهو لا يضر الصيام على الصحيح، بعض العلماء يقول: إنه يفطر الصائم، ولكن الصحيح أنه لا يفطر الصائم، ولا يضر. السؤال: الأخ يقول: لو أمنى؟ الجواب: إذا أمنى عليه الإعادة، يفطره المني، وعليه أن يعيد ذلك اليوم، يقضيه، ولا عليه كفارة. الكفارة في الوطء، أما من سبقه المني بسبب العادة السرية -والعياذ بالله- أو بسبب أنه قبلها، وهو سريع المني؛ فإنه يقضي ذلك اليوم، وليس عليه كفارة، ولكن عليه القضاء، والحذر في المستقبل من التساهل في هذا الأمر.","link":"https://binbaz.org.sa/fatwas/1217/حكم-خروج-المذي-والمني-من-الصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_214.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":5908,"question":"هل الحجامة تفسد الصوم، أم هي منسوخة؟","title":"حكم الاحتجام للصائم","answer":"الجواب: هذا فيه خلاف بين أهل العلم، منهم من رآها تبطل الصوم لحديث أفطر الحاجم والمحجوم، ومنهم من رآها لا تفطر لحديث أنس وغيره أنه كانوا لا يكرهونها إلا من أجل الضعف. وقد اختلف العلماء في ذلك، والمشهور أنها تفطر الصوم، وأن آخر الأمرين من النبي ﷺ أنها تفطر الصائم، ولكن الخلاف قائم فيها، والحجة من الجانبين قوية؛ فالأولى من المؤمن أن يتباعد عنها أثناء الصيام، يحتاط لدينه، ولا يحتجم إلا في الليل.","link":"https://binbaz.org.sa/fatwas/1241/حكم-الاحتجام-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_238.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":6005,"question":"إذا كانت المرأة على جنابة، وقبل أن تغتسل أتتها الحيضة، فما الحكم، هل تغتسل للجنابة، أم تنتظر حتى تتطهر؟","title":"حكم من حاضت وهي على جنابة لم تغتسل منها","answer":"الجواب:  إذا كانت المرأة على جنابة، ثم أتاها الحيض؛ فهي بالخيار، إن شاءت أخرت الغسل عنهما جميعًا؛ لأنها لا تصلي مع الحيض، وإن شاءت بادرت بغسل الجنابة، وهو أحسن، وأولى، ويبقى غسل الحيض فقط، تغتسل من الجنابة حتى يخف الحدث، ويبقى عليها غسل الحيض بعد انقطاع الدم، هذا هو الأولى.","link":"https://binbaz.org.sa/fatwas/1400/حكم-من-حاضت-وهي-على-جنابة-لم-تغتسل-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_355.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":6008,"question":"إذا كانت المرأة على جنابة، وقبل أن تغتسل أتتها الحيضة، فما الحكم، هل تغتسل للجنابة، أم تنتظر حتى تتطهر؟","title":"حكم من حاضت وهي على جنابة لم تغتسل منها","answer":"الجواب:  إذا كانت المرأة على جنابة، ثم أتاها الحيض؛ فهي بالخيار، إن شاءت أخرت الغسل عنهما جميعًا؛ لأنها لا تصلي مع الحيض، وإن شاءت بادرت بغسل الجنابة، وهو أحسن، وأولى، ويبقى غسل الحيض فقط، تغتسل من الجنابة حتى يخف الحدث، ويبقى عليها غسل الحيض بعد انقطاع الدم، هذا هو الأولى.","link":"https://binbaz.org.sa/fatwas/1400/حكم-من-حاضت-وهي-على-جنابة-لم-تغتسل-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_355.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":6420,"question":"آخر  يسأل: امرأة تأتيها العادة الشهرية لمدة خمسة عشر يومًا تستمر سبعة أيام، أو ثمانية، ينزل فيها دم حيض أسود منتن، وفي بقية الأيام يكون أصفر، تغلب عليه الحمرة، فهل تنزل المرأة للصلاة خمسة عشر يومًا كلها، أم السبعة أيام؟","title":"بيان متى تطهر المرأة من حيضها","answer":"الجواب: الحيض لا حد لأقله، ولا لأكثره على الصحيح، لا حد لأكثره، ولا لأقله، فإذا كان من عادتها خمسة عشر يوماً، بعضها أسود، وبعضها أصفر، وبعضها أحمر، لا تصلي، ولا تصوم، ولا يأتيها زوجها في ذلك حتى تطهر، أما إذا كانت تطهر من الدم، ثم يأتيها بعد الطهارة كدرة، أو صفرة؛ فهذه لا عمل عليها، الكدرة والصفرة لا عمل عليها، ولا تعتبر حيضًا، بل تصلي، وتصوم، وتحل لزوجها مع الصفرة، والكدرة، لكن بعد الطهارة لا بدّ أنها من ترك إن كانت الصفرة، والكدرة متصلة بالدم، ما بينهما طهارة، هذه حيض، لا تصلي فيها، ولا تصوم، أما إذا طهرت على سبعة أيام، أو ثمانية، أو خمسة مثلاً، ثم بعد الطهارة المضبوطة جاءها صفرة، أو كدرة، هذه لا عمل عليها، قالت أم عطية -رضي الله عنها-: كنا لا نعد الكدرة والصفرة بعد الطهر شيئًا، يعني بعد ما تغسل حيضها عن طهارة واضحة، ثم بعد ذلك يأتي كدرة، أو صفرة؛ فليس عليها عمل، بل تصلي فيها، وتصوم، وتحل لزوجها، وتعمل ما تعمل المستحاضة من الوضوء بعد دخول الوقت، والتحفظ من هذا الدم بقطن، ونحوه، حتى يذهب. السؤال: ما يلزمها الغسل؟ الجواب: لا، مثل البول.","link":"https://binbaz.org.sa/fatwas/2131/بيان-متى-تطهر-المراة-من-حيضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_779.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":6580,"question":"وضعت زوجتي في أول شهر رمضان المبارك، وانتهى شهر رمضان، ولم تصم فيه يومًا واحدًا، وبعدما انتهى الشهر أمرتها بالصيام، فقالت: إنها لا تطيق بسبب مرض أصابها، ولا عادت، وهكذا، فمتى يسقط عنها الإعادة، أو..؟","title":"وقت قضاء الحائض والنفساء لصيام رمضان","answer":"الجواب: عليها الصوم متى قدرت، إذا أفطرت في رمضان من أجل النفاس، وهكذا الحائض إذا أفطرت أيامًا في رمضان، تصوم، تصومان بعد ذلك فيما بين رمضان، وما بين شعبان إلى آخر شعبان، كله محل صوم إذا استطاعت، وقدرت، صامت في شوال في ذي القعدة، في ذي الحجة في المحرم، صفر، ربيع، جماد، رجب، شعبان، كلها محل صوم، والحمد لله، لم يضيق الله  وإذا بادرت؛ فهو أفضل، إذا حصل لها البدار؛ فهو أفضل بالقضاء إذا تيسر ذلك، فإن شق عليها لمرض، أو رضاع؛ أجلت الصوم حتى تستطيع، ثم تصوم بعد ذلك، ولا شيء عليها، ولا فدية عليها، ولا إطعام، بل متى قدرت؛ صامت، والحمد لله.","link":"https://binbaz.org.sa/fatwas/2412/وقت-قضاء-الحاىض-والنفساء-لصيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_939.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":6742,"question":"إذا كان في امرأة نفساء، انقطع دم النفاس عنها، ثم عاد خلال يوم، فهل تجب عليها الصلاة في هذا اليوم؟","title":"حكم انقطاع دم النفاس ليوم ورجوعه بعد ذلك","answer":"الجواب: إذا كانت في أيام النفاس الأربعين، وانقطع عنها الدم؛ تغتسل، وتصلي، وتصوم في الأيام التي انقطع عنها الدم، ورأت فيها الطهارة يوم يومين ثلاثة، صلاتها صحيحة، وصومها صحيح، وتحل لزوجها، فإذا عاد عليها الدم في الأربعين؛ فالصحيح أنها تجلس، إذا عاد عليها الدم في الأربعين؛ لا تصلي ولا تصوم، ولكن أيامها الماضية التي رأت فيها الطهارة صومها صحيح، وصلاتها صحيحة، لا تعاد.","link":"https://binbaz.org.sa/fatwas/2624/حكم-انقطاع-دم-النفاس-ليوم-ورجوعه-بعد-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1120.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":6785,"question":".. أثناء الحيض ..؟","title":"حكم انقطاع الدم عن الحائض ورجوعه بعد ذلك","answer":"الجواب: مثل النفساء، إذا طهرت -رأت الطهارة- تغتسل، وتصلي، وتصوم، فإذا عاد عليها الدم -الدم الصاحي- تجلس، ولا تصلي، ولا تصوم، مثل النفساء. السؤال​​:.. الجواب: تصلي، وتصوم، وتحل لزوجها، فإذا عاد عليها الدم؛ تجلس، لا تصلي، ولا تصوم إن كان صفرة، أو كدرة لا، إذا مضت العادة، وطهرت، واغتسلت، ثم رأت صفرة، أو كدرة هذه ما عليها عمل، الصفرة، والكدرة تعتبر مثل البول، تصلي، وتصوم معه، وتستنجي إذا دخل الوقت، وتتوضأ وضوء الصلاة.","link":"https://binbaz.org.sa/fatwas/2626/حكم-انقطاع-الدم-عن-الحاىض-ورجوعه-بعد-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1122.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":6997,"question":"امرأة ذهبت لأداء العمرة، وقبل أن تأتي مكة أتتها الدورة الشهرية، وطافت، وسعت وهي بهذا، فهل عليها كفارة، وهل عمرتها صحيحة، وإذا كان عليها كفارة، فما نوعها؟","title":"حكم طواف العمرة للحائض","answer":"الجواب:\n\nلا زالت في العمرة حتى ترجع، وتطوف، وتسعى، لا زالت في العمرة؛ لأن الطواف لا يكون مع الحيض، فإذا جاءت العمرة، وأصابها الحيض؛ تبقى حتى تطهر، ثم تطوف، ثم تسعى، وتؤدي العمرة بذلك، تقصر من رأسها، وتمت العمرة، العمرة طواف، وسعي، بعد الإحرام طواف، وسعي، وتقصير من رأسها، والرجل إن شاء قصر، وإن شاء حلق، هذه العمرة، فإذا وصلت إلى مكة، وجاءتها الدورة؛ تبقى حتى تطهر، فإذا طهرت؛ طافت، وسعت، وقصرت من رأسها، وتمت عمرتها.\n\nالسؤال: يعني الطواف هذا لا يقبل؟\n\nالجواب: ما يقبل لا، عليها أن ترجع إلى مكة، وتؤدي الطواف، ثم التقصير، وأما السعي فيجزئها -إن شاء الله-.\n\nالسؤال: يعني ليس عليها دم؟ \n\nالجواب: ما عليها دم، عليها أن ترجع.\n\nالسؤال: ولو كان أتاها الزوج؟\n\nالجواب: إذا أتاها زوجها؛ فسدت العمرة، وعليها أن ترجع، وتؤدي العمرة كاملة، وعليها أن تقضي عمرة جديدة، زيادة من إحرامها من الميقات الذي أحرمت منه، إذا أتاها الزوج؛ بطلت العمرة، فسدت، ولكن عليها مع هذا أن تكملها عمرة فاسدة، عليها أن ترجع، وتطوف، وتكمل عمرتها، ثم بعد ذلك تقضي عمرة جديدة ليس فيها وطء بطواف، وسعي، وتقصير بدلًا من عمرتها التي فسدت بالجماع، كما أفتى بهذا أصحاب النبي -عليه الصلاة والسلام-.\n\nالسؤال: ما عليها دم في العمرة الأولى؟\n\nالجواب: عليها شاة، دم شاة تذبح في مكة للفقراء، عليها دم عن الجماع.\n\nالسؤال: بعض النساء ..؟\n\nالجواب: تغتسل، أو تتعاطى دواء يزيل الدم، إذا انقطع الدم، أو انقطعت الدورة تغتسل، وتطوف -والحمد لله- وتصلي. \n\nالسؤال: لا العمرة الوقت فيها؟\n\nالجواب: حتى العمرة، والحج\n\nالسؤال: خارج العمرة، وخارج الحج في الأيام العادية؟","link":"https://binbaz.org.sa/fatwas/2922/حكم-طواف-العمرة-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1370.mp3","categories":["الطواف بالبيت","الحيض والنفاس","قضايا المرأة"]},{"id":7026,"question":"هناك امرأة صامت رمضان، ولكن قبل الغروب نزل منها دم، فتكمل الصوم وإلا تفطر، مع العلم أن الدم ليس حيض؛ لأنه أتى بعد العادة الشهرية، فما يكون صومها؟","title":"حكم صيام المرأة إذا خرج منها دم قبل الغروب","answer":"الجواب:\n\nإذا كانت المرأة صائمة، ونزل بها الحيض قبل الغروب، أو الدم الذي يعتبر حيضًا قبل الغروب؛ بطل الصوم.\n\nأما إذا كان بعد الغروب، بعدما غابت الشمس؛ فصومها صحيح، ولو قبل أن تصلى المغرب، ما دام بعد إفطارها بعد غروب الشمس، صومها صحيح.\n\nأما إن كان قبل الغروب، والدم يعتبر حيضًا؛ فإنه يبطل صومها، أما إن كان لا، صفرة، وكدرة؛ هذا لا يبطل الصوم، تقول: أم عطية -رضي الله عنها وهي من الصحابيات-: كنا لا نعد الكدرة، والصفرة بعد الطهر شيئًا، لكن إذا نزل الدم؛ فالأصل في الدم أنه حيض، قد .. تطهر، ثم يعود علها الدم، لكن إذا كان صفرة، أو كدرة بعد الطهارة، هذا لا يضرها.","link":"https://binbaz.org.sa/fatwas/3003/حكم-صيام-المراة-اذا-خرج-منها-دم-قبل-الغروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1411.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":7233,"question":"أنا امرأة حضت خمسة أيام، أول رمضان ثم طهرت، وبعد عشرين يومًا رجعت علي العادة خمسة أيام، لكنني صليت، وصمت، هل أعيد أم لا؟","title":"حكم المرأة التي يأتيها الحيض في الشهر مرتين","answer":"الجواب:\n\nنعم نعم، الأيام التي صمتِها ومعك الدم هذا غلط، ومنكر، عليك التوبة إلى الله من هذا، عليك التوبة إلى الله؛ لأن الحائض لا تصوم، ولا تصلي، فالأيام التي صمتِها الأخيرة، أو الأولى عليك قضاء الصيام؛ لأنها أيام من رمضان، وأنت لا تصلحين للصيام، ومعك الحيض، فصومها باطل، صومك إياها باطل، وعليك قضاؤها وعليك التوبة إلى الله . \n\nأما الصلاة فلا تقضى؛ لأن الحائض لا تصلي، لكن عليك التوبة إلى الله من صلاتك وأنت حائض، ومن صومك وأنت حائض، فالله -جل وعلا- وضع عن الحائض والنفساء الصوم والصلاة، وجعلها تقضي الصوم، ولا تقضي الصلاة، قالت عائشة رضي الله عنها: \"كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة\".\n\nفالحائض لا تصلي ولا تصوم، وهكذا النفساء لا تصلي ولا تصوم ما دام معها الدم قبل الأربعين، وعليها قضاء الصوم بعد الطهر، وليس عليهما قضاء الصلاة، إنما تقضيان الصوم، صوم رمضان.\n\nوإذا طهرت النفساء قبل الأربعين؛ فإنها تغتسل، لو طهرت وهي بنت ثلاثين، أو عشرين، أو خمس وعشرين، ما مضى من نفاسها إلا خمس وعشرون، أو عشرون، أو ثلاثون إذا طهرت؛ تغتسل وتصلي وتصوم وتحل لزوجها، ولا تبقى حتى تكمل الأربعين، ما هو لازم تكمل الأربعين، متى رأت الطهر؛ تغتسل، وتصلي، وتصوم، وتحل لزوجها، ولو لم يمض عليها من الأربعين إلا عشرون، أو خمس وعشرون، أو ثلاثون.\n\nفأما إن استمر معها الدم إلى كمال الأربعين؛ فإنها تغتسل عند تمام الأربعين، تغتسل، وتصلي، وتصوم، ولو أن الدم معها؛ لأن النهاية أربعون، وبعد مضي الأربعين ولم ينقطع الدم؛ تغتسل وتصلي وتصوم وتتحفظ بقطن ونحوه، ولا تتوضأ إلا عند دخول الوقت، كالمستحاضة حتى توافق الحيض، فإذا جاء الدم في وقت الحيض؛ جلست، ولم تصم، ولم تصل، وهكذا، هذه أمور ينبغي العناية بها. \n\nوهكذا الحائض لو كانت عادتها سبعًا، أو ثمانية، ثم طهرت في ثلاث، أو لأربع اغتسلت وصلت وصامت، ولم تنتظر بقية الأيام التي طهرت فيها، فإن الحيض يزيد وينقص، فإذا كانت سبعًا، أو ثمانية، وطهرت لثلاث، أو أربع؛ فإنها تغتسل وتصلي وتصوم، وتحل لزوجها.\n\nوهكذا لو زادت خمسًا، فاستمر الدم معها ستًا، أو سبعًا، أو ثماني؛ لا تصلي، ولا تصوم حتى تكمل، حتى تطهر.\n\nالسؤال: يكون بين الحيضتين أقل من شهر؟ \n\nالجواب: نعم يكون بينهما أقل من شهر، وأقل من عشرين يومًا أيضًا، وقال بعضهم: أقل ما يكون ثلاثة عشر يومًا، لكن ليس عليه دليل، متى رأت الدم؛ جلست، إلا إذا كان المرئي صفرة، أو كدرة بعد الطهارة؛ فإنها لا تعتبرهما شيئًا.\n\nالصفرة والكدرة كالبول، تصلي وتصوم معهما، وتستنجي في الوقت -وقت الصلاة- وتتوضأ وضوء الصلاة في وقتها، إذا دخل وقتها، إذا كان معها صفرة أو كدرة كالمستحاضة التي يستمر معها الدم دائمًا، هذه تصلي وتصوم، وتتوضأ لوقت كل صلاة، ولا تجلس إلا إذا جاء وقت الحيض، إذا جاء وقت حيضها؛ جلست -يعني تركت الصوم والصلاة- وإذا مضى وقت الحيض؛ اغتسلت، وصلت، وصامت. \n\nالسؤال: يعني الشهر يستوعب حيضًا، وطهرًا؟\n\nالجواب: قد يكون فيه حيضتان الشهر الواحد.","link":"https://binbaz.org.sa/fatwas/3296/حكم-المراة-التي-ياتيها-الحيض-في-الشهر-مرتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1621.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":7293,"question":"امرأة جاءها رمضان وهي نفساء، وبعد سبعة وعشرين يومًا من نفاسها طهرت؛ فاغتسلت، ثم صامت، وقبل نهاية رمضان بسبعة أيام جاءها دم، واستمر معها ستة أيام، هل يعتبر من النفاس، أم عادة شهرية؛ لأن عادتها الشهرية ستة أيام تقريبًا؟","title":"حكم انقطاع دم النفاس ثم ظهوره مرة أخرى","answer":"الجواب: النفساء لا مانع من أن تغتسل عند وجود الطهارة، بل يجب عليها أن تغتسل عند وجود الطهارة، ولو أنها بنت عشرة أيام، أو عشرين يومًا؛ لأنه ليس لأقل النفاس حد محدود، قد يكون قليلًا وقد يكون كثيرًا، فإذا طهرت لعشرة أيام، أو عشرين يومًا، أو خمس وعشرين، أو سبع وعشرين؛ فإنها تغتسل، وتصلي، وتصوم، وتحل لزوجها. فإذا عاد عليها الدم في الأربعين نفسها؛ فإنها تجلس أيضًا، ولا تصلي، ولا تصوم؛ لأنه دم النفاس عاد إليها حتى تستكمل الأربعين، فإذا كملت الأربعين وجب عليها التطهر، ولو كان معها الدم؛ وجب عليها الاغتسال والصلاة والصوم والحج، وحلت لزوجها؛ لأن النهاية أربعون، نهاية النفاس أربعون يومًا كما جاء في الحديث -حديث أم سلمة- وما بعد هذا يكون استحاضة لا يمنع صلاة، ولا صومًا ولا زوجًا. عليها أن تعمل ما تعمل المستحاضة، تصلي بعد دخول الوقت، وتستنجي، وتتوضأ لوقت كل صلاة، ولها أن تجمع بين الصلاتين؛ لأنها في شبه مرض، لكن لا تصلي إلا بوضوء جديد؛ كلما دخل الوقت تستنجي وتتوضأ لقول النبي ﷺ للمستحاضة: وتوضئ لوقت كل صلاة فهي من جنس المستحاضة، تتوضأ لوقت كل صلاة، وتصلي بعد ذلك، ولو مشى معها الدم تصلي على حسب حالها، وإن جمعت بين الصلاتين بين الظهر والعصر والمغرب والعشاء؛ فلا حرج؛ لحديث ورد في ذلك عن حمنة بنت جحش رضي الله عنها .  المقصود: أن طهارتها في أثناء الأربعين معتبرة؛ تغتسل، وتصلي، وتصوم، وتحل لزوجها، فإذا عاد عليها الدم في الأربعين؛ كذلك لا تصلي، ولا تصوم، في الأربعين تجلس في الدم الجديد، لا يكون حيضًا، يكون نفاسًا في الأربعين، ثم إذا طهرت قبل الأربعين؛ فالحمد لله تغتسل وتصلي، وإن بقي للأربعين اغتسلت أيضًا، ولو أن الدم معها تغتسل، وتصلي؛ لأنه لا يزيد على الأربعين على الصحيح، فتغتسل، وتصلي، وتصوم، ولو مشى معها الدم، لكن لا تتوضأ إلا لوقت كل صلاة، إذا دخل الوقت توضأت، واستنجت لوقت كل صلاة، هكذا جاء في حديث المستحاضة، وهذه مثلها.","link":"https://binbaz.org.sa/fatwas/3375/حكم-انقطاع-دم-النفاس-ثم-ظهوره-مرة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1693.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":7474,"question":"هذه رسالة من الأخ في الله عبد الله السليمان من الرياض، يقول: بعض الفتيات يتوهمن أن المرأة الحائض أصبحت نجسة فلا يجوز لها الذكر، ولا استماع القرآن، وإنما الاتجاه لسماع الغناء واللهو، نرجو تبيين هذا الحكم، وما الذي يجوز أيضاً للحائض؟","title":"ما يحل للحائض وما يحرم","answer":"الجواب: هذا توهم لا ينبغي، الحائض مشروع لها ما يشرع لغيرها من ذكر الله عز وجل، وتسبيحه وتحميده وتهليله وتكبيره، والاستغفار والتوبة، وسماع القرآن ممن يتلوه، وسماع العلم، والمشاركة في حلقات العلم، وسماع ما يذاع من حلقات العلم، وحلقات القرآن، والاستفادة من ذلك مثل غيرهما. النبي ﷺ قال للحائض: افعلي ما يفعله الحاج غير أن لا تطوفي بالبيت حتى تطهري فأمرها أن تفعل ما يفعله الحجاج؛ من التلبية، والذكر، وسائر الوجوه الشرعية ما عدا الطواف، فدل ذلك على أن الحائض مثل غيرها، ترمي الجمار، تلبي، تذكر الله، تسبح، تحمد، تهلل، تستغفر، يعني تفعل كل شيء ما عدا الطواف إذا كانت محرمة بالحج أو العمرة حتى تطهر. كذلك في بيتها تستعمل ما تستطيع من ذكر الله  تسبيحه.. تحميده.. تهليله.. تكبيره.. الاستغفار.. الدعوة إلى الله.. الأمر بالمعروف والنهي عن المنكر.. تدريس العلم.. مطالعة الأحاديث.. غير ذلك. أما قراءة القرآن ففيه خلاف، بعض أهل العلم يرى أنها تمنع من قراءة القرآن، والقول الثاني: أنها لا تمنع من قراءة القرآن عن ظهر قلب، وهذا هو الأقرب والأظهر؛ لأنه لها أن تقرأ القرآن عن ظهر قلب من دون مس المصحف، كالمعلمة تعلم البنات القرآن عن ظهر قلب، وكالتلميذة التي تحتاج إلى قراءة القرآن من غير مس المصحف كذلك. الصحيح أنه لا حرج في قراءتها عن ظهر قلب؛ لأن مدة الحيض تطول وهكذا النفاس، بخلاف الجنب، الجنب لا يقرأ القرآن، لا من المصحف ولا عن ظهر قلب حتى يغتسل؛ لأن النبي ﷺ: كان لا يقرأ القرآن وهو جنب عليه الصلاة والسلام؛ ولأن الجنب يعني وقته قصير يستطيع في أي حال أن يغتسل ويقرأ، ما هناك له موانع؛ لكن الحائض تحتاج إلى أيام وليالي، ليس باختيارها، وهكذا النفساء أطول وأطول، فلهذا الصحيح أنه لا حرج عليها في قراءة القرآن عن ظهر قلب لا من المصحف. وبهذا تعلم أن الحائض تشارك في كل شيء من الخير، ولا تمنع ما عدا مس المصحف، وما عدا الصلاة؛ لأنه لا تصلي ولا تصوم حتى تنتهي من حيضها ونفاسها ثم تقضي الصوم دون الصلاة، ليس عليها قضاء الصلاة بل الله سامحها، سامح الحائض والنفساء الصلاة فلا تقضيها ولا تجب عليها مدة الحيض والنفاس، لكن الصوم تقضيه بعد طهرها وبعد رمضان تقضي ما أفطرت من الأيام. سئلت عائشة رضي الله عنها قالت لها امرأة: يا أم المؤمنين! ما بالنا نقضي الصوم ولا نقضي الصلاة؟ فقالت لها عائشة رضي الله عنها: كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة يعني من النبي ﷺ، كان يأمرهن بقضاء الصوم ولا يأمرهن بقضاء الصلاة، وبهذا علم أن الصوم يقضى والصلاة لا تقضى، وهذا محل إجماع بين المسلمين، فقد أجمع العلماء على أن الصلاة لا تقضى في حق الحائض والنفساء، ولكنهما تقضيان الصوم فقط، صوم رمضان يعني.\nفالحاصل: أن الحائض والنفساء يشرع لهما ذكر الله، وتسبيحه وتحميده وتهليله وتكبيره، وحضور حلقات العلم، وسماع القرآن ممن يتلوه، والإنصات لذلك، والمشاركة في كل خير، ما عدا أنها لا تصلي حتى تطهر ولا تصوم حتى تطهر، ولا تقرأ القرآن من المصحف، أما عن ظهر قلب فالصحيح أنه يجوز لها ذلك في أصح قولي العلماء ولاسيما عند الحاجة. نعم.","link":"https://binbaz.org.sa/fatwas/4319/ما-يحل-للحاىض-وما-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00304.mp3","categories":["الحيض والنفاس"]},{"id":7662,"question":"أيضاً يقلن السائلات (م. ع. ش) من بيشة وفاطمة و نوال و شريفة في سؤالهن الثاني يقلن: إذا تأخرت المرأة.. لم تطهر أثناء النفاس، وانتهت الأربعين يوم وهي لم تطهر، هل تصلي أم تبقى بدون صلاة؟","title":"حكم الدم إذا استمر مع النفساء بعد الأربعين","answer":"الجواب: إذا استمر الدم مع النفساء حتى كملت الأربعين فإن هذا الدم الذي زاد معها يعتبر دم فساد، فتغتسل وتصلي وتصوم ولا تلتفت إليه، يكون مثل دم المستحاضة دماً فاسد تتوضأ لوقت كل صلاة، تتحفظ بقطن ونحوه عن أذى الدم لها وفي ثيابها وبدنها، وتصلي على حسب حالها، ولا مانع من أن تصلي الظهر والعصر جميعاً والمغرب والعشاء جميعاً كالمستحاضات، ولا يعتبر نفاساً من حين تتم الأربعين.. لا يعتبر الدم الذي معها نفاساً بل هو دم فساد، هذا هو المعتمد. نعم.","link":"https://binbaz.org.sa/fatwas/4827/حكم-الدم-اذا-استمر-مع-النفساء-بعد-الاربعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_037/03708.mp3","categories":["الحيض والنفاس"]},{"id":7666,"question":"هذه رسالة وردت من المواطن حسن علي من خميس مشيط من المدينة العسكرية يقول فيها: حضرة المكرم فضيلة الشيخ عبد العزيز بن عبد الله بن باز الموقر، بعد التحية السلام عليكم ورحمة الله وبركاته وبعد، يقول:لدي زوجة أسقطت في الشهر الثالث أي قبل أن يتمثل الجنين وبقي الدم معها لما يقارب من ثلاثة أشهر، وخلال المدة المذكورة لم تستطع أن تؤدي الفرائض المطلوبة في الصلاة، بسبب سيلان الدم طبعاً، وذلك لأن الغسل لكل صلاة صعب جداً عليها، لدى سؤال بعض العلماء من ذلك أفاد بأن المرأة التي تسقط في الثلاثة الشهور من الحمل ونزل منها الجنين عبارة لحمة فإن عليها أن تؤدي فرائض الصلاة والفرائض الأخرى حتى الزوج له حق في جماعها، و هل هناك نص شرعي بذلك، أفيدونا جزاكم الله خيراً؟","title":"حكم الدم الخارج من المرأة بسبب الإسقاط","answer":"الجواب: إذا أسقطت المرأة جنينها ففيه تفصيل: إذا كان إسقاطها للجنين قبل أن يتخلق قبل أن يوجد فيه علامة الإنسان من رأس أو رجل أو ما أشبه ذلك بل دم.. دم، أو دم من دم متجمع لم يظهر فيه ولو خفياً ما ظهر فيه خلق الإنسان هذا يعتبر دماً فاسداً كالمستحاضة، تصلي وتصوم وتحل لزوجها كما أفتاه بعض العلماء بذلك، كما أفتى السائل بعض العلماء، هذا مثل ما قال له المفتي الذي أفتاه من أهل العلم صحيح إذا كان السقط دماً ما فيه لحم إنسان المتخلق أو لحمة لكن ما فيها خلق إنسان لا خفي ولا ظاهر، هذا يعتبر دماً فاسداً، وتعتبر المرأة في حكم المستحاضة التي لها أن تصلي بل عليها أن تصلي وتصوم وتباح لزوجها وعليها مع ذلك أن تعنى بالطهارة، يعني تغتسل إذا تيسر لها ذلك كل صلاة أو في الظهر والعصر.. جميعاً غسلاً واحداً، وللمغرب والعشاء غسلاً واحداً، هذا يكون أكمل وليس بواجب، وإنما الواجب الوضوء؛ إذا دخل الوقت توضأ وضوء الصلاة: تستنجي بالماء في فرجها وتغسل ما أصابها من الدم، تستثفر بشيء من القطن ونحوه وتوضأ وضوء الصلاة في غسل وجهها ويديها ومسح رأسها وغسل رجليها، وضوء الصلاة المعروف بعد الاستنجاء بعد غسل ما في الفرج من النجاسة ثم تصلي كل وقت في وقته، وإن جمعت صلاة الظهر والعصر جميعاً أخرت الأولى الظهر مثلاً وعجَّلت العصر وصلتهما بغسل واحد هذا أفضل، وكذلك المغرب والعشاء تؤخر المغرب عن وقتها بعض الشيء تعجل العشاء في وقتها، يعني تكون صلاتها متقاربة العشاء والمغرب، جمعاً صوري يسمى ليس بجمع حقيقة، هذا لا بأس به وهو أفضل لها حتى يتيسر لها غسل لهما غسلاً واحداً، وهذا من باب الفضائل، هذا هو الصواب من أقوال أهل العلم أنه من باب الفضائل لا من باب الوجوب، والواجب عليها غسل واحد للحيض فقط، ما دامت هذه المرأة قد أصابها النزيف وليس عندها نفاس شرعي فإن هذا الدم يعتبر دماً فاسداً دم استحاضة تصلي وتصوم وتحل لزوجها ولا حرج عليها في ذلك إلا أنها تؤمر بأن تستنجي وتوضأ لوقت كل صلاة، ولا بأس عليها أن تجمع وهو الأفضل بين الظهر والعصر والمغرب والعشاء وتغتسل لهما غسلاً واحداً لهاتين ولهاتين، وللفجر وحده غسلاً واحداً إذا تيسر ذلك وإلا فليس بلازم، هذا هو حكم هذه المسألة وأشباهها، هذه المسألة التي يبتلى بها كثير من النساء تسقط في الشهرين في الثلاثة دماً ما فيه خلق إنسان فيه رأس لا رأس ولا رجل ولا شيء من ذلك، هذا دم فاسد تتحفظ فيه وتصلي وتصوم وتحل لزوجها، أما إن كان فيه خلق إنسان بين أو رجل أو يد أو ما أشبه ذلك مما يبين أنه إنسان هذه نفاس، هذا نفاس تمكث لا تصلي ولا تصوم حتى تطهر، ولا تحل لزوجها أيضاً، فإذا طهرت بعد إسقاط هذا الجنين ولو بعد خمسة أيام عشرة أيام عشرين يوم متى طهرت تغتسل وتصلي وتصوم وتحل لزوجها ولو ما مضى عليها إلا عشرة أيام أو عشرون يوماً، ما هو لازم أن تكمل أربعين يوم ما هو لازم، فإن مضى معها الدم واستمر معها الدم حتى كملت أربعين فهي نفاس، ولكن لا تزيد على أربعين، لو استمر معها تغتسل وتصلي وتصوم ولو كان معها الدم يعتبر دماً فاسداً، ما زاد على الأربعين يعتبر دماً فاسداً على الصحيح تصلي فيه وتصوم وتحل لزوجها وتتوضأ لكل وقت في كل صلاة، وتتنظف عند دخول الوقت بالاستنجاء والتحفظ بقطن ونحوه، هذا هو الواجب عليها بعد الأربعين ولو معها الدم ولو سال معها الدم، كالمستحاضة التي معها الدم من غير إسقاط، كالذي في بعض النساء قد يصيبها الدم وهي ما فيها حمل، يستمر معها الدم وتسمى مستحاضة، فإذا جاء وقت حيضها توقفت عن الصلاة والصوم وحرمت على زوجها، وتبقى هكذا في حكم الحيض، فإذا مضى وقت الحيض الذي تعرفه بعدها تغتسل وتصلي وتصوم وتحل لزوجها مدة الطهارة الحكمية، حتى يأتي وقت الحيض المعتاد وهكذا، هكذا التي أنزلت يعني دماً وهي تعتبر نفسها حاملاً ثم أراد الله عليها إسقاط هذا الحمل بأسباب فإن هذا الدم يكون فاسداً إلا إذا علمت الثقة القابلة التي قبلتها أنه خرج منها لحم فيه خلق الإنسان من رأس أو رجل أو ما أشبه ذلك فهذه تكون نفساء، تعتبر نفسها نفساء إذا كان فيه خلق الإنسان ولو خفياً فلا تصلي ولا تصوم حتى تطهر، والطهارة ليس لها حد محدود، ما هو بلزوم أن تكمل أربعين لا، لو طهرت وهي بنت عشرة أيام أو عشرين يوم أو شهر فالطهارة صحيحة، وتصلي وتصوم لهذه الطهارة، فلو عاد الدم عليها في الأربعين تجلسه أيضاً، تعتبره نفاساً ولا تصلي ولا تصوم في الأربعين إذا عاد عليها الدم فيها على الصحيح، فإذا استمر معها الدم إلى كمال الأربعين تعتبر هذا الدم الزائد دماً فاسداً بعد الأربعين، تصلي فيه وتصوم وتحل لزوجها، توضأ لوقت كل صلاة، تتحفظ في فرجها بشيء من القطن ونحوه إذا استنجت، هذا هو الحكم في ذلك، كالمستحاضة سواء، ولا تزال على هذا العمل حتى يخلصها الله من هذا النزيف، وإذا جمعت بين الظهر والعصر وبين المغرب والعشاء فلا بأس كما تقدم وتغتسل لهما غسلاً واحداً أفضل، وتغتسل للفجر غسلاً واحداً أفضل إن تيسر ذلك، وإلا فالغسل الواجب إنما هو الغسل من الحيض أو الغسل من النفاس هذا الواجب أو الغسل من الجنابة كما هو معروف. نعم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4840/حكم-الدم-الخارج-من-المراة-بسبب-الاسقاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_038/03805.mp3","categories":["الحيض والنفاس"]},{"id":7741,"question":"هذه رسالة وردت من عدة مستمعات -هن: رقية علي الشمري، فاطمة من الرياض، سعاد محمد البشري من الهفوف، (عائشة . م. ص) من القصيم يقلن في رسالتهن هذه: سمعنا أو في رسائلهن، ولكني جمعتها لأنها متفقة-: سمعنا في حلقة ماضية مع سماحة الشيخ عبد العزيز بن عبد الله بن باز لقاء، وقد قال في هذا اللقاء: إن المرأة إذا طهرت قبل الأربعين فلها أن تصلي وتصوم، لكن لو عاد إليها الدم خلال الأربعين، فهل يعتد بصومها الذي صامته، وهل يجوز لزوجها مباشرتها في الأربعين؟","title":"حكم النفساء إذا طهرت ثم صلت وصامت وعاد إليها الدم","answer":"الجواب: نعم، إذا طهرت المرأة في الأربعين -كما تقدم- تصلي وتصوم وتحل لزوجها ولو ما كملت الأربعين؛ لأن الحكم مناط بالطهارة، فإذا رأت الطهارة وهي بنت عشرين يوماً في النفاس أو ثلاثين يوماً في النفاس فطهارتها صحيحة، وعليها أن تغتسل غسل النفاس وتوضأ وضوء الصلاة تصلي وتصوم وتحل لزوجها ولو أنها ما كملت الأربعين؛ بسبب وجود الطهارة، فلو عاد الدم في الأربعين رجع الدم عليها، وطهرت مثلاً لشهر وبقيت ثلاثة أيام أربعة أيام طاهرة، ثم عاد عليها الدم في الخامس والثلاثين أو في السادس والثلاثين فالصحيح أن هذا الدم يعتبر نفاساً، لا تصلي فيه ولا تصوم ولا تحل لزوجها، لكن صومها الذي في أيام الطهارة وصلاتها صحيحة ما تعاد صومها الذي هو في أوقات الطهارة صوم صحيح، ليس عليها أن تعيده بعد ذلك -أن تقضيه- لا، صوم وقع في محله، صلاة وقعت في محلها، فالصوم صحيح والصلاة صحيحة، وكون زوجها باشرها في ذلك كذلك؛ لا حرج عليه لأنه باشرها في وقت الحل وهو الطهارة.\nأما بعد رجوع الدم في الأربعين فإن هذا الدم الذي رجع قال بعض أهل العلم: إنه مشكوك فيه. والصواب أنه ليس مشكوكاً فيه، بل هو دم نفاس يعتبر دم نفاس، مثل الدم الذي يعود في وقت الحيض؛ فلا تصلي ولا تصوم، فإذا مضت الأربعون ولم ينقطع فقد تقدم أن هذا الدم الزائد يعتبر دماً فاسداً بعد الأربعين تصلي وتصوم فيه وتعتبره دم استحاضة عليها أن تتحفظ فيه من قطن ونحوه وتوضأ لوقت كل صلاة وتصلي الصلوات في أوقاتها أو تجمع بين الظهر والعصر والمغرب والعشاء لا بأس وتحل لزوجها كما تقدم.\nوقد يجمع بين الصلاتين -الظهر والعصر والمغرب والعشاء- أفضل للمستحاضات ومن في حكمهن وهو أفضل لهن مع ذلك أن يغتسلن للظهر والعصر غسلاًَ واحداً والعشاء والمغرب غسلاً واحداً، والفجر غسلاً واحداً إذا تيسر ذلك، كما أوصى به النبي ﷺ بعض المستحاضات. نعم.\n2. السائل: لكن إذا صامت مثلاً عشرة أيام خلال الأربعين في رمضان ثم عاد عليها الدم خلال الأربعين هل يعتد بصومها الذي انقطع؟\nالشيخ: نعم. بينا أن صومها صحيح تعتد بصومها وهو صحيح ولا تقضيه؛ لأنه وقع في وقت الطهارة، هو صوم صحيح. نعم.","link":"https://binbaz.org.sa/fatwas/4941/حكم-النفساء-اذا-طهرت-ثم-صلت-وصامت-وعاد-اليها-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_041/04102.mp3","categories":["الحيض والنفاس"]},{"id":7743,"question":"هذه الرسالة وردتنا من شريفة طالع من قرية الخلفة بتهامة بني شهر تقول فيها: لي جارة حملت وسقط حملها بعد شهرين، ولا يعرف هل هو ذكر أو أنثى، وقد دفن في جانب من الحارة ولم يدفن في مقبرة المسلمين، فما حكم هذا الدفن؟","title":"الأحكام المتعلقة بالسقط إذا كان له شهران","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالمرأة إذا أسقطت جنيناً فيه تفصيل: إن كان الجنين دماً محضاً هذا ما يسمى جنين، ولا يسمى نفاس الدم الخارج بسببه ولا يكون لها حكم النفساء، بل عليها أن تصلي وأن تصوم وتحل لزوجها؛ لأن هذا لا يسمى نفاس مادام ابن شهرين أو ابن ثلاثة أشهر، هذا في الغالب ما يتخلق هذا يكون دماً فاسداً، هذا الدم يكون دماً فاسداً، وتصلي وتصوم، والدم المجتمع الذي سقط يدفن في أي مكان، في البيت أو في الحوش ما يذهب إلى المقابر ما في حاجة، لأن هذا ليس بإنسان، وعليها أن تصلي وأن تصوم، وتعتبر هذا الدم دماً فاسداً مثل دم اللي يخرج من الجراحات الأخرى، دماً فاسداً لا يمنعها من الصلاة والصوم، ولا يمنع زوجها من غشيانها؛ لأنه دم فاسد لا يسمى نفاساً، ولا يسمى حيضاً.\nأما إن كان الدم قد اجتمع فيه لحمة - تجمع منه لحمة - وفيها خلق إنسان - ولو خفي - مثل رأس.. رجل.. يد، إذا علم ذلك علمت ذلك المرأة أو القابلة لها التي عندها الثقة أن هذا اللحم فيه خلق الإنسان هذا يسمى ولد ويعتبر نفاس، فليس لها حينئذٍ أن تصلي ولا أن تصوم وليس لزوجها أن يقربها، يعني: أن يطأها؛ لأنها نفساء مادامت اللحمة التي خرجت فيها خلق الإنسان، ولو ما مضى عليها أربعة أشهر في اعتقادها لأن الجنين قد يخلق فيه قبل ذلك، والغالب أنه لا يخلق إلا في الطور الثالث بعد المضغة، لكن جاء ما يدل في بعض الأحاديث على أنه قد يقع قبل ذلك، فالحاصل أنه إذا كان فيه خلق الإنسان يعتبر نفاس، وعليها أن تمتنع من الصلاة والصوم وعلى زوجها أن يمتنع من قربانها.. من غشيانها حتى تطهر، فإذا طهرت -ولو لعشرة أيام أو عشرين يوم- تباح لزوجها، ليس من شرط الطهارة أن تكمل أربعين، لا، لو طهرت وهي بنت عشرين أو بنت ثلاثين فالطهارة صحيحة تصلي وتصوم وتحل لزوجها، وليس للنفاس حد محدود -قبل الأربعين يعني- ليس له حد محدود؛ لأن النساء يختلفن، فقد تطهر المرأة لشهر وتطهر لخمسة وعشرين يوماً قد تطهر لأقل من ذلك، أو لأكثر من ذلك كل هذا واقع، والحكم مناط بالطهارة بانقطاع الدم ورؤية الطهارة، فإذا رأت الطهارة بانقطاع الدم ورؤية ما يدل على الطهارة بأن ترى الماء الأبيض أو بأن تحتشي بقطنة في فرجها ونحوها من البياض؛ فلا يتأثر، تخرجها ما تأثرت بشيء، هذه علامة الطهارة، فتغتسل وتصلي وتصوم وتحل لزوجها، ولو أنها ما مضى عليها من النفاس إلا عشرون يوماً أو ثلاثون يوماً.\nفإن استمر الدم حتى كملت الأربعين والدم معها فإن هذا الدم الزائد يعتبر دماً فاسداً من الأربعين، وتصلي وتصوم وتحل لزوجها، وتحفظ في هذا الدم بالقطن ونحوه، وتوضأ لكل وقت لكل صلاة كما تفعل المستحاضات، المستحاضات غير الحيض، المستحاضات الذين يستمر معهن الدم بعد الحيض، والحيض شيء والمستحضات شيء آخر، فالحيض هن اللاتي يجلسن وقت الحيض المعتاد يقال لها: حائض التي يأتيها الدم في وقتها المعتاد ويعتبر دمها حيضاً هذه تسمى حائض لا تصلي ولا تصوم ولا تحل لزوجها والمستحاضة هي التي تصاب بدم زائد على الحيض يستمر معها، هذا الدم الزائد يسمى استحاضة إذا جاء تغتسل وتصلي وتصوم، وإذا جاء وقت الحيض المعتاد وقفت عن الصلاة والصوم وحرمت على زوجها حتى تنتهي أيام الحيض.\nفهذه النفساء كذلك مثل الحائض في وقت النفاس -وقت الدم بالنفاس- لا تصلي ولا تصوم ولا تحل لزوجها، فإذا ذهب هذا الدم لشهر أو عشرين يوماً طهرت واغتسلت وصلت وصامت وحلت لزوجها، ولو ما كملت الأربعين، وهذا الدم الذي ليس فيه خلق الإنسان ليس له حكم الولد؛ لا يغسل ولا يصلى عليه ولا يدفن في مقابر المسلمين، كل هذا، أما إذا كان فيه خلق الإنسان فإنه يعتبر جنيناً ويكون لها حكم النفاس، لكن إذا كان ما نفخت فيه الروح -ما تحرك من بطن أمه- لا بأس أن يدفن في عرض البيت يحفر له في الحوش ويدفن لا حرج؛ لأنه ما صار له حكم الأموات حينئذٍ ما نفخت فيه الروح، ما بعد تحرك ببطن أمه، ليس له حكم الأموات، لكن له حكم الإنسان في وجوب النفاس في حكم النفاس فقط.\nأما إذا نفخت فيه الروح تحرك ثم ولدته ميتاً أو حياً ثم مات هذا يغسل ويكفن ويصلى عليه ويدفن في مقابر المسلمين، هذا الذي ينبغي، هذا هو تفصيل هذه المسألة. نعم.","link":"https://binbaz.org.sa/fatwas/4940/الاحكام-المتعلقة-بالسقط-اذا-كان-له-شهران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_041/04101.mp3","categories":["الحيض والنفاس"]},{"id":7889,"question":"نرحب بسماحة الشيخ، ونقول: يا سماحة الشيخ! إننا في لقائنا هذا سنكمل رسالة المستمع من حضرموت الذي سأل أسئلة عديدة ومفيدة في حلقات ماضية، فقد سأل عن الصلاة، وعن تفسير آيات، وعن زيارة القبور، وتعظيم الأولياء، أما في لقائنا هذا فيسأل عما يحل للرجل من امرأته حالة حيضها، يقول المستمع من حضرموت في رسالته هذه: أن رجلاً سأل الرسول ﷺ وقال له: ما يحل لي من امرأتي وهي حائض؟ قال له: شد إزارها، ثم عليك بأعلاها، نرجو رواية الحديث صحيحاً وتفسير معنى (إزارها)؟","title":"ما يحل للرجل من امرأته وهي حائض","answer":"الجواب: هذا الحديث مشهور عن معاذ  عن النبي ﷺ أنه سأله: ما يحل للرجل من امرأته وهي حائض ؟ قال: ما فوق الإزار يعني: صدرها وبطنها فوق السرة هذا هو الذي يحل له أن يباشر ذلك منها، لكن الحديث ضعيف، والصواب أنه يحل له كل شيء ما عدا الجماع، والحديث هذا ضعيف، والنبي ﷺ قال: اصنعوا كل شيء إلا النكاح رواه مسلم ، وكان يأمر عائشة ونساءه أن يأتزرن عندما يريد مباشرتهن، فهذا أفضل مستحب له أن يأمرها بالاتزار إذا أراد المباشرة؛ لأنه أبعد عن الوقوع فيما حرم الله، لكن ليس بواجب، الواجب: تجنب الوطء فإذا تجنب الوطء فلا بأس أن يباشر بدنها ولو مس فخذها أو مس فرجه فخذها لا يضر، الواجب بس الحذر مما حرمه الله من الجماع، وإذا أمرها بالاتزار فهو أفضل حتى يكون أبعد له عن الوقوع في المحرم، ولهذا كان النبي يأمر أزواجه عليه الصلاة والسلام أن يتزرن ويباشرهن عليه الصلاة والسلام كما أخبرت عائشة رضي الله عنها وغيرها.\nولكن المحرم هو الجماع لقوله فيما رواه مسلم عن أنس  أن النبي عليه السلام قال: اصنعوا كل شيء إلاا النكاح يعني: الجماع، كانت اليهود تغلو في هذا إذا حاضت المرأة لم يواكلوها ولم يشاربوها ولم يضاجعوها في الفراش وهذا من غلوهم فأنكر النبي ذلك عليه الصلاة والسلام وقال: اصنعوا كل شيء إلا النكاح يعني: إلا الجماع. نعم.","link":"https://binbaz.org.sa/fatwas/5353/ما-يحل-للرجل-من-امراته-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05901.mp3","categories":["الحيض والنفاس"]},{"id":7912,"question":"أيضاً لديها سؤال آخر، تقول: لقد صمت يوماً من أيام رمضان ولم يبق من ذلك اليوم إلا خمس دقائق عن موعد الإفطار وجاءتني الدورة الشهرية، فهل يجب علي أن أصلي صلاة المغرب قضاء بعد أن أطهر أم لا؟","title":"حكم من جاءتها الدورة قبل غروب الشمس في رمضان","answer":"الجواب: مادامت الدورة جاءتها قبل غروب الشمس فليس عليها صلاة المغرب ولا غيرها، والصوم لا يصح ذاك اليوم الذي جاء فيه الحيض قبل أن تغيب الشمس فإن الصوم يبطل وعليها قضاؤه، هذا إذا كانت تعلم أنها جاءتها قبل غروب الشمس ولو بخمس دقائق. نعم.","link":"https://binbaz.org.sa/fatwas/5394/حكم-من-جاءتها-الدورة-قبل-غروب-الشمس-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06203.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":7920,"question":"أيضاً يقول في رسالته: سمعت من بعض الناس يقولون: إذا جامع الرجل زوجته قبل أن تغلق الأربعين يوماً -يعني: من النفاس- كأنه يزني بها، وما الحكم لو فعل ذلك، هل يلزمه الكفارة أو التوبة إلى الله، وإذا جامعها وهي حائض يقولون نفس الكلام، أفيدونا جزاكم الله عنا كل خير؟","title":"حكم من جامع زوجته في حيض أو نفاس","answer":"الجواب: الحائض والنفساء لا يجوز للزوج جماعهما، حرام على الرجل أن يجامع زوجته في الحيض أو النفاس؛ لهذا الله سبحانه يقول: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ [البقرة:222]، فلا يجوز للزوج أن يأتي الزوجة في حال الحيض حتى تغتسل، تطهر وتغتسل من حيضها، ثم له أن يجامعها، وكذلك النفساء ليس له أن يأتيها في حال النفاس مادام الدم موجوداً فإذا طهرت واغتسلت جاز له جماعها ولو كانت في الأربعين، فلو طهرت لشهر واغتسلت جاز له أن يجامعها في العشر الباقية، فإن عليها أن تصلي وتصوم وتحل لزوجها في بقية الأربعين؛ لأن أقل النفاس ليس له حد، فقد تطهر لعشرين، وقد تطهر لثلاثين، وقد تطهر لأقل أو أكثر، فإذا طهرت واغتسلت عليها أن تصوم وتصلي ولزوجها أن يأتيها في وقت الطهر، أما في وقت الدم فلا.\nفإذا أكملت الأربعين وجب عليها أن تغتسل ولو كان الدم موجوداً، لو استمر معها الدم حتى كملت الأربعين فإنها تنتهي المدة، فعليها أن تغتسل ولو كان الدم جارياً وتصلي وتصوم وتعتبر هذا الدم دماً فاسداً لا يمنعها من صومها وصلاتها ولا يمنع زوجها من قربانها؛ لأن هذا الدم المستمر يعتبر دماً فاسداً بعد تمام الأربعين؛ لأن نهاية النفاس وتمامه الأربعون، فإذا انتهت الأربعون فإن النفاس قد انتهى فعلى المرأة أن تغتسل وعليها أن تصلي وتصوم إذا كان في رمضان، وتحل لزوجها ولو كان الدم جارياً؛ لأنه والحال ما ذكر يكون دم فساد لا يعتبر.\nوإذا جامع الرجل امرأته في الحيض أو في النفاس فقد أساء وأثم وأتى كبيرة من الكبائر، فالواجب عليه أن يتقي الله وأن يتوب إليه سبحانه وتعالى عما فعل، والتوبة تجب ما قبلها، وعليه مع ذلك في أصح قولي العلماء الكفارة، وهي نصف دينار أو دينار، إذا أتى زوجته في الحيض، ومثله النفاس، عليه الكفارة مع التوبة إلى الله والندم والإقلاع والعزم الصادق ألا يعود في ذلك، وعليه الكفارة وهي دينار أو نصف دينار من الذهب أو قيمته من الفضة، ومقدار نصف الدينار من الجنيه السعودي اليوم سهمان من سبعة، لأن الجنيه السعودي اليوم ديناران إلا ربع، يعني: مثقالان إلا ربع، فنصف الدينار منه سهمان من سبعة، والدينار أربعة من سبعة، فعليه أن يكفر بذلك إذا أتى زوجته وهي حائض أو نفساء، ينظر في صرف الجنيه السعودي فإذا عرف عند الصرافين يخرج مقدار سهمين من سبعة من صرف الجنيه، ويتصدق به على بعض الفقراء أو أربعة من سبعة من غير الدينار فيتصدق به على بعض الفقراء توبة إلى الله عز وجل وكفارة لما أتى من الوطء في الحيض أو النفاس وقت خروج الدم، أما بعد الطهر فليس في ذلك شيء، إذا طهرت واغتسلت من حيضها أو نفاسها حلت للزوج كما تقدم. نعم.","link":"https://binbaz.org.sa/fatwas/5426/حكم-من-جامع-زوجته-في-حيض-او-نفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06405.mp3","categories":["الحيض والنفاس"]},{"id":7921,"question":"هذه رسالة وردت من الحائرة (هـ. م)، تقول: امرأة صامت في رمضان، ولما جاء يوم من أيام رمضان وجاء المغرب وأذن المؤذن أفطرت، وبعد ذلك ذهبت للوضوء للصلاة، ولكنها وجدت العادة الشهرية قد جاءتها، فهل صيامها صحيح أم لا؟","title":"حكم من جاءتها الدورة بعد الغروب في رمضان","answer":"الجواب: إذا حصل الدم بعد غروب الشمس فإن الصوم صحيح، إذا لم تعلم وجود الدم إلا بعد غروب الشمس فإن الصوم صحيح ذلك اليوم، أما إن أتاها الدم قبل غروب الشمس وتيقنت ذلك فإن هذا الصوم لا يصح، بل عليها أن تعيده أن تقضيه، فينبغي أن يعلم ذلك.\nإن أتاها الدم بعد الغروب فصومها صحيح، أو لم تعلم ذلك إلا بعد الغروب فصومها صحيح، إذا كانت ما تعلم أنها حصل في النهار وإنما تيقنته في الليل فصومها صحيح، أما إن علمت أن الدم أصابها قبل غروب الشمس وأنه خرج منها شيء قبل غروب الشمس فإن هذا الصوم الذي خرج فيه الدم قبل غروب الشمس يكون غير صحيح، وعليها أن تقضيه بعد رمضان. نعم.\nالمقدم: مثل هذه الحالة المرأة لم تعلم إلا بعد أن ذهبت للوضوء بعد الإفطار.\nالشيخ: نعم.\nالمقدم: فإن شاء الله تعالى لا قضاء عليها.\nالشيخ: صومها صحيح.\nالمقدم: صومها صحيح.\nالشيخ: نعم.\nالمقدم: شكراً لسماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/5427/حكم-من-جاءتها-الدورة-بعد-الغروب-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06406.mp3","categories":["الحيض والنفاس"]},{"id":7924,"question":"أيضاً يقول في رسالته: سمعت من بعض الناس يقولون: إذا جامع الرجل زوجته قبل أن تغلق الأربعين يوماً -يعني: من النفاس- كأنه يزني بها، وما الحكم لو فعل ذلك، هل يلزمه الكفارة أو التوبة إلى الله، وإذا جامعها وهي حائض يقولون نفس الكلام، أفيدونا جزاكم الله عنا كل خير؟","title":"حكم من جامع زوجته في حيض أو نفاس","answer":"الجواب: الحائض والنفساء لا يجوز للزوج جماعهما، حرام على الرجل أن يجامع زوجته في الحيض أو النفاس؛ لهذا الله سبحانه يقول: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ [البقرة:222]، فلا يجوز للزوج أن يأتي الزوجة في حال الحيض حتى تغتسل، تطهر وتغتسل من حيضها، ثم له أن يجامعها، وكذلك النفساء ليس له أن يأتيها في حال النفاس مادام الدم موجوداً فإذا طهرت واغتسلت جاز له جماعها ولو كانت في الأربعين، فلو طهرت لشهر واغتسلت جاز له أن يجامعها في العشر الباقية، فإن عليها أن تصلي وتصوم وتحل لزوجها في بقية الأربعين؛ لأن أقل النفاس ليس له حد، فقد تطهر لعشرين، وقد تطهر لثلاثين، وقد تطهر لأقل أو أكثر، فإذا طهرت واغتسلت عليها أن تصوم وتصلي ولزوجها أن يأتيها في وقت الطهر، أما في وقت الدم فلا.\nفإذا أكملت الأربعين وجب عليها أن تغتسل ولو كان الدم موجوداً، لو استمر معها الدم حتى كملت الأربعين فإنها تنتهي المدة، فعليها أن تغتسل ولو كان الدم جارياً وتصلي وتصوم وتعتبر هذا الدم دماً فاسداً لا يمنعها من صومها وصلاتها ولا يمنع زوجها من قربانها؛ لأن هذا الدم المستمر يعتبر دماً فاسداً بعد تمام الأربعين؛ لأن نهاية النفاس وتمامه الأربعون، فإذا انتهت الأربعون فإن النفاس قد انتهى فعلى المرأة أن تغتسل وعليها أن تصلي وتصوم إذا كان في رمضان، وتحل لزوجها ولو كان الدم جارياً؛ لأنه والحال ما ذكر يكون دم فساد لا يعتبر.\nوإذا جامع الرجل امرأته في الحيض أو في النفاس فقد أساء وأثم وأتى كبيرة من الكبائر، فالواجب عليه أن يتقي الله وأن يتوب إليه سبحانه وتعالى عما فعل، والتوبة تجب ما قبلها، وعليه مع ذلك في أصح قولي العلماء الكفارة، وهي نصف دينار أو دينار، إذا أتى زوجته في الحيض، ومثله النفاس، عليه الكفارة مع التوبة إلى الله والندم والإقلاع والعزم الصادق ألا يعود في ذلك، وعليه الكفارة وهي دينار أو نصف دينار من الذهب أو قيمته من الفضة، ومقدار نصف الدينار من الجنيه السعودي اليوم سهمان من سبعة، لأن الجنيه السعودي اليوم ديناران إلا ربع، يعني: مثقالان إلا ربع، فنصف الدينار منه سهمان من سبعة، والدينار أربعة من سبعة، فعليه أن يكفر بذلك إذا أتى زوجته وهي حائض أو نفساء، ينظر في صرف الجنيه السعودي فإذا عرف عند الصرافين يخرج مقدار سهمين من سبعة من صرف الجنيه، ويتصدق به على بعض الفقراء أو أربعة من سبعة من غير الدينار فيتصدق به على بعض الفقراء توبة إلى الله عز وجل وكفارة لما أتى من الوطء في الحيض أو النفاس وقت خروج الدم، أما بعد الطهر فليس في ذلك شيء، إذا طهرت واغتسلت من حيضها أو نفاسها حلت للزوج كما تقدم. نعم.","link":"https://binbaz.org.sa/fatwas/5426/حكم-من-جامع-زوجته-في-حيض-او-نفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06405.mp3","categories":["الحيض والنفاس"]},{"id":7925,"question":"هذه رسالة وردت من الحائرة (هـ. م)، تقول: امرأة صامت في رمضان، ولما جاء يوم من أيام رمضان وجاء المغرب وأذن المؤذن أفطرت، وبعد ذلك ذهبت للوضوء للصلاة، ولكنها وجدت العادة الشهرية قد جاءتها، فهل صيامها صحيح أم لا؟","title":"حكم من جاءتها الدورة بعد الغروب في رمضان","answer":"الجواب: إذا حصل الدم بعد غروب الشمس فإن الصوم صحيح، إذا لم تعلم وجود الدم إلا بعد غروب الشمس فإن الصوم صحيح ذلك اليوم، أما إن أتاها الدم قبل غروب الشمس وتيقنت ذلك فإن هذا الصوم لا يصح، بل عليها أن تعيده أن تقضيه، فينبغي أن يعلم ذلك.\nإن أتاها الدم بعد الغروب فصومها صحيح، أو لم تعلم ذلك إلا بعد الغروب فصومها صحيح، إذا كانت ما تعلم أنها حصل في النهار وإنما تيقنته في الليل فصومها صحيح، أما إن علمت أن الدم أصابها قبل غروب الشمس وأنه خرج منها شيء قبل غروب الشمس فإن هذا الصوم الذي خرج فيه الدم قبل غروب الشمس يكون غير صحيح، وعليها أن تقضيه بعد رمضان. نعم.\nالمقدم: مثل هذه الحالة المرأة لم تعلم إلا بعد أن ذهبت للوضوء بعد الإفطار.\nالشيخ: نعم.\nالمقدم: فإن شاء الله تعالى لا قضاء عليها.\nالشيخ: صومها صحيح.\nالمقدم: صومها صحيح.\nالشيخ: نعم.\nالمقدم: شكراً لسماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/5427/حكم-من-جاءتها-الدورة-بعد-الغروب-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06406.mp3","categories":["الحيض والنفاس"]},{"id":7974,"question":"هذه الرسالة من المستمعة (ن. ش. ك) من الرياض تقول: السلام عليكم ورحمة الله وبركاته، أرجو عرض رسالتي هذه على سماحة الشيخ عبد العزيز بن عبد الله بن باز وفقه الله ورعاه آمين، ما حكم من واقع زوجته في حالة العادة الشهرية؟","title":"كفارة من واقع زوجته وهي حائض","answer":"الجواب: لا يجوز للمسلم أن يجامع زوجته في حال الحيض ولا في حال النفاس بإجماع المسلمين؛ لقول الله سبحانه: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ [البقرة:222]، فإتيان الحائض من المنكرات فيجب الحذر من ذلك، ومن فعل هذا فعليه التوبة إلى الله ، وهكذا مع النفساء قبل أن تطهر قبل أن ينقطع الدم وتطهر، فالحكم واحد في النفساء والحائض، فمن فعل شيئاً من ذلك فعليه التوبة إلى الله والرجوع إليه سبحانه والندم على ما فرط منه، وعليه مع هذا الكفارة وهي دينار أو نصف دينار يتصدق به على بعض المساكين، كما جاء في حديث ابن عباس أن النبي عليه الصلاة والسلام سئل عمن أتى امرأته وهي حائض، قال: يتصدق بدينار أو بنصف دينار خرجه الخمسة وصححه ابن خزيمة وغيره، فهو حديث صحيح يدل على أن من أتى زوجته وهي حائض -وهكذا النفساء في حكمها- فإنه قد عصى ربه عز وجل فعليه التوبة إلى الله والإنابة إليه والندم على ما مضى منه، والعزم أن لا يعود في ذلك، وعليه مع ذلك أن يتصدق بدينار أو بنصف دينار مخير.\nوالدينار مثقال من الذهب مقداره أربعة أسباع من الجنيه السعودي المعروف اليوم، أربعة أسباع من الجنيه السعودي يسمى دينار، ونصفه سبعان من الجنيه السعودي، أو قيمتها من الفضة والورق، يتصدق به على بعض الفقراء، فإذا كان الجنيه السعودي مثلاً يساوي سبعين فإن الدينار يكون أربعين، ونصفه يكون عشرين يتصدق به على الفقراء وهكذا، يعني: سهمان من سبعة من الجنيه السعودي هذا نصف الدينار وأربعة من سبعة من الجنيه السعودي فله الدينار، يتصدق به على بعض الفقراء إذا أتى امرأته وهي حائض، وعليه مع هذا التوبة إلى الله والإنابة إليه سبحانه وتعالى؛ لأن هذه معصية لا يجوز للرجل فعلها ولا يجوز للمرأة أن توافق على ذلك وأن تمكنه من ذلك، عليها أن تمتنع؛ لأن هذا من التعاون على طاعة الله ورسوله، وتهاونها بهذا وتسامحها في هذا من باب التعاون على الإثم والعدوان، نعم.\nالمقدم: في الحقيقة جاءت الإجابة على سؤالها الثاني لكن نريد أن ننص عليه لكي لا يكون عندها لبس في ذلك، تقول: إنني سمعت من كثير من زميلاتي بأن الزوجة التي يواقعها زوجها في هذه الحالة تطلق منه، فهل هذا صحيح أم لا وفقكم الله؛ لأنني في حيرة من هذا، مع شكري الجزيل، من المستمعة (ن. ش. ك) من الرياض؟\nالشيخ: لا، لا يكون طلاق، جماعه للحائض لا يكون طلاق، لكنه معصية ومنكر وعليه التوبة إلى الله من ذلك والكفارة، وهكذا -والعياذ بالله- جماع الدبر، لو جامعها في الدبر لا يكون طلاقاً لكنه معصية وجريمة يجب عليه التوبة إلى الله من ذلك، فالمرأة لا تؤتى في دبرها مطلقاً، ولا تؤتى في الحيض، ولا في النفاس، ولا وهي محرمة، ولا وهي صائمة صوم فرض، لا تؤتى في هذه الحالات، لا في حال صومها الفريضة كرمضان أو القضاء أو النذر، ولا تؤتى وهي محرمة بحج أو عمرة، يجب على زوجها الامتناع من ذلك، ولا تؤتى في حال صوم رمضان، ولا في صوم القضاء، ولا في حال الحيض والنفاس، المقصود: أنها لا تؤتى في هذه الحال، فإذا أتاها وهي حائض أو نفساء فعليه الكفارة مع التوبة إلى الله عز وجل، وهكذا لا يجوز إتيانها في دبرها مطلقاً؛ لأن الدبر محل القذر وليس محل الجماع، فلا يجوز إتيان النساء في أدبارهن بل ذلك محرم ومعصية ومن الكبائر، نسأل الله العافية والسلامة. نعم.\nولا تطلق بذلك، يعني: لا تطلق بكونه وطئها في دبرها، أو في الحيض، أو في النفاس لا تطلق، هي زوجته لكنه قد عصى ربه، فعليه التوبة إلى الله من ذلك، وليس لها أن تطاوعه في ذلك، لو أراد وطأها في الحيض أو في النفاس أو في الدبر يلزمها أن تمتنع من ذلك، ولا يجوز لها تمكينه من ذلك، بل تمتنع وتخوفه من الله وتقول: هذا لا يجوز، وهذا منكر وتأبى عليه ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5523/كفارة-من-واقع-زوجته-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_071/07104.mp3","categories":["الحيض والنفاس"]},{"id":7983,"question":"أيضاً تقول: إذا جاءت العادة الشهرية وزادت مدتها على كل شهر كالنزيف، فهل جائز للمرأة أن تصلي وتصوم أم لا؟","title":"حكم الصلاة والصوم للمرأة عند زيادة عادتها الشهرية","answer":"الجواب: إذا زادت العادة فالصواب: أنها تبع العادة، إذا كانت عادتها خمسة أيام فصارت ستاً، سبعاً، ثماناً، فالصواب أنها تجلس مادام الدم مستمراً فإنها تحسبها من العادة، تحسبها من العادة ولا تصلي ولا تصوم ولا يحل لزوجها أن يقربها في هذه الحالة؛ لأن العادة تزيد وتنقص، هذه عادة النساء تزيد وتنقص، فإذا زاد الدم جلست ولم تصل ولم تصم، وإذا نقص ورأت الطهارة اغتسلت وحلت لزوجها وصلت وصامت، هذا هو الصواب في هذه المسألة.\nأما إذا طهرت واغتسلت من حيضها ثم رأت صفرة أو كدرة فإن هذه الصفرة والكدرة لا تحسب شيئاً ولا تعد شيئاً بل تصلي معها وتصوم كما قالت أم عطية رضي الله عنها: كنا لا نعد الكدرة والصفرة بعد الطهر شيئاً، فإذا اغتسلت مثلاً بعد حيضها ثم رأت صفرة أو كدرة فإن هذه لا يعمل عليها ولا تمنعها من الصلاة ولا من الصوم ولا من زوجها، أما الدم الصاحي الدم الواضح فإنها تجلسه ولو انفصل، سواءً اتصل أو انفصل فإنها تجلسه تبعاً للعادة. نعم.","link":"https://binbaz.org.sa/fatwas/5529/حكم-الصلاة-والصوم-للمراة-عند-زيادة-عادتها-الشهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07204.mp3","categories":["الحيض والنفاس"]},{"id":8016,"question":"المستمعة المرسلة (م. ج. ب) من جدة تقول: أنا فتاة في العشرين من عمري وقد تأتيني آلام العادة الشهرية في رمضان قبل صلاة الظهر لدرجة أنني لا أستطيع الوقوف للصلاة حتى وأنا جالسة لا أستطيع الصلاة، ولا تأتيني العادة إلا قبل أذان المغرب بخمس دقائق، مع العلم أني أظل صائمة طوال النهار، فهل يجوز لي قضاء هذا اليوم أم أعتبر صائمة؟","title":"حكم من تأتيها العادة قبل غروب الشمس بوقت قصير","answer":"الجواب: إذا نزل الحيض وخرج الدم قبل غروب الشمس فاعتبري نفسك مفطرة وعليك أن تقضي هذا اليوم، أما التألم قبل ذلك فلا يبطل الصوم، التألم بقرب مجيء الدم لا يبطل الصوم، فإذا استمر معك التألم ولكن ما خرج شيء حتى غابت الشمس فالصوم صحيح ولا تقضي هذا اليوم، أما إن خرج الدم قبل غروب الشمس ولو بخمس دقائق فإن هذا اليوم يبطل ويجب قضاؤه عليك، هذا هو الحكم الشرعي فيما نعلم، وأما الآلام فهذه لها دواء ولها علاج ينبغي أن تسألي عنها الطبيبات والأطباء لعلك تجدين عندهم ما يريحك من هذا الألم الذي تحسين به. نعم..","link":"https://binbaz.org.sa/fatwas/5577/حكم-من-تاتيها-العادة-قبل-غروب-الشمس-بوقت-قصير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07604.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":8017,"question":"سؤالها الثاني تقول: تأتي لي العادة بكذا من الأيام في الشهر وتنقطع عني، لكن نص السؤال تقول: إننا ذهبنا إلى مكة المكرمة وقد أتتني العادة الشهرية، وحيث أنه لا يوجد لدينا في مكة من أبقى عنده فقد دخلت في الحرم وجلست فيه، هل علي شيء أم لا وشكراً لكم؟","title":"حكم مكوث الحائض في المسجد","answer":"الجواب: الواجب على من أصابها الحيض أن تبقى في محلها .. في مخيمها .. منزلها في الأبطح أو في غيره ولا تأتي إلى المسجد؛ لأن دخول الحائض المسجد لا يجوز إلا على سبيل المرور والعبور، وأما الجلوس عمداً في المسجد الحرام أو غيره من المساجد ما يجوز، لكن لو اضطرت لو جاءت وهي سليمة ليس فيها حيض ثم بليت بالحيض وهي في المسجد ولا تعرف أحداً تذهب إليه فإن الأولى بها أن تخرج وتجلس عند باب المسجد حتى يفرغ أصحابها ولا تجلس في المسجد، تعدهم باباً معروفاً فتجلس فيه حتى يأتوا وتذهب معهم مهما استطاعت إلى ذلك سبيلا، ولا تجلس في المسجد وهي حائض؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام قال: لا أحل المسجد لحائض ولا جنب فالمسجد لا يجلس فيه، لا يجلس فيه الحائض ولا الجنب، لكن عابر السبيل الذي يمر مرور لا بأس بذلك، فهي تجتهد وتحرص على أن تنتظرهم خارج المسجد عند الأبواب. نعم.","link":"https://binbaz.org.sa/fatwas/5578/حكم-مكوث-الحاىض-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07605.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":8672,"question":"تقول في سؤال آخر: قال الرسول ﷺ ما معناه لامرأة: اغسلي الدم وصلي أي: دم الحيض، فهل يكون هذا في أي وقت من أوقات نزول الدورة أم قرب انتهائها، وإذا اغتسلت وتطهرت منها وصليت فهل يحل الجماع أم لا؟","title":"معنى حديث: (اغسلي عنك الدم وصلي)","answer":"الجواب: هذا عند انتهاء الحيض، إذا انتهى الحيض أمرها النبي صلى الله عليه وسلم أن تغسل الدم وتغتسل وتصلي، إذا انتهت الدورة وفي ثوبها شيء غسلت ما أصاب الثوب، تقرصه بالماء تحكه بظفرها أو بحجر أو بعظم أو بغيره ثم تغسله بالماء ويطهر الثوب وتصلي فيه بعد ذلك، وكذلك إذا اغتسلت بعد ذلك بعد زوال الدم والطهر ووجود الطهر فإنها تصلي بعد ذلك وتحل لزوجها.\nالمقصود: أن هذا كله عند انتهاء الدورة إذا رأت الطهارة إما بالقصة البيضاء أو حشت بقطن ونحوه في الفرج فخرج نقياً فإنها تغتسل غسل الحيض وتغسل إن كان في بدنها شيء إذا كان أصاب فخذها أو رجلها شيء من الدم تغسله ثم تغتسل غسل الحيض وإذا أصاب ثوبها شيء أو سراويلها غسلته أيضاً وبعد هذا تصلي وتحل لزوجها. نعم.\nالمقدم: جزاكم الله خير، الحقيقة لها كلام بعد هذا يفهم منه أنها فهمت حديث الرسول صلى الله عليه وسلم بأن تغسل المرأة دمها وهي في أثناء الحيض ثم تصلي؛ لأنها تقول: هل كلما عاد علي الدم مرة أخرى طوال اليوم أغتسل وأصلي أم لا؟\nالشيخ: مادام الدم موجود لا تغتسلي، إنما الغسل يكون عند النهاية، أما مادام الدم يتكرر في الليل والنهار فأنت في الحيض حتى تنتهي المدة وتحصل الطهارة، فإذا انتهت المدة خمساً أو ستاً أو سبعاً أو ثمان حسب العادة، إذا انتهت العادة ورأت المرأة الطهارة ... الماء الأبيض، أو جعلت في فرجها شيء من القطن ثم أخرجته أو نحوه من الأشياء الدالة على نظافتها فإنها تغتسل، وتصلي وتحل لزوجها وتصوم إذا شاءت وانتهى الأمر، أما أنها تغتسل كل ساعة، لا ؛ لأن الدم يجري تارة ويقف أخرى ما دام المدة موجودة ما بعد انتهت المدة ولا رأت الطهارة فإنها لا تغتسل حتى تنتهي المدة وينقطع الدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6810/معنى-حديث-اغسلي-عنك-الدم-وصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21415.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":8674,"question":"تقول في سؤال آخر: قال الرسول ﷺ ما معناه لامرأة: اغسلي الدم وصلي أي: دم الحيض، فهل يكون هذا في أي وقت من أوقات نزول الدورة أم قرب انتهائها، وإذا اغتسلت وتطهرت منها وصليت فهل يحل الجماع أم لا؟","title":"معنى حديث: (اغسلي عنك الدم وصلي)","answer":"الجواب: هذا عند انتهاء الحيض، إذا انتهى الحيض أمرها النبي صلى الله عليه وسلم أن تغسل الدم وتغتسل وتصلي، إذا انتهت الدورة وفي ثوبها شيء غسلت ما أصاب الثوب، تقرصه بالماء تحكه بظفرها أو بحجر أو بعظم أو بغيره ثم تغسله بالماء ويطهر الثوب وتصلي فيه بعد ذلك، وكذلك إذا اغتسلت بعد ذلك بعد زوال الدم والطهر ووجود الطهر فإنها تصلي بعد ذلك وتحل لزوجها.\nالمقصود: أن هذا كله عند انتهاء الدورة إذا رأت الطهارة إما بالقصة البيضاء أو حشت بقطن ونحوه في الفرج فخرج نقياً فإنها تغتسل غسل الحيض وتغسل إن كان في بدنها شيء إذا كان أصاب فخذها أو رجلها شيء من الدم تغسله ثم تغتسل غسل الحيض وإذا أصاب ثوبها شيء أو سراويلها غسلته أيضاً وبعد هذا تصلي وتحل لزوجها. نعم.\nالمقدم: جزاكم الله خير، الحقيقة لها كلام بعد هذا يفهم منه أنها فهمت حديث الرسول صلى الله عليه وسلم بأن تغسل المرأة دمها وهي في أثناء الحيض ثم تصلي؛ لأنها تقول: هل كلما عاد علي الدم مرة أخرى طوال اليوم أغتسل وأصلي أم لا؟\nالشيخ: مادام الدم موجود لا تغتسلي، إنما الغسل يكون عند النهاية، أما مادام الدم يتكرر في الليل والنهار فأنت في الحيض حتى تنتهي المدة وتحصل الطهارة، فإذا انتهت المدة خمساً أو ستاً أو سبعاً أو ثمان حسب العادة، إذا انتهت العادة ورأت المرأة الطهارة ... الماء الأبيض، أو جعلت في فرجها شيء من القطن ثم أخرجته أو نحوه من الأشياء الدالة على نظافتها فإنها تغتسل، وتصلي وتحل لزوجها وتصوم إذا شاءت وانتهى الأمر، أما أنها تغتسل كل ساعة، لا ؛ لأن الدم يجري تارة ويقف أخرى ما دام المدة موجودة ما بعد انتهت المدة ولا رأت الطهارة فإنها لا تغتسل حتى تنتهي المدة وينقطع الدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6810/معنى-حديث-اغسلي-عنك-الدم-وصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21415.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":8853,"question":"إن أبي يقول لي: لماذا لم تصلي معي المغرب في رمضان، وأنا في حالة العذر، وبعد ذلك أقف معهم وأكبر، هل يجوز ذلك؟","title":"حكم صلاة المرأة وهي حائض","answer":"الجواب: إذا كنت في عذر الحيض الدورة الشهرية فليس لك ذلك، بل عليك أن تعتذري بأنك معذورة شرعًا من جهة الصلاة، أما إذا كنت سليمة وصار أبوك يصلي بكن مثلًا التراويح أو يصلي بكن الفريضة عند تخلفه عنها لأجل مرض أو لأنها فاتته في المسجد وصليتن معه فلا بأس، تصلي معهن خلفه، يكون أمامكن و يكون النساء خلفه فلا بأس بذلك.\nوليس له أن يصلي في البيت...إذا كان من غير عذر، بل يجب عليه أن يصلي في المساجد، أما النساء فبيوتهن خير لهن وأفضل، لكن لو فرض أنه تأخر لمرض أو علة أخرى حتى فاتته الصلاة في الجماعة، وصلى بكن الفريضة فلا بأس، وصلي معهن إذا كنت صالحة للصلاة، أما إذا كنت في نفاس أو في حيض فليس لك ذلك، والحمد لله هذا أمر شرعي فلا مانع من بيانه وأنك معذورة، وأنك في دورة في الدورة الشهرية أو في النفاس، توضحي نعم حتى لا تتهمي بترك الصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7008/حكم-صلاة-المراة-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16610.mp3","categories":["الحيض والنفاس"]},{"id":8899,"question":"شيخ عبدالعزيز، أذكر أنه في حلقة مضت عرضتُ على فضيلتكم سؤال عن المرأة وعذرها وقراءة القرآن ولا سيما أولئك النساء الذين اعتدن على قراءة القرآن الكريم قبل النوم وعند كثير من الأوقات، لازال هذا الموضوع حيًا ويسأل عنه كثير من الأخوات المستمعات، فهذه الأخت (ط. ص. ج. ج) من جيزان أبو عريش، أختنا أيضًا تسأل وتقول: هل يجوز للمرأة أن تقرأ القرآن الكريم في أيام عذرها، وهل لها أن تقرأ القرآن الكريم إذا آوت إلى النوم وتقرأ آية الكرسي بدون أن تلمس المصحف؟ نرجو من سماحة الشيخ أن يتفضل بإشباع هذا الموضوع حتى نبقى عن عرضه فترة من الزمن؟","title":"حكم قراءة الحائض والنفساء والجنب للقرآن الكريم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد سبق أن تكلمت في هذا الموضوع غير مرة في هذا البرنامج وبينت أنه لا بأس ولا حرج أن تقرأ المرأة وهي حائض أو نفساء ما تيسر من القرآن عن ظهر قلب؛ لأن الأدلة الشرعية دلت على ذلك، وقد اختلف العلماء رحمة الله عليهم في هذا، فمن أهل العلم من قال: إنها لا تقرأ كالجنب، واحتجوا بحديث ضعيف رواه أبو داود من حديث ابن عمر رضي الله تعالى عنهما عن النبي ﷺ أنه قال: لا تقرأ الحائض ولا الجنب شيئًا من القرآن وهذا الحديث ضعيف عند أهل العلم؛ لأنه من رواية إسماعيل بن عياش عن الحجازيين وروايته عنهم ضعيفة.\nوبعض أهل العلم قاسها على الجنب قال: كما أن الجنب لا يقرأ فهي كذلك؛ لأن عليها حدثًا أكبر يوجب الغسل فهي مثل الجنب.\nوالجواب عن هذا: أن هذا قياس غير صحيح؛ لأن حالة الحائض والنفساء غير حالة الجنب، الحائض والنفساء مدتهما تطول وربما شق عليهما ذلك وربما نسيتا الكثير من حفظهما للقرآن الكريم.\nأما الجنب فمدته يسيرة، متى فرغ من حاجته اغتسل وقرأ، فلا يجوز القياس.\nوالحاصل أن الصواب والراجح من قولي العلماء: أنه لا حرج على الحائض والنفساء أن تقرأا ما تحفظان من القرآن، ولا حرج أن تقرأ الحائض والنفساء آية الكرسي عند النوم، ولا حرج أن تقرأ ما تيسر من القرآن في جميع الأوقات عن ظهر قلب، هذا هو الصواب وهذا هو الأصل؛ ولهذا أمر النبي ﷺ عائشة لما حاضت قال لها: افعلي ما يفعله الحاج غير أن لا تطوفي بالبيت ولم يقل لها: غير أن لا تقرئي: غير أن لا تطوفي فمنعها من الطواف لأن الطواف كالصلاة وهي لا تصلي وسكت عن القراءة؛ فدل ذلك على أنها غير ممنوعة من القراءة ولو كانت القراءة ممنوعة لبينها لـعائشة ولغيرها من النساء في حجة الوداع وفي غير حجة الوداع.\nومعلوم أن كل بيت في الغالب لا يخلو من الحائض والنفساء فلو كانت لا تقرأ القرآن لبينه ﷺ للناس بيانًا عامًا واضحًا حتى لا يخفى على أحد.\nأما الجنب فإنه لا يقرأ القرآن بالنص، ومدته يسيرة متى فرغ تتطهر وقرأ، كان النبي ﷺ يذكر الله على كل أحيانه إلا إذا كان جنبًا انحبس عن القرآن حتى يغتسل عليه الصلاة والسلام كما قال علي : كان عليه الصلاة والسلام لا يحجبه شيء عن القرآن سوى الجنابة وجاء عنه عليه الصلاة والسلام أنه قرأ بعد ما خرج من محل الحاجة قرأ وقال: هذا: لمن ليس جنبًا، أما الجنب فلا ولا آية فدل ذلك على أن الجنب لا يقرأ حتى يغتسل. نعم.\nالمقدم: جزاكم الله خيرا، إذًا: فلتقرأ الأخت المسلمة القرآن الكريم على الصفة التي تفضلتم بذكرها، ولتقرأ البحوث والكتب الإسلامية وإن تضمن البحث آيات من القرآن الكريم.\nالشيخ: نعم .. نعم، من باب أولى، الكتب التي فيها القرآن.. مثل: كتب التفسير وكتب الخلاف بين العلماء كل هذا لا بأس به تقرأ ولا حرج. نعم.\nالمقدم: جزاكم الله عنا خيرًا.","link":"https://binbaz.org.sa/fatwas/7055/حكم-قراءة-الحاىض-والنفساء-والجنب-للقران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16801.mp3","categories":["الحيض والنفاس"]},{"id":8945,"question":"أختنا تتساءل سماحة الشيخ عن الحائض وحاجتها إلى قراءة القرآن ولاسيما إذا خشيت النسيان، ثم إنها تتساءل أيضًا عن الكتب التي تشتمل على بحوث ومن بينها آيات من القرآن الكريم، وترجو التوجيه حول هذا؟","title":"حكم قراءة الحائض للقرآن ومس الكتب المحتوية على الآيات","answer":"الجواب: اختلف العلماء رحمهم الله في جواز قراءة الحائض والنفساء للقرآن عن ظهر قلب، والصواب أنه لا حرج في ذلك، والصواب أنه يجوز للحائض أن تقرأ القرآن عن ظهر قلب وأن تقرأه النفساء أيضًا ولاسيما إذا خشيت النسيان فإن الأمر يكون آكد، والصواب أنه يجوز مطلقًا ولو لم تخش النسيان لكن لا تمس المصحف إنما تقرأ عن ظهر قلب، وإذا دعت الحاجة إلى مس المصحف من وراء حائل كلبس القفازين أو غيرهما مما يكون حائلًا بينها وبين المصحف للحاجة؛ كمراجعة آية أشكلت عليها أو ما أشبه ذلك فلا بأس بذلك.\nوهكذا الكتب التي فيها القرآن لا بأس بقراءتها مثل كتب التفسير، تراجم معاني القرآن كل هذا لا بأس به إنما الممنوع مس المصحف فقط من دون حائل، أما كونها تقرأ كتب فيها آيات تقرأ كتب التفسير فهذا لا حرج فيه، والصحيح أنها تقرأ الآيات أيضًا عن ظهر قلب مطلقًا. نعم.\nالمقدم: حتى وإن كانت معذورة؟\nالشيخ: ولو كانت معذورة، لها أن تقرأ وتدرس كتاب ربها عن ظهر قلب، تدرس الكتب المفيدة في التفسير وغيرها من كتب الحديث الشريف لكن لا تمس المصحف إلا من وراء حائل عند الحاجة إليه.\nأما الجنب فلا، أما الجنب فليس له مس المصحف ولا قراءة القرآن حتى يغتسل؛ لأن الرسول ﷺ كان لا يقرأ القرآن حتى يغتسل عليه الصلاة والسلام، ويقول في حق الجنب: ولا آية يعني: لا يقرأ ولا آية؛ لأن الجنب مدته يسيرة متى فرغ من حاجته استطاع أن يغتسل ويقرأ بخلاف الحائض فإن مدته تطول وليس الأمر بيدها إنما يحصل لها الطهر بعد انقطاع الدم ....... الطهارة.\nفالحاصل أن الحائض والنفساء ليستا مثل الجنب، مدتهما تطول وليس الأمر بأيديهما، أما الجنب فالأمر بيده متى فرغ استطاع أن يغتسل ويقرأ. نعم.","link":"https://binbaz.org.sa/fatwas/7103/حكم-قراءة-الحاىض-للقران-ومس-الكتب-المحتوية-على-الايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17207.mp3","categories":["الحيض والنفاس"]},{"id":8962,"question":"رسالة وصلت إلى البرنامج من اليمن بتوقيع إحدى الأخوات تقول: (م. ع. ع) أختنا تقول: إننا طالبات ندرس في مدرسة بنات، وفي حصة القرآن الكريم يأمرنا الأستاذ بقراءة القرآن ونكون في حالة العذر، ونستحيي أن نخبر الأستاذ فنقرأ مرغمات، هل يجوز لنا هذا، وإذا كان لا يجوز فكيف نعمل في أيام الامتحانات إذا صادفتنا ونحن في أيامنا، جزاكم الله خيراً؟","title":"حكم قراءة الحائض والنفساء للقرآن","answer":"الجواب: اختلف العلماء رحمة الله عليهم في قراءة الحائض والنفساء من القرآن الكريم، فذهب بعض أهل العلم إلى تحريم ذلك وألحقوهما بالجنب، وقالوا: ثبت عنه ﷺ أن الجنب لا يقرأ؛ لأن الجنابة حدث أكبر والحيض مثل ذلك والنفاس مثل ذلك، فقالوا: لا تقرأ الحائض ولا تقرأ النفساء حتى تطهرا، واحتجوا أيضاً بحديث رواه الترمذي عن ابن عمر أن النبي ﷺ قال: لا تقرأ الحائض ولا الجنب شيئاً من القرآن.\nوذهب آخرون من أهل العلم إلى أنه يجوز للحائض أن تقرأ والنفساء كذلك عن ظهر قلب؛ لأن مدتهما تطول، النفساء تأخذ أيام كثيرة والحائض كذلك تأخذ أيام وإن كانت النفساء أكثر منها، فلا يصح أن يقاس على الجنب، الجنب مدته قصيرة، إذا فرغ من حاجته في إمكانه أن يغتسل ويقرأ.\nأما الحائض فليس في إمكانها ذلك حتى ينقطع الدم وهكذا النفساء فهما في حاجة إلى القراءة، قالوا: والحديث الذي فيه: لا تقرأ الحائض ولا النفساء شيئاً من القرآن، حديث ضعيف، ضعفه أهل العلم لكونه من رواية إسماعيل بن عياش عن الحجازيين وروايته عنهم ضعيفة، وهذا القول هو الصواب أنه يجوز للحائض القراءة، وهكذا النفساء لما تقدم؛ لأن مدتهما تطول ولأن القياس على الجنب لا يصح، ولأن الحديث الذي فيه النهي عن القراءة ضعيف.\nفعلى هذا: لا بأس أن تقرأ الطالبة القرآن وهكذا المدرسة في الامتحان وفي غير الامتحان عن ظهر قلب، لا من المصحف بل عن ظهر قلب.\nأما إذا احتيج إلى المصحف فيكون من وراء حائل، تلبس قفازين، تلمسه من دون القفازين أو من وراء ثيابها الأخرى الصفيقة، وتفتش عند الحاجة للمصحف تنظر الآية، أو يحفظ عليها بعض زميلاتها حتى تقرأ إذا كانت لا تستطيع القراءة عن ظهر قلب.\nفالحاصل: أنه لا بأس أن تقرأ عن ظهر قلب على الصحيح.\nوهكذا من المصحف من وراء حائل كالقفازين في اليدين أو ثوب تجعله على اليدين، تلمسه به عند الحاجة، أو تحفظ عليها تمسك لها أختها الطاهرة حتى تطالع المصحف وهو في يد أختها الطاهرة، كل هذا لا حرج فيه إن شاء الله على الصحيح من أقوال أهل العلم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7121/حكم-قراءة-الحاىض-والنفساء-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_145/14506.mp3","categories":["الحيض والنفاس"]},{"id":9054,"question":"السؤال الثالث في رسالة الأخت: صالحة محمد علي أبو حسين من مكة المكرمة تقول فيه: ماذا تفعل المرأة إذا جاءتها العادة أو الدورة الشهرية في الحج، وماذا تفعل المرأة النفساء إذا وضعت مولودها في يوم الوقوف بعرفات؟ أفيدونا أفادكم الله.","title":"ماذا تفعل المرأة إذا أصابها الحيض في الحج؟","answer":"الجواب: كلتا الحادثتين وقعت في عهد النبي ﷺ، فقد حجت معه عائشة رضي الله عنها وأصابها الحيض، يعني: الدورة الشهرية، في مكة قبل الخروج إلى منى وعرفات، فأمرها النبي ﷺ أن تغتسل للنظافة وتلبي بالحج مع العمرة، وكانت قد دخلت للعمرة فجاءها الحيض في سرف موضع قرب مكة قبل أن تطوف قبل أن تسعى، فأمرها النبي ﷺ أن تلبي بالحج، وأن تدع العمرة وتكون بهذا قارنة بين الحج والعمرة ففعلت، فلما طافت وسعت يوم العيد، قال لها النبي ﷺ: طوافك بالبيت وبين الصفا والمروة يكفيك لحجك وعمرتك فأخبرها ﷺ أن عملها هذا يكفيها للحج والعمرة، وهو الطواف والسعي؛ لأنها دخلت العمرة في الحج، كما قال النبي ﷺ: دخلت العمرة في الحج إلى يوم القيامة فهذا شأن الحائض إذا أصابها الحيض قبل أن تطوف وتسعى للعمرة، فإنها تلبي بالحج، وتدخل ... العمرة وتكون قارنة ويكون عملها واحداً تطوف لحجها وعمرتها طوافاً واحداً سبعة أشواط وتسعى سعياً واحداً سبعة أشواط، ويكفي هذا في حجها وعمرتها.\nأما لو جاءها الحيض وقد فرغت من العمرة، بأن طافت وسعت وقصرت وحلت، ثم جاءها الحيض قبل خروجها إلى منى أو في منى أو في عرفات فإنها تكمل الحج، تفعل ما يفعل الحجاج كما قال النبي ﷺ لـعائشة: افعلي ما يفعل الحاج غير أن لا تطوفي بالبيت حتى تطهري، فأمرها أن تفعل ما يفعل الحجاج، غير ألا تطوف حتى تطهر.\nفتقف مع الناس في عرفات تذكر الله  وتدعو وتقف معهم في مزدلفة، تذكر الله وتدعو، ترمي الجمار يوم العيد وهكذا الأيام بعدها، أيام التشريق وتبيت بمنى أيام منى، تفعل ما يفعله الحجاج من كل شيء إلا أنها لا تطوف، تبقى عن الطواف حتى تطهر، فإذا طهرت اغتسلت وطافت لحجها وسعت، هذا هو المشروع لمن أصيبت بالدورة الشهرية وهي الحيض، فلا يمنعها هذا الحيض إلا من الطواف، والسعي يكون بعد هذا الأفضل، يؤجل معه السعي فإذا طهرت طافت وسعت ولو بعد أيام منى، لا يضرها ذلك، أما إذا كان الحيض أصابها قبل أن تحل من العمرة فقد تقدم البيان، وأنها تلبي بالحج مع العمرة وتكون قارنة، ويكفيها الطواف والسعي للأمرين جميعاً للحج والعمرة جميعاً كما تقدم.\nأما النفساء فهي مثل الحائض، فقد أصاب ذلك أسماء بنت عميس ، فإنها ولدت في الميقات في حجة النبي ﷺ، ولدت محمد بن أبي بكر ولدها محمد بن أبي بكر الصديق ، ولدته في ذي الحليفة، فأمرها النبي ﷺ أن تغتسل يعني: للنظافة، وأن تستنفر بشيء يحفظ عنها الدم، وأن تلبي مع الناس، ففعلت رضي الله عنها وأرضاها فاغتسلت ولبت مع الناس وحجت مع الناس، لكنها لا تطوف ولا تسعى حتى تطهر كما في حق الحائض، تفعل ما يفعل الحجاج من التلبية والذكر، والوقوف بعرفة يوم التاسع، والمبيت بمزدلفة ليلة العاشرة، ورمي الجمار يوم العيد وما بعده، والمبيت بمنى أيام منى، كل هذا تفعله النفساء كالحائض وكالطاهرات، لكن يبقى عليها الطواف والسعي، فإذا طهرت من نفاسها، ولو بعد أيام بمنى بأيام، تطوف وتسعى لحجها والحمد لله، كما فعلت أسماء بنت عميس بأمر النبي عليه الصلاة والسلام. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7206/ماذا-تفعل-المراة-اذا-اصابها-الحيض-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22405.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":9187,"question":"تسأل سؤال آخر لو تكرمتم سماحة الشيخ وتقول: هل يجوز الصلاة على النبي ﷺ للمرأة وهي في عذرها؟","title":"حكم الصلاة على النبي للحائض","answer":"الجواب: نعم، يجوز للمرأة أن تصلي على النبي ﷺ في جميع الأحوال وإن كانت في حال الحيض والنفاس كما تذكر الله سبحانه وتعالى، قالت عائشة رضي الله عنها: كان النبي ﷺ يذكر الله على كل أحيانه يعني: في حال الجنابة وغيرها، فإذا قالت الحائض: سبحان الله والحمد لله ولا إله إلا الله والله أكبر فهذا طيب، وهكذا النفساء، وهكذا إذا صلت على النبي ﷺ فإن الصلاة على النبي صلى الله عليه وسلم من ذكر الله.\nفالحائض والنفساء يشرع لهما ذكر الله والصلاة على النبي ﷺ وسلم في جميع الأحوال إلا في حال الجنابة فإنه لا يقرأ القرآن خاصة، وهكذا الرجل لا يقرأ القرآن في حال الجنابة، أما ما سوى القرآن من الذكر فإن الجنب والحائض والنفساء مشروع لهم الإكثار من ذكر الله سبحانه وتعالى، لكن يستثنى من ذلك الجنب فإنه لا يقرأ القرآن حتى يغتسل ولا يمس المصحف حتى يغتسل، وهكذا الحائض والنفساء لا تمسان المصحف إلا بعد الغسل، لكن لا بأس أن تقرأ عن ظهر قلب ؛ لأن مدتهما تطول ليستا مثل الجنب مدته قصيرة، فالحائض والنفساء مدتهما تطول فلا مانع من قراءتهما القرآن عن ظهر قلب في أصح قولي العلماء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7347/حكم-الصلاة-على-النبي-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15102.mp3","categories":["الحيض والنفاس"]},{"id":9368,"question":"السؤال الأخير الذي سنعرضه من رسالة الأخت أم مجاهد يقول: أقرأ في بعض الكتب أن قراءة القرآن دون وضوء جائزة، فمثلًا: في الموطأ حينما أتى عمر من قضاء الحاجة فسأله أحد عن الوضوء ثم القراءة فقال له: \"أي مسيلمة أخبرك هذا؟\" وفي كتب أخرى أقرأ تحريم قراءة القرآن دون وضوء.","title":"تفصيل أحوال الطهارة لقراءة القرآن","answer":"الشيخ: أعد مسيلمة أقرأك هذا؟\nالمقدم: كتبت هي أخبرك هذا.\nالشيخ: لعلها أخبرك مسيلمة الكذاب يعني.\nالمقدم: وفي كتب أخرى أقرأ تحريم قراءة القرآن دون وضوء فأيهما أصح يا سماحة الشيخ، جزاكم الله خيرا؟\nالشيخ: قراءة القرآن من المصحف تحتاج إلى وضوء، هذا الذي عليه أهل العلم، وهو قول أصحاب النبي ﷺ جميعًا؛ لما ثبت من حديث عمرو بن حزم  الأنصاري: أن النبي ﷺ كتب إلى أهل اليمن أن لا يمس القرآن إلا طاهر، وهو حديث جيد له طرق يشد بعضها بعضا، وهو دال على أن القرآن لا يمسه إلا من تطهر، كما قال : إِنَّهُ لَقُرْآنٌ كَرِيمٌ ۝ فِي كِتَابٍ مَكْنُونٍ ۝ لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:77-79] فهذه الآية تعم المصحف الذي في أيدينا والذي في أيدي الملائكة؛ ولهذا قال بعدها: تَنزِيلٌ مِنْ رَبِّ الْعَالَمِينَ [الواقعة:80] فالمنزل علينا لا يمسه إلا المطهرون.\nأما القراءة من دون مسيس بل عن ظهر قلب وهو الحفظ فهذه لا تحتاج إلى طهارة، لو قرأه ..على غير طهارة فلا بأس، إلا الجنب فإن الجنب لا يقرأ حتى يغتسل، لا من المصحف ولا عن ظهر قلب؛ لما ثبت عنه ﷺ: أنه كان لا يحجزه شيء عن القرآن إلا الجنابة ولما جاء عنه ﷺ قال لما خرج من الغائط قرأ وقال: هذا لمن لم يكن جنبا أما الجنب، فلا ولا آية.\nفالحاصل: أن القارئ للقرآن إن كان من المصحف فلابد من الطهارتين الكبرى والصغرى، من الجنابة والوضوء والحدث الأصغر، أما إن كان من غير المصحف بل عن ظهر قلب فإنه يقرؤه إذا كان ليس عليه جنابة، ولا يلزمه الطهارة الصغرى يقرأ وإن كان على حدث أصغر، أما إن كان جنبًا فإنه لا يقرأ حتى يغتسل، هذا هو الصواب في هذه المسألة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7532/تفصيل-احوال-الطهارة-لقراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18608.mp3","categories":["الحيض والنفاس","مس المصحف"]},{"id":9477,"question":"تسأل أيضاً وتقول: عندما تكون في مدة الحيض تقرأ من القرآن ما تحفظه من سور، فهل يجوز لها ذلك؟","title":"حكم قراءة الحائض والنفساء للقرآن عن ظهر قلب","answer":"الجواب: لا حرج في ذلك، فالصحيح من أقوال العلماء أنه يجوز للحائض أن تقرأ القرآن عن ظهر قلب، لكن لا تمس المصحف تقرأه عن ظهر قلبها؛ لأن مدة الحيض تطول والنفاس كذلك، فلا حرج أن تقرأ عن ظهر قلب، أما الجنب فلا، الجنب لا يقرأ حتى يغتسل؛ لأن مدته قصيرة وفي إمكانه أن يغتسل متى شاء بعد فراغه من حاجته، وهكذا المحدث حدث أصغر يقرأ عن ظهر قلب ولا يقرأ من المصحف حتى يتوضأ. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7638/حكم-قراءة-الحاىض-والنفساء-للقران-عن-ظهر-قلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24102.mp3","categories":["الحيض والنفاس"]},{"id":9586,"question":"وهذه رسالة من السائلة (ر. ط) من الرياض تقول: في أيام الحيض أحياناً يأتيني الدم في أوقات متقاربة وأحياناً لا ينقطع عني الدم نهائياً، فماذا أصنع؟ هل أغتسل وأصلي علماً بأنني لا أستطيع أن أحدد هذه الأوقات؛ لأنها لا تنضبط، وقد لا أجد فرصة للاغتسال؛ لأنه قد ينزل مني الحيض كما قلت لكم بغير انضباط عندما أريد أن أغتسل ينزل مني الحيض أحياناً، فماذا أفعل بالنسبة للصلاة، وقد تركت الصلاة في مرات سابقة ولم أغتسل، أفيدوني أفادكم الله؟","title":"أحكام المستحاضة","answer":"الجواب: إذا استمر الدم بالمرأة فإنها تكون مستحاضة، وتصلي وتصوم ولو معها الدم ولو كان معها الدم، مثل صاحب السلس الذي يستمر معه البول دائماً ولا ينقطع إلا في أشياء يسيرة، يصلي على حسب حاله دائماً، ويستنجي إذا دخل الوقت ويصلي في الوقت الفريضة والنوافل، ويمس المصحف ويقرأ القرآن حتى يأتي الوقت الآخر كالمستحاضة سواء؛ لأن النبي عليه الصلاة والسلام قال للمستحاضة: توضئي لكل صلاة والمستحاضة هي التي يستمر معها الدم ولا ينقطع إلا أشياء يسيرة، فهذه يقال لها: مستحاضة، فعليها أن تصلي ما فرض الله عليها وتصوم وتحل لزوجها؛ لأنها مبتلاة بهذا الدم المستمر، ولكن تجلس أيام الحيض المعتاد، إذا جاء وقت العادة التي تعرفها خمسة أيام ستة أيام سبعة أيام عادتها المعروفة تجلسها فلا تصلي ولا تصوم ولا تحل لزوجها، فإذا انتهت هذه الأيام المعتادة اغتسلت وصلت وصامت وحلت لزوجها، هذا هو الواجب في هذه المسائل. نعم.\nالمقدم: والحج كذلك؟\nالشيخ: والحج كذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7758/احكام-المستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24813.mp3","categories":["الحيض والنفاس"]},{"id":9592,"question":"وهذه رسالة من السائلة (ر. ط) من الرياض تقول: في أيام الحيض أحياناً يأتيني الدم في أوقات متقاربة وأحياناً لا ينقطع عني الدم نهائياً، فماذا أصنع؟ هل أغتسل وأصلي علماً بأنني لا أستطيع أن أحدد هذه الأوقات؛ لأنها لا تنضبط، وقد لا أجد فرصة للاغتسال؛ لأنه قد ينزل مني الحيض كما قلت لكم بغير انضباط عندما أريد أن أغتسل ينزل مني الحيض أحياناً، فماذا أفعل بالنسبة للصلاة، وقد تركت الصلاة في مرات سابقة ولم أغتسل، أفيدوني أفادكم الله؟","title":"أحكام المستحاضة","answer":"الجواب: إذا استمر الدم بالمرأة فإنها تكون مستحاضة، وتصلي وتصوم ولو معها الدم ولو كان معها الدم، مثل صاحب السلس الذي يستمر معه البول دائماً ولا ينقطع إلا في أشياء يسيرة، يصلي على حسب حاله دائماً، ويستنجي إذا دخل الوقت ويصلي في الوقت الفريضة والنوافل، ويمس المصحف ويقرأ القرآن حتى يأتي الوقت الآخر كالمستحاضة سواء؛ لأن النبي عليه الصلاة والسلام قال للمستحاضة: توضئي لكل صلاة والمستحاضة هي التي يستمر معها الدم ولا ينقطع إلا أشياء يسيرة، فهذه يقال لها: مستحاضة، فعليها أن تصلي ما فرض الله عليها وتصوم وتحل لزوجها؛ لأنها مبتلاة بهذا الدم المستمر، ولكن تجلس أيام الحيض المعتاد، إذا جاء وقت العادة التي تعرفها خمسة أيام ستة أيام سبعة أيام عادتها المعروفة تجلسها فلا تصلي ولا تصوم ولا تحل لزوجها، فإذا انتهت هذه الأيام المعتادة اغتسلت وصلت وصامت وحلت لزوجها، هذا هو الواجب في هذه المسائل. نعم.\nالمقدم: والحج كذلك؟\nالشيخ: والحج كذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7758/احكام-المستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24813.mp3","categories":["الحيض والنفاس"]},{"id":9928,"question":"هذه السائلة تقول في سؤال ثاني: قبل حلول الدورة الشهرية تأتي معي مادة بنية اللون تستمر خمسة أيام، وبعد ذلك يأتي الدم الطبيعي ويستمر الدم الطبيعي مدة ثمانية أيام بعد الأيام الخمسة الأولى، وتقول: أنا أصلي هذه الأيام الخمسة، ولكن أسأل: هل يجب علي صيام وصلاة هذه الأيام أم لا؟ أفيدوني أفادكم الله.","title":"حكم الصفرة والكدرة قبل الحيض أو بعده","answer":"الجواب: إذا كانت الأيام الخمسة البنية منفصلة عن الدم مقدمة، ولكنها منفصلة فلا بأس فيها تصومين وتصلين، لأنها كدرة وصفرة ما تمنع. وهكذا بعد الطهر إذا جاءت كدرة أو صفرة بعد الطهر لا تمنع صلاة ولا صيام، ولكنها تكون كالبول، تستنجين منها وتصلين، أما إذا كانت هذه البنية هذا الشيء البني يتصل يعني بعد الخامس متصلاً يقع الدم، وهكذا بعد الحيض يتصل بالدم، هذا من جملة العادة يكون من جملة العادة، فلا تصلين فيها ولا تصومين، إذا كانت الخمس متصلة بالحيض. أما إذا كان بينهما فاصل يوم أو نصف يوم وما أشبه ذلك، يعني فاصل بين تزول هذه الكدرة البنية تزول ويكون بعدها طهارة ثم يأتي الدم دم الحيض بعد ذلك، هذه منفصلة لا تعتبر حيضًا وعليك أن تصلي فيها، وأن تستنجي كل صلاة عند دخول الوقت تستنجين من هذه الكدرة البنية وتصلين. وهكذا لو جاءت بعد الطهر جاءت كدرة أو صفرة فتستنجين منها كل وقت وتصلين ولا يحتسب حيض. أما المتصل فإنه يحتسب حيض، المتصل قبل الحيض أو بعده متصلاً به هذا يحتسب منه. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8101/حكم-الصفرة-والكدرة-قبل-الحيض-او-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26906.mp3","categories":["الحيض والنفاس"]},{"id":9960,"question":"أخيراً تسأل عن حكم وضع الحناء بيدي المرأة التي لديها العذر الشرعي؟","title":"حكم استعمال الحائض والنفساء للحناء","answer":"الجواب: لا حرج في ذلك، لا حرج على المرأة أن تضع الحناء في يديها وهي في النفاس أو في الحيض لا يضر ذلك تتحنى في يديها أو في رأسها أو في رجليها لا حرج في هذا وإن كانت في حال الحيض. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8146/حكم-استعمال-الحاىض-والنفساء-للحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26606.mp3","categories":["الحيض والنفاس"]},{"id":9969,"question":"أخيراً تسأل عن حكم وضع الحناء بيدي المرأة التي لديها العذر الشرعي؟","title":"حكم استعمال الحائض والنفساء للحناء","answer":"الجواب: لا حرج في ذلك، لا حرج على المرأة أن تضع الحناء في يديها وهي في النفاس أو في الحيض لا يضر ذلك تتحنى في يديها أو في رأسها أو في رجليها لا حرج في هذا وإن كانت في حال الحيض. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8146/حكم-استعمال-الحاىض-والنفساء-للحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26606.mp3","categories":["الحيض والنفاس"]},{"id":9992,"question":"تسأل وتقول: هل يجوز للحائض دخول المسجد وإذا كان الدم قد انقطع عنها ولكنها لم تغتسل بعد فما الحكم؟","title":"حكم دخول الحائض والجنب المسجد","answer":"الجواب: إذا كان الدخول لحاجة تأخذ حاجة من المسجد، تأخذ سجادة من المسجد تأخذ عصا تأخذ نعلين تأخذ حاجة من المسجد لا بأس، أما الجلوس فيه لا تجلس النبي ﷺ قال لـعائشة: ناوليني الخمرة - الحصير الذي يصلي عليه سجادة- قالت: يا رسول الله! إني حائض قال: إن حيضتك ليست في يدك فأمرها بالدخول وأخذ الخمرة يعني: الحصير وهي حائض، وقال الله جل وعلا في هذا المعنى: وَلا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ [النساء:43] فالجنب كالحائض لا يدخل المسجد إلا عابر سبيل لا يجلس، فأذن الله في عابر السبيل الذي يمر مرور ويأخذ حاجة ويمر، سواءً من الجنب أو حائض أو نفساء، أما الجلوس لا، جاء في الحديث يقول ﷺ: إني لا أحل المسجد لحائض ولا جنب يعني: الجلوس فيه، ولهذا قال سبحانه: وَلا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ [النساء:43]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8164/حكم-دخول-الحاىض-والجنب-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30005.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":10034,"question":"تقول: أنا أحب قراءة القرآن وخاصة عندما أقوم بأعمال المنزل وفي كل الأوقات أحياناً، ولكن أثناء الدورة الشهرية أجد نفسي بدون شعور يردد لساني آيات من القرآن، وكذلك أقوم بالاستماع إلى الأشرطة أثناء الدورة الشهرية، فهل في ذلك حرج؟","title":"حكم قراءة القرآن للجنب والحائض والنفساء","answer":"الجواب: لا حرج في القراءة في أعمالك أعمال البيت، من طبخ أو غيره لا حرج، وكذلك لو قرأتي وأنت في حال الحيض أو النفاس الصواب لا حرج في ذلك عن ظهر قلب، لأن الحيض والنفاس ليس مثل الجنابة، الجنابة مدتها قصيرة يغتسل ويقرأ وهكذا المرأة تغتسل وتقرأ، لكن مدة الحيض تطول مدة النفاس تطول، والصواب أنه لا حرج في القراءة عن ظهر قلب وإذا احتاجت إلى مس المصحف من وراء حائل لمعرفة أخطائها وأغلاطها فلا بأس، أما سماع الأشرطة فلا حرج فيه بالكلية عند جميع أهل العلم، .......لا حرج في سماع الأشرطة أو سماع من يقرأ في إذاعة القرآن أو في المجلس يقرأ والحائض تستمع والنفساء تستمع والجنب يستمع هذا لا حرج فيه حتى الجنب يستمع لأنه ممنوع أن يقرأ هو أما كون الجنب يستمع لا حرج في ذلك والحائض تستمع لا حرج في ذلك والنفساء كذلك، فالأمر واسع في هذا والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8204/حكم-قراءة-القران-للجنب-والحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30108.mp3","categories":["الحيض والنفاس"]},{"id":10053,"question":"التي تغتسل من الحيض العصر هل تصلي الظهر والعصر أم العصر فقط؟","title":"حكم صلاة الظهر على من طهرت عند العصر","answer":"الجواب: نعم إذا اغتسلت الحائض في العصر تصلي الظهر والعصر، أفتى بهذا جماعة من الصحابة  وهكذا إذا اغتسلت في الليل في أوله أو في آخره تصلي المغرب والعشاء، لأن الظهر والعصر حكمهما حكماً واحداً في حق المعذور لأنهما يجمعان والمغرب والعشاء كذلك في حق المعذور حكمها حكم واحدة، في حق المعذور كالمريض فالحائض إذا اغتسلت كأنها المريض تصلي الظهر والعصر جميعاً تقضيهما وقت صلاة العصر، وتقضي المغرب والعشاء جميعاً إذا اغتسلت في أثناء الليل ولو بعد نصف الليل.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8216/حكم-صلاة-الظهر-على-من-طهرت-عند-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30301.mp3","categories":["الحيض والنفاس"]},{"id":10060,"question":"التي تغتسل من الحيض العصر هل تصلي الظهر والعصر أم العصر فقط؟","title":"حكم صلاة الظهر على من طهرت عند العصر","answer":"الجواب: نعم إذا اغتسلت الحائض في العصر تصلي الظهر والعصر، أفتى بهذا جماعة من الصحابة  وهكذا إذا اغتسلت في الليل في أوله أو في آخره تصلي المغرب والعشاء، لأن الظهر والعصر حكمهما حكماً واحداً في حق المعذور لأنهما يجمعان والمغرب والعشاء كذلك في حق المعذور حكمها حكم واحدة، في حق المعذور كالمريض فالحائض إذا اغتسلت كأنها المريض تصلي الظهر والعصر جميعاً تقضيهما وقت صلاة العصر، وتقضي المغرب والعشاء جميعاً إذا اغتسلت في أثناء الليل ولو بعد نصف الليل.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8216/حكم-صلاة-الظهر-على-من-طهرت-عند-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30301.mp3","categories":["الحيض والنفاس"]},{"id":10064,"question":"المستمعة (س) من الرياض بعثت تسأل وتقول: هل تغتسل المرأة من الاستحاضة التي بعد الحيض وإذا كان يجب الغسل فما الحكم فيمن كانت جاهلة بهذا؟","title":"حكم الغسل على المستحاضة","answer":"الجواب: الاغتسال من الاستحاضة مستحب وليس بواجب، الغسل الواجب من الحيض إذا انتهت مدته ورأت الطهارة تغتسل وجوباً كالجنب، أما الاستحاضة الدماء التي تأتيها بعد الحيض المستمر النزيف المستمر فهذا يستحب منه الغسل، لصلاتي الظهر والعصر والمغرب والعشاء غسلاً واحداً والفجر غسلاً واحداً، وإن تركت فلا حرج عليها لأن النبي ﷺ أوصى بهذا حمنة بنت جحش .\nأما الواجب فلا يجب عليها إلا غسل الحيض وغسل الجنابة أما الاستحاضة فيها الوضوء، على المرأة أن تتوضأ لكل صلاة، كما قال النبي ﷺ لـفاطمة بنت أبي حبيش وكانت مستحاضة: توضئي لوقت كل صلاة، لكن من اغتسل إذا اغتسلت فهو أفضل فالأفضل أن يكون للظهر والعصر غسلاً واحداً، أن تغتسل لوقت الظهر و العصر غسلاً واحداً، وأن تغتسل للمغرب والعشاء غسلاً واحداً وللفجر غسلاً واحداً هذا أفضل لأن الرسول ﷺ أوصى به حمنة رضي الله عنها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8233/حكم-الغسل-على-المستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30315.mp3","categories":["الغسل","الحيض والنفاس","شروح الحديث"]},{"id":10168,"question":"سماحة الشيخ! مما حفظته منكم يحفظكم الله أن المسلمة لا تترك قراءة القرآن في فترة الحيض والنفاس، هل تذكرون أختنا بهذا القول؟","title":"حكم قراءة القرآن للحائض والنفساء والجنب","answer":"الجواب: هذه مسألة خلاف بين أهل العلم هل تقرأ الحائض والنفساء أم لا؟ والأرجح: أنها تقرأ عن ظهر قلب؛ لأنها قد تنساه وتطول المدة، وقال بعض أهل العلم: ليس لها أن تقرأ إلا إذا خشيت النسيان، إذا خافت فلها أن تقرأ وإلا فلا، والأرجح والأقرب أن لها أن تقرأ عن ظهر قلب، ولها أن تراجع المصحف من وراء القفازين، من وراء الستر يعني عند الحاجة، هذا هو الأرجح لعدم الدليل على المنع.\nأما حديث أنه ﷺ قال: لا تقرأ الحائض ولا الجنب شيئاً من القرآن فهو حديث ضعيف في حق الحائض، أما الجنب فقد ثبت عنه ﷺ أنه كان لا يقرأ إذا كان جنب، كان لا يمنعه من القرآن شيء إلا الجنابة عليه الصلاة والسلام، ولم يحفظ عنه في شيء من الأحاديث أنه منع الحائض من القراءة أو النفساء، وقياسهما على الجنب لا يصح؛ لأن الجنب مدته يسيرة يغتسل ويقرأ، أما الحائض مدتها طويلة أسبوع أو أكثر، والنفساء مدتها طويلة أكثر وأكثر، فهذا قد يسبب نسيان ما حفظت، وأيضاً قد يسبب قسوة القلب، فكونها تقرأ وتتدبر القرآن عن ظهر قلب، وتراجع المصحف عند الحاجة، هذا خير لها في دينها ودنياها.\nالمقدم: بارك الله فيكم، يحفظكم الله، كما ذكرت الفتور، إذا خافت على نفسها الفتور من الانقطاع عن تلاوة القرآن، فما هو توجيهكم يحفظكم الله؟\nالشيخ: تحرص، تحرص على القراءة، وتجاهد نفسها على القراءة والذكر مهما أمكن، من باب المجاهدة، الله يقول: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، مع المجاهدة يعينها الله يعينها الله.\nالمقدم: إذاً مع خوف الفتور هذا يعني يبيح لها قراءة القرآن وإن كانت معذورة.\nالشيخ: .. لكن مثلما تقدم.\nالمقدم: نعم.\nالشيخ: مثلما تقدم التفصيل الجنب لا يقرأ حتى يغتسل وهي تقرأ لها القراءة، وإذا كانت تخشى النسيان آكد وآكد.\nالمقدم: بارك الله فيكم، جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8339/حكم-قراءة-القران-للحاىض-والنفساء-والجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27719.mp3","categories":["الحيض والنفاس"]},{"id":10211,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلينا من إحدى الأخوات المستمعات، تقول: أم أحمد ، أم أحمد عرضنا جزءاً من أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها مجموعة من الأسئلة، من بينها سؤال حول من أفطرت عدة رمضانات بسبب حال النفاس، ولم تقضها حتى الآن، كيف تتصرف؟ وتسأل: هل يجزئ ذلك الصيام في رجب، جزاكم الله خيراً؟","title":"حكم من أفطرت عدة رمضانات بسبب النفاس ولم تقضها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فالواجب على من أفطرت في رمضان من أجل النفاس أو الحيض القضاء قبل أن يأتي رمضان الآخر الذي بعده؛ لقول الله جل وعلا: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] والحائض والنفساء من جنس المريض والمسافر عليهما القضاء، فإذا طهرت من نفاسها، وطهرت من حيضها، تقضي والبدار أفضل، ولا يجوز لها التأخير إلى رمضان، بل يجب أن تبادر حتى تقضي ما عليها قبل رمضان، ولا مانع أن تصوم في رجب أو غيره، ولا حرج أن تؤخر إلى شعبان، قالت عائشة رضي الله عنها: كان يكون علي الصوم من رمضان، فلا أستطيع أن أقضي إلا في شعبان .\nفالواجب على المرأة أن تعتني بهذا الأمر، وأن تبادر بالقضاء قبل رمضان، ولو مفرقاً، ولو موزعاً، لا يجب التتابع، فتصوم وتفطر حتى تكمل، وإذا أخرته عن رمضان وجب عليها التوبة من ذلك، وعليها القضاء والإطعام، إطعام مسكين عن كل يوم، نصف صاع عن كل يوم من التمر أو غيره من قوت البلد، مقداره كيلو ونصف تقريباً، كفارة عن التأخير، فيكون عليها ثلاثة أشياء: التوبة، وقضاء الصيام، مع الإطعام عن كل يوم؛ إذا كان التأخير لغير عذر.\nأما إن كان أخرت ذلك لمرض لم تستطع معه الصوم، فلا حرج عليها، تصوم بدون إطعام، تقضي بدون إطعام، وليس عليها إثم، لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]سبحانه وتعالى، والواجب على المؤمنة أن تتقي الله، وأن تعتني بقضاء ما عليها، وأن تتحرى الأوقات التي تستطيع فيها القضاء قبل أن يأتي رمضان، حتى تفرغ من ذلك قبل أن يأتي رمضان الدائر الذي هو بعد رمضان الذي أفطرت فيه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8381/حكم-من-افطرت-عدة-رمضانات-بسبب-النفاس-ولم-تقضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31001.mp3","categories":["قضاء الصيام","الحيض والنفاس","قضايا المرأة"]},{"id":10218,"question":"من ليبيا إحدى الأخوات المستمعات بعثت برسالة تسأل فيها جمعاً من الأسئلة، في أحدها تقول: في اليوم السادس، وبعد انقضاء مدة العذر الشرعي يخرج منها سائل أبيض مائل إلى الاحمرار، فهل يجب الغسل منه أم لا؟","title":"حكم خروج الكدرة والصفرة بعد الطهر من الحيض","answer":"الجواب: إذا كان هذا بعد الطهر لا يجب عليها شيء، بل هذا مثل البول عليها أن تستنجي وتتوضأ وضوء الصلاة، لقول أم عطية رضي الله عنها، -وهي صحابية جليلة-: كنا لا نعد الكدرة والصفرة بعد الطهر شيئاً.\nفإذا كان بعد الطهر ورأت سائلاً فيه صفرة أو كدرة، فلا عبرة به، بل هو كالبول، تستنجي وتتوضأ وضوء الصلاة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8394/حكم-خروج-الكدرة-والصفرة-بعد-الطهر-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31009.mp3","categories":["الحيض والنفاس"]},{"id":10222,"question":"من ليبيا إحدى الأخوات المستمعات بعثت برسالة تسأل فيها جمعاً من الأسئلة، في أحدها تقول: في اليوم السادس، وبعد انقضاء مدة العذر الشرعي يخرج منها سائل أبيض مائل إلى الاحمرار، فهل يجب الغسل منه أم لا؟","title":"حكم خروج الكدرة والصفرة بعد الطهر من الحيض","answer":"الجواب: إذا كان هذا بعد الطهر لا يجب عليها شيء، بل هذا مثل البول عليها أن تستنجي وتتوضأ وضوء الصلاة، لقول أم عطية رضي الله عنها، -وهي صحابية جليلة-: كنا لا نعد الكدرة والصفرة بعد الطهر شيئاً.\nفإذا كان بعد الطهر ورأت سائلاً فيه صفرة أو كدرة، فلا عبرة به، بل هو كالبول، تستنجي وتتوضأ وضوء الصلاة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8394/حكم-خروج-الكدرة-والصفرة-بعد-الطهر-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31009.mp3","categories":["الحيض والنفاس"]},{"id":10231,"question":"المستمع أحمد زيدان شهاب بعث يسأل جمعاً من الأسئلة، في أحدها يقول: هل يجوز للمسلم غير المتوضئ أن يقرأ القرآن الكريم، وهل يسمح أيضاً للنساء إذا كن في أعذارهن أو في حالة النفساء أن يقرأن القرآن الكريم جزاكم الله خيرا.","title":"حكم قراءة القرآن للمحدث حدثاً أصغر والجنب والحائض والنفساء","answer":"الجواب: الرجل والمرأة له القراءة إذا كان على غير وضوء، يقرأ عن ظهر قلب من غير المصحف، يقرأ الرجل وإن كان ليس على طهارة إذا لم يكن جنب إذا كان ماهو بعلى وضوء، قد أتى بول أو غائط أو ريح له القراءة عن ظهر قلب، ولكن لا يقرأ من المصحف لا الرجل ولا المرأة حتى يتوضأ، أما الجنب لا، لا يقرأ لا من المصحف ولا عن ظهر قلب، إذا كان جنب لا يقرأ حتى يغتسل، كان النبي ﷺ لا يحجبه عن القرآن شيء إلا الجنابة.\nأما الحائض والنفساء فاختلف العلماء في شأنهما، فأكثر أهل العلم على أنها تمنع من القراءة حتى تطهر، وقال بعضهم: لها أن تقرأ إذا خافت النسيان، إذا خافت نسيانه لها أن تقرأ وإلا فلا.\nوالصواب: أن لها أن تقرأ عن ظهر قلب؛ لأن مدتها تطول ما هي مثل الجنب، الجنب يغتسل في الحال ويقرأ، لكن المرأة الحائض تأخذ مدة أسبوع أو نحوه، والنفساء تأخذ مدة أطول، فهذه لها أن تقرأ؛ لأنه يخشى عليها أن تنسى ما حفظت، والمقصود أنه ليس هناك دليل واضح في منع الحائض والجنب من القراءة عن ظهر قلب، فالصواب: أن لهما أن تقرأا عن ظهر قلب لا من المصحف، لكن إذا دعت الحاجة لمراجعة الآية من المصحف من وراء القفازين من وراء حائل فلا بأس.\nالمقدم: جزاكم الله خيرا، الحائض والجنب أو الحائض والنفساء سماحة الشيخ؟\nالشيخ: الحائض والنفساء.\nالمقدم: الحائض والنفساء.\nالشيخ: لهما أن تقرأا عن ظهر قلب. هذا هو الصواب، لا من المصحف عن ظهر قلب، لكن إذا دعت الحاجة لمراجعة المصحف، لمراجعة آية أو نحوها من وراء حائل، من وراء القفازين مثلاً. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8397/حكم-قراءة-القران-للمحدث-حدثا-اصغر-والجنب-والحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27809.mp3","categories":["الحيض والنفاس","القرآن وعلومه","قضايا المرأة"]},{"id":10246,"question":"يسأل بالنسبة للمرأة هل إذا أرادت قراءة الأحاديث النبوية يشترط عليها الطهارة أو لا تشترط؟","title":"حكم اشتراط الطهارة عند قراءة الأحاديث النبوية","answer":"الجواب: الطهارة تشترط لمس المصحف، أما القراءة من غير مس المصحف أو التسبيح والتهليل والذكر فلا يشترط لها طهارة، كان النبي ﷺ يذكر الله على كل أحيانه، كان النبي ﷺ يذكر الله على كل أحيانه، حتى ولو كان على جنب، حتى الحائض والنفساء، لكن القراءة قراءة القرآن لا يقرأها الجنب مطلقًا، ولا يمس المصحف إلا من كان طاهرًا من الحدثين، من الجنابة والحدث الأصغر؛ لقوله ﷺ: لا يمس القرآن إلا طاهر.\nوالحائض والنفساء لهما أن تقرأا عن ظهر قلب غيب، لأن المدة تطول، ليست تابعة للجنب، الجنب لا يقرأ مطلقًا حتى يغتسل، أما الحائض والنفساء فمدتهما تطول، فالصحيح أنهما يقرأان من دون مس المصحف، فإن احتاجتا إلى مس المصحف جاز من دون حائل، يعني: من وراء حائل كالقفازين، لمراجعة بعض الآيات ونحو ذلك. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8417/حكم-اشتراط-الطهارة-عند-قراءة-الاحاديث-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27904.mp3","categories":["الحيض والنفاس","مس المصحف"]},{"id":10268,"question":"سمعت من يقول في قراءة المرأة للقرآن وهي في عذرها أنه يجوز للمرأة قراءة وردها من القرآن وإن كانت معذورة، فما هو الورد؟","title":"يجوز للحائض والنفساء قراءة القرآن عن ظهر قلب","answer":"الجواب: نعم. نعم يجوز لها أن تقرأ القرآن على الصحيح، لكن من دون مس المصحف عن ظهر قلب، تقرأ آية الكرسي عند النوم، تقرأ: (قُلْ هُوَ اللَّهُ أَحَدٌ) والمعوذتين عند النوم ثلاث مرات، كل هذا مشروع، تأتي بالأذكار الشرعية في الصباح والمساء، كل ذلك مشروع، وإن كانت في نفاس أو في حيض. نعم.","link":"https://binbaz.org.sa/fatwas/8439/يجوز-للحاىض-والنفساء-قراءة-القران-عن-ظهر-قلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33708.mp3","categories":["الحيض والنفاس"]},{"id":10368,"question":"بالنسبة لصلاة الظهر يوم الجمعة للمرأة التي اعتادت أن تصلي أربع ركعات قبل الظهر هل تصليها أيضًا يوم الجمعة؟","title":"حكم صلاة النافلة للمرأة قبل صلاة الظهر يوم الجمعة","answer":"الجواب: نعم تصلي ما شاءت تصلي أربعًا أو ثمانًا أو أكثر من ذلك ليس لها حد محدود، لا في يوم الجمعة ولا في غيرها، والرجل كذلك، يصلي ما قسم الله له، ركعتين أو يصلي أربع ركعات أو ست ركعات أو ثمان ركعات أو أكثر.\nلكن الأفضل أن يسلم من كل ثنتين، وهكذا الأنثى تسلم من كل ثنتين هذا هو الأفضل، لما روى الخمسة وهم أهل السنن وأحمد رحمة الله عليهم عن النبي ﷺ أنه قال: صلاة الليل والنهار مثنى مثنى هذا هو الأفضل، وأقل شيء ركعتان الضحى هذا هو الأفضل أقل المشروع ركعتان يركعهما من الضحى في الجمعة أو في غيرها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8540/حكم-صلاة-النافلة-للمراة-قبل-صلاة-الظهر-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33902.mp3","categories":["صلاة التطوع","الحيض والنفاس","قضايا المرأة"]},{"id":10469,"question":"تقول: كثير من النساء عند بداية الدورة الشهرية تضطرب أفكارهن ولا يعرفن الأحكام، وترجو التوجيه لمثل هؤلاء، جزاكم الله خيراً؟","title":"بعض أحكام الدورة الشهرية عند النساء","answer":"الجواب: الواجب عليهن إذا بدأت الدورة ترك الصلاة والصيام وكذلك مس المصحف للقراءة؛ لأن الحائض ممنوعة من الصلاة والصوم كما أنها ممنوعة من الجماع، ولا ينبغي في هذا التردد، الله يقول جل وعلا: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ [البقرة:222] والنبي ﷺ قال: اصنعوا كل شيء إلا النكاح يعني: في حق الحائض، وهكذا النفساء، فليس له أن يجامعها، لكن له أن ينام معها وله أن يقبلها، وله أن يباشرها لا بأس، لكن ليس له الجماع في حق الحائض والنفساء، وعليهن.. على الحيض والنفساء عليهن تقوى الله سبحانه وتعالى بأن يجتنبن ما حرم الله عليهن من الصلاة حال الحيض، الصوم الجماع في حال الحيض، كل هذا ممنوع.\nوإذا طهرن صلين بعد ذلك وقضين الصيام الذي عليهن من رمضان، قد يسقط عنهن فعله ولكن ما يسقط وجوبه، بل عليهن قضاؤه بعد ذلك، قضاء الصوم خاصة، أما الصلاة تسقط ولا تقضى، وإذا جاءت الدورة فعليها أن تمسك في الحال عن الصلاة والصوم، وإذا كانت صائمة بطل الصوم. نعم.","link":"https://binbaz.org.sa/fatwas/8648/بعض-احكام-الدورة-الشهرية-عند-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32016.mp3","categories":["الحيض والنفاس"]},{"id":10592,"question":"تقول في سؤالها الأخير: إذا أتى المرأة عذرها لمدة أربعة أيام ثم انقطع عنها واغتسلت لظنها أنها قد طهرت وصامت ليوم كامل، وفي اليوم التالي عاودها العذر مرة أخرى، فهل عليها قضاء ذلك اليوم أم لا؟","title":"حكم صيام من انقطع حيضها ثم عاودها ثانية","answer":"الجواب: ليس عليها قضاء ذلك اليوم، إذا كان الدم ارتفع عنها ذلك اليوم ولم تر دماً إلا بعد غروب الشمس، فإن ذلك اليوم صومه صحيح، والدم الذي عاد عليها بعد ذلك اليوم يعتبر دم الحيض إذا كان في العدة في أيام العادة، أما إن كان خارج العادة، بأن كانت عادتها أربعة أيام وطهرت ثم جاءها دم بعد اليوم الخامس الذي طهرت فيه، فهذا فيه تفصيل: فإن كان كدرة أو صفرة فإنه لا عمل عليه تصلي وتصوم وتوضأ لكل صلاة، أما إن كان دماً صحيحاً فإنه تابع للحيض، يكون حيضاً تابعاً للأول، واليوم الذي فيه الطهارة يوم صحيح صومه صحيح والحمد لله.\nالمقدم: جزاكم الله خيراً","link":"https://binbaz.org.sa/fatwas/8764/حكم-صيام-من-انقطع-حيضها-ثم-عاودها-ثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32502.mp3","categories":["الحيض والنفاس"]},{"id":10596,"question":"تقول في سؤالها الأخير: إذا أتى المرأة عذرها لمدة أربعة أيام ثم انقطع عنها واغتسلت لظنها أنها قد طهرت وصامت ليوم كامل، وفي اليوم التالي عاودها العذر مرة أخرى، فهل عليها قضاء ذلك اليوم أم لا؟","title":"حكم صيام من انقطع حيضها ثم عاودها ثانية","answer":"الجواب: ليس عليها قضاء ذلك اليوم، إذا كان الدم ارتفع عنها ذلك اليوم ولم تر دماً إلا بعد غروب الشمس، فإن ذلك اليوم صومه صحيح، والدم الذي عاد عليها بعد ذلك اليوم يعتبر دم الحيض إذا كان في العدة في أيام العادة، أما إن كان خارج العادة، بأن كانت عادتها أربعة أيام وطهرت ثم جاءها دم بعد اليوم الخامس الذي طهرت فيه، فهذا فيه تفصيل: فإن كان كدرة أو صفرة فإنه لا عمل عليه تصلي وتصوم وتوضأ لكل صلاة، أما إن كان دماً صحيحاً فإنه تابع للحيض، يكون حيضاً تابعاً للأول، واليوم الذي فيه الطهارة يوم صحيح صومه صحيح والحمد لله.\nالمقدم: جزاكم الله خيراً","link":"https://binbaz.org.sa/fatwas/8764/حكم-صيام-من-انقطع-حيضها-ثم-عاودها-ثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32502.mp3","categories":["الحيض والنفاس"]},{"id":10601,"question":"هل يجوز للمرأة أن تتعاطى علاجاً يمنع عنها العذر الشرعي إذا كانت تريد الحج؟","title":"حكم تعاطي المرأة علاجاً يمنع الحيض في الحج ورمضان","answer":"الجواب: لا أعلم مانعاً من ذلك، تتعاطى ما يمنع الحيض في حال الحج أو العمرة أو في شهر رمضان حتى تصوم مع الناس كل هذا لا حرج فيه إن شاء الله نعم، إذا كان لا يترتب عليه ضرر، إذا كانت الحبوب التي تتعاطاها لا يترتب عليها ضرر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8777/حكم-تعاطي-المراة-علاجا-يمنع-الحيض-في-الحج-ورمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32604.mp3","categories":["الحيض والنفاس","الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":10610,"question":"هل يجوز للمرأة أن تتعاطى علاجاً يمنع عنها العذر الشرعي إذا كانت تريد الحج؟","title":"حكم تعاطي المرأة علاجاً يمنع الحيض في الحج ورمضان","answer":"الجواب: لا أعلم مانعاً من ذلك، تتعاطى ما يمنع الحيض في حال الحج أو العمرة أو في شهر رمضان حتى تصوم مع الناس كل هذا لا حرج فيه إن شاء الله نعم، إذا كان لا يترتب عليه ضرر، إذا كانت الحبوب التي تتعاطاها لا يترتب عليها ضرر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8777/حكم-تعاطي-المراة-علاجا-يمنع-الحيض-في-الحج-ورمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32604.mp3","categories":["الحيض والنفاس","الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":10781,"question":"هذه الرسالة وردتنا من المرسلة (هـ. م. ن) من الربيعية تسأل عن لمس القرآن للحائض تقول: إني طالبة وفي درس القرآن إذا كنت لست طاهرة لا أقرأ ولا ألمسه ولكن في دروس التفسير والفقه والتوحيد وغيره من الدروس التي تكثر بها الآيات القرآنية فأنا أقرأ وأكتب وأحل الأسئلة فهل يجوز لي ذلك، وإذا كان لا يجوز فماذا أفعل إذا توقفت كل شهر عن المذاكرة وخاصة أيام الامتحان؟","title":"حكم قراءة ولمس الحائض للقرآن","answer":"الجواب: الصواب من أقوال العلماء أنه لا حرج في ذلك، أنه لا حرج على الحائض أن تقرأ والنفساء كذلك، أما الجنب فلا، كان النبي ﷺ لا يحجزه شيء عن القرآن إلا الجنابة، ولم يثبت عنه النهي عن قراءة الحائض للقرآن، والفرق بينهما أن الحائض مدتها تطول وهكذا النفساء، أما الجنب فمدته لا تطول، في إمكانه إذا فرغ من حاجته أن يغتسل ويقرأ ويصلي، أما الحائض فلها مدة لا تستطيع فيها الغسل حتى تنتهي الدورة حتى ينقطع الدم وترى الطهر فهي محتاجة إلى أن تقرأ، والنبي ﷺ قال في حق الحائض في الحج افعلي ما يفعل الحاج غير ألا تطوفي بالبيت حتى تطهري فلم ينهاها إلا عن الطواف، لا تطوف حتى تطهر ولم يقل لها لا تقرئي. فدل ذلك على أنها لا بأس أن تقرأ القرآن ولا بأس أن تقرأ كتب التفسير والآيات التي في كتب التفسير وهكذا الآيات التي في الكتب الأخرى، من كتب الفقه، كتب الحديث لا حرج في ذلك.\nلكن لا تمس المصحف، أما المصحف لا تمسه حتى تطهر، وإذا احتاجت يكون من وراء الحائل، أو يمسه غيرها لها حتى تراجع ما أشكل عليها من الآيات، أما أن تقرأه عن ظهر قلب فلا حرج في ذلك على الصحيح من أقوال العلماء كما تقدم. نعم.","link":"https://binbaz.org.sa/fatwas/8957/حكم-قراءة-ولمس-الحاىض-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35003.mp3","categories":["الحيض والنفاس"]},{"id":11115,"question":"بالنسبة للمعذورة شرعًا، هل لها أن تقرأ القرآن الكريم من وراء حائل؟","title":"حكم قراءة الحائض والنفساء القرآن","answer":"الجواب:  المعذورة بالحيض والنفاس تقرأ عن ظهر قلب، حفظها من القرآن، وإن قرأت من وراء حائل كالقفازين فلا حرج، لكن تركه، الأحوط أن تقرأ عن ظهر قلب، إلا إذا أشكل عليها شيء وراجعت المصحف من طريق القفازين ونحوهما فلا حرج، إن شاء الله. وذهب أكثر أهل العلم إلى المنع، وشبهوها بالجنب، والصواب: أنها لا تكون كالجنب، الجنب مدته قصيرة يغتسل ويقرأ، أما الحائض والنفساء فمدتهما تطول، فالقياس لهما على الجنب غير صحيح. الأفضل والصواب: أن لهما القراءة عن ظهر قلب، وإذا استعانا بالمصحف من وراء حائل فلا بأس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9290/حكم-قراءة-الحاىض-والنفساء-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36808.mp3","categories":["الحيض والنفاس"]},{"id":11158,"question":"إذا كان الإنسان غير متوضئ، فهل يجوز له قراءة القرآن للحفظ أم يلزمه الوضوء؟","title":"حكم قراءة القرآن لغير المتوضئ","answer":"الجواب:  الوضوء مستحب لقراءة القرآن، إذا كان عن ظهر قلب، وإن قرأ من دون وضوء فلا بأس، إذا لم يكن جنبًا، أما الجنب فلا يقرأ حتى يغتسل، لكن إذا كان غير جنب، فله أن يقرأ القرآن من غير مصحف عن ظهر قلب، وإن كان على غير طهارة، لكن إذا كان أراد أن يقرأ من المصحف، فإنه يتوضأ أولًا؛ لقوله جل وعلا: لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:79]، وقوله ﷺ لا يمس القرآن إلا طاهر. فالمقصود أنه إذا كان يقرأ عن ظهر قلب، يعني: غيب حفظ، فلا بأس أن يقرأ وإن كان على غير وضوء، أما الجنب لا، لا يقرأ، الجنب لا يقرأ حتى يغتسل، أما إذا كان يقرأ بالمصحف، فإنه لا بد أن يكون على طهارة من الجنابة ومن الحدث الأصغر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9347/حكم-قراءة-القران-لغير-المتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37111.mp3","categories":["الحيض والنفاس","مس المصحف"]},{"id":11170,"question":"إذا كان الإنسان غير متوضئ، فهل يجوز له قراءة القرآن للحفظ أم يلزمه الوضوء؟","title":"حكم قراءة القرآن لغير المتوضئ","answer":"الجواب:  الوضوء مستحب لقراءة القرآن، إذا كان عن ظهر قلب، وإن قرأ من دون وضوء فلا بأس، إذا لم يكن جنبًا، أما الجنب فلا يقرأ حتى يغتسل، لكن إذا كان غير جنب، فله أن يقرأ القرآن من غير مصحف عن ظهر قلب، وإن كان على غير طهارة، لكن إذا كان أراد أن يقرأ من المصحف، فإنه يتوضأ أولًا؛ لقوله جل وعلا: لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:79]، وقوله ﷺ لا يمس القرآن إلا طاهر. فالمقصود أنه إذا كان يقرأ عن ظهر قلب، يعني: غيب حفظ، فلا بأس أن يقرأ وإن كان على غير وضوء، أما الجنب لا، لا يقرأ، الجنب لا يقرأ حتى يغتسل، أما إذا كان يقرأ بالمصحف، فإنه لا بد أن يكون على طهارة من الجنابة ومن الحدث الأصغر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9347/حكم-قراءة-القران-لغير-المتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37111.mp3","categories":["الحيض والنفاس","مس المصحف"]},{"id":11210,"question":"السائلة (ع. د. م) تقول: ما على من حاضت أثناء الصلاة هل تقطع صلاتها وتقضيها بعد طهرها، أم تكمل صلاتها؟","title":"حكم من أتاها الحيض أثناء الصلاة","answer":"الجواب:  من نزل بها الحيض وهي تصلي تبطل صلاتها مثل من خرج منه البول وهو يصلي تبطل صلاته، لكن الحائض ليس عليها قضاء وإن قضت فلا بأس، ليس عليها قضاء الصلاة التي نزل الحيض عليها فيها، فإن قضتها بعد الطهر فلا حرج وإلا فلا يلزمها ذلك إلا إذا كانت أخرتها حتى ضاق الوقت فإنها تقضيها، وأما إذا كانت ما زالت في وسط الوقت أو في أوله فلا تقضيها. نعم.","link":"https://binbaz.org.sa/fatwas/9391/حكم-من-اتاها-الحيض-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29110.mp3","categories":["الحيض والنفاس"]},{"id":11270,"question":"يسأل يقول: هل يصح للحائض أن تؤخر طواف الإفاضة إلى حج آخر؟","title":"حكم تأخير الحائض طواف الإفاضة إلى عام آخر","answer":"الجواب:  ليس لها ذلك، بل الواجب عليها أن تبادر وتطوف الإفاضة قبل أن تسافر، ولهذا لما حاضت صفية قال رسول الله ﷺ أحابستنا هي؟ قالوا له: إنها قد أفاضت قال: انفروا.  فالمقصود أن عليها أن تطوف للإفاضة قبل أن تغادر مكة، إلا إذا كان هناك ضرورة والمحل قريب كجدة والطائف والرفقة لا يسمحون لها تذهب معهم ثم ترجع ولا تؤخر. نعم. المقدم: هل تنصحونها بالالتزام بأحكام معينة حتى تطوف طواف الإفاضة؟  الشيخ: نعم، لا تحل لزوجها، إذا كان لها زوج لا يقربها زوجها حتى تطوف، أما الطيب وقص الأظفار لا حرج في ذلك، نعم. المقدم: المهم أنها إذا كانت ذات زوج فإنها تبتعد عن زوجها. الشيخ: نعم، لا يقربها حتى تطوف. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9453/حكم-تاخير-الحاىض-طواف-الافاضة-الى-عام-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37504.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":11287,"question":"امرأة جاءتها العادة أثناء الطواف فكيف تتصرف؟","title":"حكم من طرأت عليها العادة أثناء الطواف","answer":"الجواب:  تخرج من المطاف وتبقى حتى تطهر والحمد لله، إذا جاءتها في أثناء الطواف تخرج يعني من المسجد حتى يذهب بها وليها، وإن كان في السعي تكمل السعي لا يشترط فيه الطهارة، لكن في الطواف نفسه الذي حول البيت إذا جاءتها العادة في الشوط الثالث أو الرابع أو الخامس تخرج، وعلى وليها أن يخرج بها من المسجد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9468/حكم-من-طرات-عليها-العادة-اثناء-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37519.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":11352,"question":"تقول أختنا: في إحدى عطل الربيع ذهبنا لأداء العمرة، وفي الطريق أتت إحدانا الدورة الشهرية، وعندما وصلنا إلى الميقات سألتني هل أحرم أم لا؟ وجهلًا مني قلت لها: لا تحرمي ولم تحرم، ومضينا إلى أن وصلنا بيت الله الحرام وكانت متعبة جدًا فدخلت معنا الحرم وجلست فيه بينما ذهبنا لأداء العمرة، وبعد أن أتممناها ذهب والدي ليبحث لنا عن شقة وتأخر كثيرًا ولم يجد شيئًا لكثرة الوافدين، فاضطررنا إلى أن ننام في الحرم، وتلك التي معها العذر الشرعي أيضًا نامت معنا في الحرم، فهل هي آثمة في ذلك؟ وماذا يجب عليها حين دخلت الحرم ونامت به؟ جزاكم الله خيرًا.","title":"حكم من أتاها الحيض قبل إحرامها بالعمرة، وحكم دخولها المسجد","answer":"الجواب:  إذا كانت مضطرة فلا شيء عليها، إذا كانت مضطرة فلا شيء عليها، والواجب عليها أن تجتهد لعلها تجد مكانًا خارج الحرم، خارج المسجد، فإذا كانت تخشى ولم تجد فلا حرج عليها -إن شاء الله- لأنها مضطرة. نعم. والله يقول سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] لأن ما عليها خطأ لو ذهبت على غير علم فلا حرج عليها حتى تجد مكانًا خارج المسجد. نعم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء، لكن عليها وعلى ولي أمرها أن يجتهد ولو بعيدًا عن الحرم. الشيخ: نعم عليهم أن يجتهدوا حتى يضعوها في محل آمن، إذا عرفوا حالها. المقدم: بارك الله فيكم، ماذا على المرأة والحال ما ذكر، كثيرًا من أخواتنا يبعثن إلى هذا البرنامج ويقلن إننا استحيينا أن نذكر هذا لأولياء الأمور؟ الشيخ: لا ما يجوز لهن لابد البيان، ما في هذا حياء هذا أمر كتبه الله على بنات آدم، لابد من البيان إذا كان عندها العذر تقول: لي عذر حتى يلتمس لها مكانًا خارج المسجد، نعم. المقدم: عليهم أن ينتظروا حينئذ سماحة الشيخ حتى تنتهي هذه الفترة لتحرم وتعتمر أم تلغي فكرة العمرة نهائيًا؟ الجواب: هذا إليهم إن كان عليهم مضرة فلا مانع من أن يرجعوا بها غير محرمة عليهم أن يرجعوا بها وبعدها تعود للإحرام مع وليها، تعود حتى تؤدي عمرتها مع وليها، أما إذا كان ما عليهم مضرة فيحتسبون يصبرون حتى تؤدي عمرتها تطهر وتؤدي عمرتها وهم على خير عظيم. أما إذا كان عليهم مشقة فإنها ترجع معهم وهي محرمة ثم يرجع بها محرمها زوجها أو أخوها حتى تؤدي العمرة التي أحرمت بها. المقدم: بارك الله فيكم، إن لم تحرم كأختنا هذه؟ الشيخ: إذا كانت ما أحرمت لا حرج، إذا كانت معها الدورة ولا أحرمت فلا بأس تدخل معهم وهي غير محرمة. المقدم: بارك الله فيكم، إذًا الذي تنصحون به سماحة الشيخ؟ الشيخ: إذا كان معها الدورة وتخشى أن تشق عليهم لا تحرم. المقدم: لا تحرم. الشيخ: لا تحرم. المقدم: تنصحون كل مسلمة. الشيخ: تبقى معهم وهي حائض بدون إحرام حتى لا تشق عليهم. المقدم: بارك الله فيكم، إذا وصلت الميقات وهي معذورة فعليها أن لا تحرم. الشيخ: إلا إذا سمحوا لها. المقدم: بالبقاء حتى تعتمر. الشيخ: إذا سمحوا لها أنها تحرم وأنهم ينتظرون لها، نعم. المقدم: بارك الله فيكم، إذًا مكان الميقات هو مكان التفاوض في هذا الموضوع. الشيخ: نعم. الميقات نعم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9544/حكم-من-اتاها-الحيض-قبل-احرامها-بالعمرة-وحكم-دخولها-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37821.mp3","categories":["الحيض والنفاس"]},{"id":11504,"question":"سماحة الشيخ، كما يصل إلى هذا البرنامج من رسائل بعض الأخوات يحملن هذا الأمر فوق ما يحتمل، فقد تطوف المرأة بالبيت، وهي معذورة شرعًا، وقد تمتنع عن الأكل والشرب، وتتظاهر بالصيام، وهي معذورة شرعاً، أطمع بكلمة موسعة في هذا المقام، جزاكم الله خيرًا.","title":"حكم طواف الحائض بالبيت حياءً","answer":"الجواب: هذا لا يجوز، ليس لها أن تطوف وهي حائض، وليس لها أن تصلي وهي حائض، لأجل الحياء، كل هذا منكر، لكن مثل كونها ما تحضر معهم إذا اجتمعوا على الأكل؛ حياء، أو شبه ذلك من الأشياء التي ليس فيها محذور شرعًا، أما أن تصلي وهي حائض، أو تطوف وهي حائض، أو تجلس في المسجد وهي حائض؛ هذا لا يجوز، لا تفعل المنكر، والنبي ﷺ حرمه على الحائض. أما كونها مثلًا تستحي أن تجلس معهم لشرب القهوة، أو شرب الشاهي، أو الأكل؛ تروح في محل آخر حياءً من إخوان زوجها، أو من زيد، أو عمرو، أو من أبيها، أو من أخيها. المقصود: إذا كان حياءً لا يترتب عليه منكر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9699/حكم-طواف-الحاىض-بالبيت-حياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38415.mp3","categories":["الحيض والنفاس"]},{"id":11517,"question":"بعد هذا رسالة من اليمن بعثت بها إحدى المستمعات رمزت إلى اسمها بالحرفين (أ) و (م) أختنا تسأل عن حكم من تظاهرت بالصيام في رمضان أثناء العذر الشهري، وذلك حياءً، هل عليها في ذلك إثم؟","title":"حكم تظاهر المرأة الحائض بالصيام في رمضان حياءً","answer":"الجواب:  ليس عليها إثم، إذا ما بينت أنها حائض، لكن لا تصم، لا تنو الصيام، أما إذا سكتت ولم تقل: إني حائض، ولم تقل: إني مفطرة؛ ما يضرها ذلك، لكن إذا كانت تنوي الصوم هذا لا يجوز، هذا منكر، الصوم باطل، أما كونها تجلس معهم، ولا تأكل مع الآكلين لأجل الحياء، وهي تأكل في وقت آخر، إلا إذا دعت الحاجة إلى هذا؛ فلا بأس، ولكن لا حياء في الأمر هذا، الحمد لله، إذا أكلت مع الآكلين؛ فلا بأس. المقصود: إذا دعت الحاجة إلى الحياء، ولكنها لا تنوي الصوم، ولا تصم، إذا دعت الحاجة إلى الحياء، ولم تأكل معهم؛ فلا بأس، إذا كان لمصلحة شرعية، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9698/حكم-تظاهر-المراة-الحاىض-بالصيام-في-رمضان-حياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38414.mp3","categories":["الحيض والنفاس"]},{"id":11540,"question":"من الأخت المستمعة: (ح. س. ع. أ) من الأحساء العيون بعثت برسالة ضمنتها جمعًا من الأسئلة من بينها سؤال يقول: هل يجوز للحائض قراءة القرآن، خاصة إذا كان لها حزب يومي معين، ومداومة على ذلك، جزاكم الله خيرًا؟","title":"يجوز للحائض والنفساء مس القرآن بحائل للحاجة","answer":"الجواب: سبق أن أفتينا من طريق هذا البرنامج مرات كثيرة، أن الحائض لها أن تقرأ القرآن عن ظهر قلب من دون مس المصحف، هذا هو الصواب، وهذا القول هو أصح قولي العلماء، وفي القول الآخر لبعض العلماء: المنع، وأنها لا تقرأ كالجنب. والصواب أنها تقرأ عن ظهر قلب؛ لأن الجنب يستطيع أن يتخلص من الجنابة بسرعة بالغسل فيقرأ، هو ممنوع من القراءة حال كونه جنبًا، يعني النبي ﷺ إذا كان جنبًا لا يقرأ -عليه الصلاة والسلام- كان لا يحجزه شيء عن القرآن إلا الجنابة، هكذا ثبت عنه ﷺ: أنه كان إذا كان جنبًا يدع القرآن، أما المرأة الحائض والنفساء فمدتهما تطول، وليستا من جنس الجنب.  فالصواب أن لهما أن تقرأ من طريق الحفظ، من طريق الغيب، لا من طريق القراءة في المصحف، لكن إذا احتاجت المصحف لمراجعة القرآن، أو ما تحتاج إليه من تصحيح الأخطاء، أو ما أشبه ذلك؛ فلا بأس من طريق حائل ..... تكون عليها قفازان، أو حائل آخر حتى تفتش عن القرآن، تراجع ما تحتاج إليه، أو يراجع لها غيرها.  أما حديث أنه ﷺ قال: لا تقرأ الحائض، ولا الجنب شيئًا من القرآن فهو حديث ضعيف عند أهل العلم، لا يصلح للاحتجاج، وقد أمر النبي ﷺ عائشة في حجة الوداع وهي حائض أن تفعل ما يفعل الحجاج قال: إلا الطواف، غير ألا تطوفي حتى تطهري. فدل ذلك على أنها لها أن تقرأ القرآن؛ لأنه لم ينهها عن القرآن، إنما نهاها عن الطواف حتى تطهر، والصلاة معروفة ما هي بتصلي الحائض. فالمقصود: أنه نهى عن الطواف حتى تطهر، فدل ذلك على أنها لا تنهى عن القرآن؛ لأن المحرم يقرأ القرآن، الحاج يقرأ القرآن، فلو كانت الحائض لا تقرأ القرآن؛ لنبهها -رضي الله عنها- ألا تقرأ حتى تطهر، كما نبهها على الطواف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9723/يجوز-للحاىض-والنفساء-مس-القران-بحاىل-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29506.mp3","categories":["الحيض والنفاس"]},{"id":11549,"question":"يسأل ويقول: هل تقضي الحائض والنفساء الصوم والصلاة؟","title":"حكم قضاء الحائض والنفساء للصوم والصلاة","answer":"الجواب:  الحائض والنفساء تقضيان الصوم فقط عند جميع العلماء، أما الصلاة فلا تقضى عند جميع أهل العلم، قالت عائشة -رضي الله عنها-: كنا نؤمر بقضاء الصوم يعني: الحيض كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة. وهذا من رحمة الله وتيسيره -جل وعلا- وإحسانه، أنه أحسن إليهن بوضع الصلاة عنهن؛ لأن الصلاة تتكرر في اليوم والليلة خمس مرات، والحيض قد يبقى معها أسبوعًا أو أكثر أو أقل؛ فيشق عليها القضاء، وهكذا النفساء قد تبقى في النفاس أربعين يومًا فيشق عليها القضاء، فمن رحمة الله أن أسقط عن الحيض والنفساء الصلاة، فلا تقضي ولا تفعلها، لا تفعلها في حال الحيض والنفاس ولا تقضي، أما الصوم فإنها لا تفعله في حال الحيض والنفاس؛ لكنها تقضي، لا يجوز بها الصوم وهي حائض أو نفساء، ولكن عليهما القضاء، إذا طهرت صامت في رمضان، وتقضي ما عليها بعد رمضان، تقضي ما أفطرت بسبب الحيض، أو النفاس، تقضيه بعد رمضان، ما بين رمضان ورمضان الثاني تقضي بينهما، لها أن تؤخر إلى رجب وشعبان لا بأس، وإذا بادرت فهو أفضل؛ حذرًا من العوائق. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9732/حكم-قضاء-الحاىض-والنفساء-للصوم-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_296/29605.mp3","categories":["الحيض والنفاس"]},{"id":11562,"question":"أيضًا مع الأخوات تسأل: هل يجوز للمرأة أن تستعمل الحناء وهي حائض، أو في النفاس؟ جزاكم الله خيرًا.","title":"حكم استعمال المرأة للحناء حال الحيض والنفاس","answer":"الجواب:  لا حرج في استعمال الحناء في الحيض، والنفاس، لا حرج أن تتحنى وهي حائض، أو نفساء، لا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9745/حكم-استعمال-المراة-للحناء-حال-الحيض-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29711.mp3","categories":["الحيض والنفاس"]},{"id":11618,"question":"هل يجوز للحائض أن تقرأ الورد اليومي من القرآن الكريم؟","title":"حكم قراءة النفساء والحائض للقرآن عن ظهر قلب","answer":"الجواب:  الصواب أنه لا حرج عليها، أن تقرأ الآيات عن ظهر قلب، وليست كالجنب، الجنب مدته قصيرة، يغتسل في الحال وينتهي، فلا يجوز له أن يقرأ القرآن الجنب، وأما الحائض والنفساء فمدتهما تطول، وقد اختلف العلماء في أمرهما هل يلحقان بالجنب، فيمنعان من قراءة القرآن عن ظهر قلب، أم لا.  والصواب أنهما لا يلحقان بالجنب؛ لأنهما ليستا مثله، المدة تطول، وليس في منعهما حديث صحيح يمنعهما من القراءة، فلهما أن تقرأا من غير المصحف عن ظهر قلب، وتراجع المصحف إذا دعت الحاجة من وراء حائل بالقفازينـ ونحوهما عند الحاجة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9803/حكم-قراءة-النفساء-والحاىض-للقران-عن-ظهر-قلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38814.mp3","categories":["الحيض والنفاس"]},{"id":11621,"question":"هل يجوز للمرأة أن تسجد إذا مرت بآية فيها سجدة وهي في عذرها الشهري، أو من غير وضوء؟","title":"حكم سجود التلاوة للحائض والنفساء","answer":"الجواب:  نعم، سجود التلاوة لا يجب له الوضوء، سجود التلاوة من جنس الذكر، يجوز أن يسجد الإنسان وهو على غير طهارة، هذا هو الصواب، فإذا قرأت الحائض القرآن؛ سجدت للتلاوة، إذا مرت بسجود التلاوة، وهكذا المحدث إذا قرأ وهو على غير طهارة، لكن ليس بجنب، فإنه إذا مر بالسجدة يسجد، أما الجنب لا، لا يقرأ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9804/حكم-سجود-التلاوة-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38815.mp3","categories":["سجود التلاوة والشكر","الحيض والنفاس"]},{"id":11673,"question":"إحدى الأخوات تسأل وتقول: المرسلة (م. أ) تسأل وتقول: ما حكم المرأة الحائض إذا تركت مكة المكرمة قبل أن تطوف طواف الإفاضة، وذلك لارتباط زوجها بالعمل عند كفيل، ولم تتمكن من الاستمرار في مكة حتى الطهر؟ وهل يمكن العودة لعمل الطواف أم لا؟ ولقد تم فك الإحرام بعد فتوى لي من أهل العلم، ولكن غير راضية عن هذه الفتوى وعن ذلكم الحج، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم من تركت طواف الإفاضة بسبب الحيض وسافرت","answer":"الجواب:  الواجب على من لم تطف طواف الإفاضة إذا سافرت من أجل علة أوجبت ذلك، فإن الواجب عليها الرجوع، ترجع مع محرمها للطواف، ولا يقربها زوجها حتى تطوف، فإذا ذهبت مع زوجها للبلد فعليه أن يرجع بها في الأوقات المناسبة، أو يرجع بها أخوها، أو أبوها، أو غيرهما من محارمها إلى مكة، حتى تطوف طواف الإفاضة، وتسعى إذا كان عليها سعي، إذا كانت متمتعة فسعيها الأول للعمرة، وعليها أن تسعى ثانٍ مع طواف الإفاضة للحج، وليس لزوجها قربانها يعني: جماعها حتى ترجع وتطوف، فإن فعل زوجها وجامعها؛ فعليها دم يذبح بمكة للفقراء، وحجها صحيح، الحج صحيح، والحمد لله، لكن إذا جامعها فعليها التوبة، وتأثم ويأثم هو أيضًا، وعليها ذبيحة تذبح في مكة للفقراء لكونه جامعها قبل الطواف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، لها كلمة بودي لو تفضلتم بالتعليق عليها سماحة الشيخ! ألا وهي قولها: إنها فكت الإحرام بناء على فتوى من أهل العلم، لكنها غير راضية عن تلكم الفتوى، وعن ذلكم الحج؟ الشيخ: إن كان فك الإحرام بالطيب وغطاء الوجه ونحو ذلك؛ فهذا لا بأس به، قلم الأظفار، كد الشعر كل هذا لا بأس به، لأن هذا يحل بعد الرمي والتقصير يحل هذا كله، ما يبقى إلا التحريم للجماع فقط، فحلها الإحرام في هذه الأمور، كد الشعر قلم الأظفار نتف الإبط، وشبه ذلك هذا لا بأس به. فإن كان قصدها فك الإحرام أنها جامعها زوجها فقد بينا أن عليها دم، وعليها أن تمتنع حتى تطوف، لا يعود إلى جماعها حتى تطوف. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9855/حكم-من-تركت-طواف-الافاضة-بسبب-الحيض-وسافرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39005.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":11875,"question":"هل يجوز لي لمس المصحف أثناء العذر الشهري، أو لا؟","title":"حكم مس الحائض المصحف","answer":"الجواب:  إذا كنت في الحيض، أو النفاس تقرئين عن ظهر قلب غيب، تقرئين لا بأس على الصحيح، تقرئين القرآن؛ لأن المدة تطول مدة الحيض والنفاس تطول، فلا بأس أن تقرأ الحائض والنفساء عن ظهر قلب غيب. أما من المصحف، لا، لا تقرأ من المصحف، لكن إذا دعت الحاجة تراجع آية، أو بعض الآيات، يكون من وراء الحجاب، عن طريق القفازين، أو تلف على أيديها كي تراجع المصحف، حتى تعرف الآية التي غلطت فيها، لا بأس عند الحاجة. أما الجنب لا، الذي عليه الجنابة لا يقرأ حتى يغتسل، لا من المصحف، ولا عن ظهر قلب حتى يغتسل؛ لأن الرسول ﷺ كان لا يقرأ وهو جنب، ويقول: أما الجنب فلا، ولا آية يعني: حتى يغتسل. أما حديث: أن الحائض لا تقرأ القرآن؛ فهو حديث ضعيف، حديث: لا تقرأ الحائض ولا الجنب شيئًا من القرآن، حديث ضعيف، والثابت: إنما هو في الجنب خاصة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10059/حكم-مس-الحاىض-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_424/42404.mp3","categories":["الحيض والنفاس"]},{"id":11883,"question":"هل يجوز للمرأة الحائض أن تسجد سجود التلاوة؟","title":"حكم سجود التلاوة للحائض والنفساء والجنب","answer":"الجواب:  الصواب أنه لا حرج أن تقرأ وتسجد، هذا هو الصواب، عن ظهر قلب، ما هو من المصحف عن ظهر قلب؛ لأنها ليست مثل الجنب، الجنب مدته قصيرة، يغتسل ويقرأ، لا يقرأ الجنب، ولا يسجد، لكن الحائض والنفساء مدتهما تطول، فالصواب أن لهما أن تقرأا عن ظهر قلب، فإذا مرتا بالسجدة سجدتا؛ لأن السجدة ليست صلاة؛ سجدة التلاوة ليست صلاة، وإنما هي خضوع لله، مثل الذكر لا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10067/حكم-سجود-التلاوة-للحاىض-والنفساء-والجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42504.mp3","categories":["سجود التلاوة والشكر","الحيض والنفاس"]},{"id":12090,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع (ح. رمضان) والمستمعة (س. رمضان) أيضًا من المنيا من الصعيد، إخوتنا يسألون سماحتكم -جزاكم الله خيرًا- عن فئة من الناس نساؤهم لا تصوم قضاء رمضان إذا ما أفطرت بعذر شرعي، ويعتقدون أن ذلك لا يقضى كالصلاة، وهذه مشكلة كبيرة وخطيرة، كما يصفونها في حق الدين، نرجو من سماحتكم أن تفتوا لنا في هذا مع توجيه الناس ونصحهم، جزاكم الله خيرًا.","title":"وجوب قضاء رمضان للحائض إذا أفطرت فيه","answer":"الجواب:  الواجب على كل مؤمنة أن تقضي صوم رمضان إذا صادف الحيض في رمضان، أو النفاس، عليها أن تفطر، وعليها أن تقضي بإجماع المسلمين، بإجماع العلماء، هذا واجب عند الجميع، عند جميع أهل العلم، قالت عائشة -رضي الله عنها-: كان يصيبنا ذلك على عهد النبي ﷺ فنؤمر بقضاء الصوم، ولا نؤمر بقضاء الصلاة فكان النبي ﷺ يأمرهن بقضاء الصوم إذا أفطرن في رمضان من أجل الحيض والنفاس، ولا يأمرهن بقضاء الصلاة، والله خفف عن عباده  فالصلاة مكررة في اليوم خمس مرات، وفي قضائها مشقة، فمن رحمة الله، وإحسانه -جل وعلا- أن أسقطها عن الحائض والنفساء مدة الحيض والنفاس فعلًا وقضاء، لا تفعل ولا تقضي رحمة من الله، وإحسانًا منه، جل وعلا. أما الصوم، صوم رمضان فإنه أسقطه عن الحائض والنفساء فعلًا وقت الحيض، ووقت النفاس، لا تصوم، لكن تقضي، إذا جاء الحيض في نهار رمضان؛ تفطر، وهكذا في النفاس تفطر، ثم تقضي بعد ذلك بإجماع العلماء. فالواجب على جميع المسلمين التواصي بهذا، والتناصح، والتنبيه للنساء على هذا الأمر، وأنه واجب على المرأة أن تقضي أيام الحيض، وأيام النفاس، التي أفطرتها في رمضان، ومن ترك ذلك؛ فقد عصى الله ورسوله، وخالف إجماع المسلمين، وهو يستحق التأديب، والضرب على هذا الأمر، تستحق المرأة إذا تركت ذلك التأديب من أبيها وزوجها وأخيها؛ لأن هذا منكر عظيم، لا يجوز لها أن تدع قضاء الصوم، إذا أفطرت في رمضان بالحيض، أو بالنفاس؛ فإنه يجب عليها القضاء -كما تقدم- بالنص والإجماع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10275/وجوب-قضاء-رمضان-للحاىض-اذا-افطرت-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43604.mp3","categories":["الحيض والنفاس"]},{"id":12214,"question":"تسأل أختنا أيضًا وتقول: أختي لها سؤال آخر، فهي طالبة في الثانوية، وقد وضعت المدرسة مشكورة مصلى للتلميذات تعقد فيه ندوات ومحاضرات بين آونة وأخرى، وتطلب المعلمة من الجميع الدخول للاستماع إلى تلك الندوات، فهل يجوز الدخول في هذا المكان لمن عليها العذر؟","title":"حكم دخول الحائض مصلى المدرسة لاستماع المحاضرات","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/10400/حكم-دخول-الحاىض-مصلى-المدرسة-لاستماع-المحاضرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44602.mp3","categories":["الحيض والنفاس"]},{"id":12256,"question":"إحدى الأخوات المستمعات بعثت بسؤالين إلى البرنامج، أحدهما يقول: ذهبت لأداء العمرة، وقبل خروجي من مكة المكرمة، اغتسلت من الدورة الشهرية قبل رؤية الطهارة جهلًا مني، وطفت طواف الوداع، فهل علي دم أو كفارة لفعلي هذا؟ أرشدوني جزاكم الله خيرًا.","title":"حكم طواف المرأة للوداع أثناء حيضها جهلاً منها","answer":"الجواب:  ليس عليك شيء سوى التوبة إلى الله؛ لأنه لا يجوز لك أن تطوفي ومعك الدم؛ لأن الطواف صلاة، وليس عليك وداع، الحائض ما عليها وداع، لا في الحج، ولا في العمرة، التي معها دم الحيض ليس عليها وداع، لا في الحج ولا في العمرة. ثم العمرة ليس لها وداع واجب، من شاء ودع، ومن شاء ترك، الوداع في العمرة مستحب، وليس بواجب على الصحيح، أما في الحج فيجب الوداع، ولكن الحائض لا وداع عليها، لا في الحج، ولا في العمرة حتى تطهر، فإذا خرجت من مكة وهي حائض؛ فلا وداع عليها، وليس لها أن تطوف وهي حائض، هذا لا يجوز، فعليك التوبة إلى الله من ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10456/حكم-طواف-المراة-للوداع-اثناء-حيضها-جهلا-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44907.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":12257,"question":"تقول أيضًا: وحدث لي مثل ذلك في الصيام، حيث صمت أحد أيام رمضان قبل الموعد الصحيح للطهارة، هل علي كفارة؟ وما هي؟ وهل علي إعادة الصلوات التي صليتها في تلك الحالة؟","title":"حكم صيام المرأة حال حيضها","answer":"الجواب:  إذا كان معك الحيض، وصمت، فعليك إعادة ذلك اليوم الذي صمتيه، مادام الدم معك، والغسل الذي مع الدم؛ لا ينفع، لابد أن يكون الغسل بعد الطهارة، بعد رؤية القصة البيضاء، أو بعد ظهور وتبين النقاء بقطن ونحوه؛ حتى تري أن الحيض قد انقطع، ما بقي له أثر، فإذا صمت ومعك أثر الدم؛ فعليك القضاء، أما الصلاة فلا قضاء عليك، لكن عليك قضاء الصوم الذي وقع في حال الحيض. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10457/حكم-صيام-المراة-حال-حيضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44908.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":12482,"question":"بعد هذا رسالة وصلت إلى البرنامج من المنوفية وباعثها مستمع يقول: أحمد محمد عيسى، الأخ أحمد يسأل ويقول: موضوع مس المصحف الشريف لمن كان على غير وضوءـ أرجو التفصيل في هذا الموضوع، حيث أنني لا يمكن أن أستغني عن لمس المصحف أبدًا، سواء كان للعبادة، أو لتعليم الأولاد، أو للحفظ، والوضوء يكون فيه مشقة كبيرة، مما يؤدي إلى هجري لكتاب الله -عز وجل- مع ذكر الأدلة ما أمكن، جزاكم الله خيرًا.","title":"حكم مس المصحف للجنب والحائض والنفساء والمحدث حدثاً أصغر","answer":"الجواب:  مس المصحف قد بين النبي الحكم -عليه الصلاة والسلام- وقال: لا يمس القرآن إلا طاهر والله يقول -جل وعلا-: لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:79]. فالواجب على من أراد مس المصحف أن يتوضأ، وأن يمس المصحف، ويقرأ فيه، أو يقرأ عن ظهر قلب، لكن إذا دعت الحاجة إلى مسه؛ فإنه يمسه من دون حائل، يكون في يديه حائل يمسه به، كالقفازين، أو غيرهما عند الحاجة، وإلا فالواجب الوضوء حتى يتمكن من مسه بدون كلفة، وبدون مشقة، وبدون حائل. أما الجنب فلا يقرأ حتى يغتسل، ولا يمس المصحف أيضًا، لا يقرأ، ولا يمس المصحف، وهكذا الحائض لا تمس المصحف، ولكن تقرأ عن ظهر قلب على الصحيح، لأن مدتها تطول، وهكذا النفساء ليست من جنس الجنب، مدة الحيض تطول، والنفاس أكثر، فلهما أن تقرأا على الصحيح عن ظهر قلب، وإذا دعت الحاجة إلى مس المصحف؛ يكون من وراء حائل للحاجة، كمراجعة آية، أو آيات، أو المعلم يحتاج إلى ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10684/حكم-مس-المصحف-للجنب-والحاىض-والنفساء-والمحدث-حدثا-اصغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40505.mp3","categories":["مس المصحف","الحيض والنفاس","القرآن وعلومه"]},{"id":12750,"question":"تقول أختنا: لقد قرأت في أحد الكتب الفقهية: أن البنت إذا بلغت لأول مرة؛ تترك الصلاة لمدة يوم وليلة، ثم تغتسل، وتصلي حتى ولو كان الدم باقيًا، وتستمر على هذه الحالة لمدة ثلاثة أشهر؛ حتى تستقر مدة حيضتها، فهل هذا صحيح؟","title":"مدة حيض المرأة","answer":"الجواب:  هذا قول بعض أهل العلم، ولكنه ليس بصحيح، والصواب: أنها لا تصلي مدة الأيام التي ترى فيها الدم، يومين، ثلاثًا، أربعًا، خمسًا، ستًا، سبعًا .. إلى خمسة عشر، لا بأس، وهكذا كلما جاءت الدورة؛ تجلس، ولا تصلي، ولا تصوم، ولا يقربها زوجها إن كانت ذات زوج حتى تنتهي المدة. وليس لها حد يوم، ولا يومين، لكن نهايتها وأكثرها عند أكثر أهل العلم خمسة عشر يومًا، فإذا زادت؛ صارت استحاضة ودمًا فاسدًا، ترجع إلى عادة النساء ستًا، أو سبعًا، أما إذا كانت تنقطع لست، أو سبع، أو ثمان، أو عشر؛ فالحمد لله هي عادتها، ولا تصلي، ولا تصوم، ولا يقربها زوجها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10964/مدة-حيض-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41821.mp3","categories":["الحيض والنفاس"]},{"id":12854,"question":"أختنا تسأل وتقول: كم هي المدة التي تبقاها المرأة بدون صلاة بعد الولادة، وجهونا جزاكم الله خيرًا؟","title":"وقت انتهاء مدة النفاس","answer":"الجواب:  المدة أربعون يومًا، إذا كان معها الدم، أما إذا انقطع الدم لأقل من أربعين فإنها تغتسل وتصلي، وإذا كانت حاملًا فإن النفاس، فإن العدة تنتهي بوضع الحمل، العدة تنتهي بوضع الحمل، أما النفاس فإن النفاس يكون أربعين يومًا ما دام الدم موجودًا، سواء كانت صغيرة، أو كبيرة، لا فرق في ذلك عربية أو أعجمية، لا فرق في ذلك العدة أربعون يومًا لجميع النساء ما دام الدم موجودًا، يبتدئ من وضع الحمل، تبتدي هذه المدة من وضع الحمل. فإن انقطع الدم وهي في العشر الأول، أو العشرين، أو الشهر تغتسل وطهرت، ليس لأقله حد محدود، فإذا رأت الطهارة على رأس الشهر، أو رأس العشرين يومًا، أو أقل، أو أكثر؛ فإنها تغتسل، وتصلي والحمد لله، وتحل لزوجها أيضًا. أما إن استمر الدم معها، ولم ينقطع؛ فإنها تغتسل بعد تمام الأربعين، ولو كان معها الدم، بعد تمام الأربعين؛ ينتهي حكم النفاس؛ لحديث أم سلمة -رضي الله عنها- قالت: كانت النفساء تقعد على عهد النبي ﷺ أربعين يومًا يعني: هذه النهاية إذا كان معها الدم. أما إذا رأت الطهر قبل ذلك؛ فإنها تغتسل، وتصلي، وتصوم، وتطوف إن كانت في الحج، وتحل لزوجها، والحمد لله، ولو ما مر عليها إلا عشرة أيام، أو خمسة أيام، بل لو ولدت، وليس معها دم؛ اغتسلت، وصلت، وصامت، كما قد يقع لبعض النساء. أما الدم الذي بعد الأربعين فهو دم فساد، كدم الاستحاضة، تصلي معه تصوم، تحفظ بثوب ونحوه كقطن، وتحل لزوجها ولو كان معها الدم بعد الأربعين مثل المستحاضة، تصلي وتصوم، وتحل لزوجها، وتتوضأ لكل صلاة، كلما دخل وقت الصلاة تتوضأ، وتصلي في الوقت، وتقرأ القرآن، وتطوف إن كانت في الحج، أو في العمرة، لها حكم الطاهرات، وتحل لزوجها حتى ينقطع عنها هذا الدم، فإذا جاء وقت العادة الشهرية؛ جلست لم تصل، ولم تصم، ولم تحل لزوجها حتى تنتهي العادة الشهرية، ثم تغتسل وتصلي وتصوم وتحل لزوجها، ولا تلتفت إلى الدم الزائد الذي هو دم الفساد، هذا ليس له حكم الحيض، ولا حكم النفاس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11069/وقت-انتهاء-مدة-النفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46502.mp3","categories":["الحيض والنفاس"]},{"id":13010,"question":"من الدمام إحدى الأخوات رمزت إلى اسمها بقولها: أختكم في الله: (م) لها ثلاثة أسئلة، في أحدها تقول: تأخرت قليلًا في صلاة العشاء، فنزلت علي الحيضة هذه الحالة، متى أقضي صلاة العشاء؟ هل بعدما أطهر مباشرة من الحيضة حتى ولو كان العصر، أم أنتظر قضاءها إلى أن يأتي وقت العشاء، والحقيقة أنني قد قضيتها بعد طهري مباشرة في العصر، فهل هذا صحيح؟","title":"حكم من جاءها الحيض في وقت صلاة لم تؤدها بعد","answer":"الجواب:  أولًا ليس عليك قضاء، لا يجب عليك القضاء إذا كنت لم تفرطي، جاء الحيض في أول الوقت، أو في أثناء الوقت، لم تفرطي؛ فلا قضاء عليك، لكن إذا قضيت؛ فلا حرج، والمقضية ليس لها وقت نهي، إذا قضيتها من حين تطهرين في العصر، أو في أي وقت؛ فلا حرج في ذلك، يقول النبي ﷺ: من نام عن الصلاة، أو نسيها؛ فليصلها إذا ذكرها، لا كفارة لها إلا ذلك. فالمقضية ليس لها وقت نهي، ولكن المرأة إذا حاضت، أو نفست في وقت الصلاة، ولم تفرط؛ فلا قضاء عليها، أما لو فرطت بأن أخرتها إلى آخر وقتها، ثم جاء الحيض؛ فإنها تقضيها؛ لأنها فرطت في عدم فعلها في وقتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11227/حكم-من-جاءها-الحيض-في-وقت-صلاة-لم-تودها-بعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47106.mp3","categories":["الحيض والنفاس"]},{"id":13014,"question":"تقول: فيما يتعلق بالدورة الشهرية فإنه بعد انتهاء مدتها ألاحظ نزول سائل، فهل بنزوله تبطل صلاتي، أم أن صلاتي صحيحة؟","title":"حكم السائل الخارج من المرأة بعد الطهر","answer":"الجواب:  السائل إذا كان ليس بالدم الماء المعروف؛ لا يؤثر، متى رأيت الطهارة؛ وجب الغسل، والصلاة صحيحة، وما خرج من السائل حكمه حكم البول تستنجين منه، وتوضئين وضوء الصلاة، وتصلين، مادمت رأيت الطهارة، واغتسلت؛ تصلين، والحمد لله، والسائل هذا الذي يقع للنساء وهي المياه التي تقع للنساء، هذه حكمها حكم الأبوال، ما أصاب الثياب؛ يغسل، وما أصاب البدن؛ يغسل، وهي تنقض الوضوء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11231/حكم-الساىل-الخارج-من-المراة-بعد-الطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47110.mp3","categories":["الحيض والنفاس"]},{"id":13214,"question":"يقول هذا السائل يا سماحة الشيخ: هل يجوز للحائض، أو النفساء أن تمس المصحف، وتقرأ فيه، وهل يجوز لها أيضًا أن تدخل المسجد لتتلقى العلوم الشرعية وهي حائض؟","title":"حكم مس الحائض والنفساء المصحف","answer":"الجواب:  ليس لها الجلوس في المسجد، وليس لها مس المصحف، وهي حائض حتى تتطهر، لكن لو دعت الحاجة إلى مسه من وراء القفازين، من وراء حائل لمراجعة آية، أو ما أشبه ذلك لا بأس، أما أن تمسه من دون حائل، لا. ليس لها ذلك؛ لأن حدثها أكبر كالجنب، فالجنب لا يقرأ، ولا يمس المصحف. أما الحائض فلها أن تقرأ لأجل طول المدة، والنفساء كذلك على الصحيح، لها أن تقرأ عن ظهر قلب، لكن لا تمس المصحف إلا إذا دعت الحاجة إلى مراجعة آية؛ فلا بأس أن تمسه من وراء حائل، نعم.","link":"https://binbaz.org.sa/fatwas/11490/حكم-مس-الحاىض-والنفساء-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52005.mp3","categories":["الحيض والنفاس"]},{"id":13599,"question":"تقول: كم هي عدد الأيام شرعًا وفي السنة المطهرة لتلك التي يأتيها العذر الشرعي؟","title":"أقل الحيض وأكثره","answer":"الجواب: الصواب لا حد لأقله، ولا لأكثره، لكن الأغلب أن العادة تكون ستًا أو سبعًا، هذا هو الأغلب، وقد تصل إلى خمسة عشر، والذي عليه جمهور أهل العلم أنها لا تزيد على خمسة عشر، متى زادت؛ فهي استحاضة، تصلي معها، وتصوم، وتحل لزوجها، أما إذا كان خمسة عشر فأقل فإنها تكون عادة، وتستمر عليها، وإن نقصت؛ طهرت، تطهرت بعد ذلك. فعلى كل حال العادة تزيد وتنقص، قد تكون ستًا وسبعًا، وقد تزيد يومًا، تنقص يومًا، فالمؤمنة تجلس ما ترى من الدم، ولو زادت العادة، أو نقصت على الصحيح تجلس، ولا تصلي، ولا تصوم، ولا تحل لزوجها؛ حتى تطهر، وتغتسل. لكن متى استمرت معها إلى خمسة عشر هذه النهاية على الصحيح، متى زادت على خمسة عشر؛ فإنها تعتبرها استحاضة، وتصلي، وتصوم، وتحل لزوجها، وترجع إلى عادتها المعروفة قبل هذه الزيادة، وتستمر عليها، سواءً كانت ستًا، أو سبعًا أو ثمانًا، أو عشرًا، لأنها لما زادت على نصف الشهر؛ اتضح أنها استحاضة، وأنها ليست العادة المعروفة، والعادة الشرعية لا تزيد على نصف الدهر، أقصاها ونهايتها نصف الشهر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11933/اقل-الحيض-واكثره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48011.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":13943,"question":"أختنا تقول: هل للمرأة أن تتزين بالحناء وهي في أيام عذرها؟","title":"حكم استعمال الحائض والنفساء للحناء‏","answer":"الجواب: لها أن تستعمل الحناء في أيام الحيض وفي أيام النفاس لها أن تستعمل إذا كانت ليست محادة ليست في عدة متوفىً عنها، إذا كانت عادية ليست في عدة من زوج متوفى فلا بأس، تستعمل الحناء في حال حيضها أو في حال نفاسها ما يضر ولو أنها غير طاهرة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12361/حكم-استعمال-الحاىض-والنفساء-للحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60409.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14221,"question":"تسأل وتقول: إذا ذهبت مثلًا لأداء صلاة الظهر في الساعة الواحدة وعند الوضوء اكتشفت أن الدورة قد أتت، فهل يجب علي أن أصلي الظهر عند تطهري مع أنني لا أعلم هل هي قد أتت قبل دخول الوقت أم بعده؟","title":"حكم قضاء الصلاة لمن حاضت بعد دخول الوقت","answer":"الجواب: لا يلزمك القضاء، وإن قضيت فلا بأس، بعض أهل العلم يرى أنها إذا أدركت الحيض في وقت تقضي، ولكن ليس عليه دليل؛ لأنها لم تفرط، فإن قضيت فلا حرج، وإلا فلا قضاء عليك، لكن لو طهرت في وقت الظهر أو وقت العصر تصلين الظهر والعصر عند الطهارة، أو طهرت في الليل تصلين المغرب والعشاء، أما إذا هجمت عليك العادة وقت الظهر فليس عليك القضاء وإن قضيت فلا حرج، أو هجمت عليك بعد الغروب فليس عليك قضاء المغرب وإن قضيت فلا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12692/حكم-قضاء-الصلاة-لمن-حاضت-بعد-دخول-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61705.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14224,"question":"تسأل وتقول: إذا ذهبت مثلًا لأداء صلاة الظهر في الساعة الواحدة وعند الوضوء اكتشفت أن الدورة قد أتت، فهل يجب علي أن أصلي الظهر عند تطهري مع أنني لا أعلم هل هي قد أتت قبل دخول الوقت أم بعده؟","title":"حكم قضاء الصلاة لمن حاضت بعد دخول الوقت","answer":"الجواب: لا يلزمك القضاء، وإن قضيت فلا بأس، بعض أهل العلم يرى أنها إذا أدركت الحيض في وقت تقضي، ولكن ليس عليه دليل؛ لأنها لم تفرط، فإن قضيت فلا حرج، وإلا فلا قضاء عليك، لكن لو طهرت في وقت الظهر أو وقت العصر تصلين الظهر والعصر عند الطهارة، أو طهرت في الليل تصلين المغرب والعشاء، أما إذا هجمت عليك العادة وقت الظهر فليس عليك القضاء وإن قضيت فلا حرج، أو هجمت عليك بعد الغروب فليس عليك قضاء المغرب وإن قضيت فلا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12692/حكم-قضاء-الصلاة-لمن-حاضت-بعد-دخول-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61705.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14475,"question":"ما الذي يجوز للمرأة أن تعمله وهي جنب كإعداد الطعام وإرضاع الأطفال، وما شابه ذلك؟ هل هذا يؤثر أو لا تأثير له؟","title":"ما يحل للجنب والحائض والنفساء؟","answer":"الجواب: الحائض والجنب والنفساء تعد كل شيء مثل غيرها من النساء الطاهرات، تعد كل شيء، ما عدا مس المصحف، ما عدا قراءة القرآن في حق الجنب، يمنع من ذلك، وإلا فهي تطبخ وتقرب الطعام وتقرب القهوة والشاي، وتقدم الماء، تقدم اللبن، ما هي بنجسة طاهرة، إنما هذا حدث، حدث الجنابة يوجب الغسل فقط، وإلا عرقها طاهر، وبدنها طاهر، ويدها طاهرة ورأسها طاهر، وهكذا الحائض والنفساء كلتاهما طاهرة، وإنما النجاسة في الدم، فما أصاب بدنها من الدم، أو أصاب ثيابها غسلته، وأما يدها إذا كانت سليمة ليس بها دم فهي طاهرة، عرقها طاهر، شعرها طاهر، ريقها طاهر، كل ذلك طاهر من المرأة، كان النبي ﷺ يتعرق العظم من عائشة وهي حائض، تأكل منه، ويأكل منه -عليه الصلاة والسلام-، ويأكل معها وتأكل معه وهي حائض، وتغسل رأسه -عليه الصلاة والسلام-، وهي حائض، كل ذلك لا حرج فيه، والحمد لله. المقصود: أنّ المرأة الحائض والنفساء والجنب كلهم طاهرون بالنسبة للحكم الشرعي، عرقهم طاهر، وثيابهم طاهرة، وبدنهم طاهر، وما مسوه، لو مس بيده ماءً أو لبنًا أو طعامًا لا ينجسه ليس بنجس وليست بنجسة الحائض والنفساء، إنما عليهم غسل، غسل واجب، فالجنب يغتسل رجلًا كان أو امرأة، والحائض والنفساء كذلك تغتسلان، إذا رأتا الطهارة في وقت الطهارة، وما أصاب الحائض من دم في ثيابها أو بدنها غسلته، وهكذا النفساء، أما الجنب فهو عليه الغسل، وعرقهم طاهر، والحمد لله، وبدنهم كله طاهر، نعم. المقدم: جزاكم الله خيرًا، إرضاع الأطفال كأن عندهم شائعًا...\nالشيخ: كذلك إرضاع الأطفال كونها ترضع طفلها وهي جنب كما ترضعه وهي حائض لا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/12980/ما-يحل-للجنب-والحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63209.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14662,"question":"المرأة التي تتخذ سجادة للصلاة في بيتها هل في ذلك بأس يا شيخ؟","title":"حكم اتخاذ المرأة سجادة لها في بيتها للصلاة","answer":"الجواب: لا حرج، تتخذ سجادة، أو حصير، أو غير ذلك لا حرج في ذلك، كان النبي ﷺ له حصير يصلي عليه -عليه الصلاة والسلام-، لا بأس. المقدم: جزاكم الله عنا كل خير.","link":"https://binbaz.org.sa/fatwas/13148/حكم-اتخاذ-المراة-سجادة-لها-في-بيتها-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56003.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":14744,"question":"السائلة من ينبع تقول في هذا  والدتي حجت، وأحرمت بملابس هدية، فهل يلزمها شيء الآن؟","title":"حكم الإحرام بملابس أهديت إليها","answer":"الجواب: لا حرج في ذلك، سواء أحرمت في ملابس أهديت إليها، أو في ملابس أخرى، ما دامت ملابس مباحة، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13237/حكم-الاحرام-بملابس-اهديت-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56102.mp3","categories":["الإحرام","الحيض والنفاس","قضايا المرأة"]},{"id":14763,"question":"هل المرأة إذا طهرت من الدورة الشهرية تغتسل وتغير ملابسها، أم أنها لا تغير الملابس؟ أفيدونا بذلك.","title":"هل تغيير المرأة ملابسها بعد الطهر من الحيض؟","answer":"الجواب: المرأة إذا طهرت من حيضها أو نفاسها عليها أن تغتسل عند جميع أهل العلم، كما قال الله -جل وعلا-: وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ [البقرة:222] فلا بد من التطهر، لا تصلي ولا يقربها زوجها حتى تغتسل. أما الملابس إن جاءها دم يغسل ما أصابه الدم فقط، والملابس طاهرة عرقها طاهر، لكن إذا أصاب شيئًا من ملابسها شيء من الدم، يغسل محل الدم؛ كما أخبرت عائشة -رضي الله عنها-: أنهن كن يغسلن ما أصابه الدم من ذلك. الحاصل: أن ملابس المرأة التي حاضت فيها، أو نفست فيها طاهرة، ولا يضرها كونها تعرق فيها، أو تنام فيها إلا إذا أصابها دم، فما أصابه الدم يغسل منها، من أي بقعة أصابها الدم تغسل، وإذا غسلت الثوب كله فلا بأس، لكن لا ينجس إلا الذي أصابه الدم فقط، فإذا غسلت بقع الدم كفى، وإن غسلت الثوب كله فلا بأس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13251/هل-تغيير-المراة-ملابسها-بعد-الطهر-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56104.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14767,"question":"السائلة تقول: هل صحيح بأن وقت العادة هو سبعة أيام لا تزيد ولا تنقص؟ وإذا طهرت قبل السبعة أيام هل تصلي يا سماحة الشيخ؟","title":"هل مدة الحيض سبعة أيام؟","answer":"الجواب: السبعة ليست حدًا للحيض يزيد وينقص، قد تكون سبعة، قد تكون ثمانية، وقد تكون خمسة، وقد تكون ثلاثة، العادة تختلف، لكن المرأة المبتدأة التي ليس لها عادة سابقة تتحيض ستة أيام، أو سبعة أيام إذا استمر معها الدم، تتحرى ستة أو سبعة كعادة نسائها ثم تغتسل. أما المرأة التي لها عادة تمشي على عادتها، التي لها عادة ست، خمس، سبع، ثمان، عشر، تبقى مع عادتها ولا يتحدد بسبع ولا بخمس ولا بسبع ولا بثمان حسب العادة، مثلما قال النبي ﷺ لـأم حبيبة: امكثي قدر ما كانت تحبسك حيضتك، ثم اغتسلي فإذا كانت عادتها عشرًا جلست عشرًا. وإذا كانت عادتها ثلاثًا جلست ثلاثًا، وهكذا، وإذا رأت دمًا في حال الطهر، فهذا دم فساد، أو صفرة أو كدرة، هذا دم فساد، تتوضأ لكل صلاة، وإنما تسير على عادتها التي استقرت لها، خمس، ست، سبع، ثمان، عشر، أقل، أكثر، إلى خمسة عشر، لا تزيد على خمسة عشر العادة عند جمهور أهل العلم. فالحاصل: أنها تقف مع عادتها، إذا كانت العادة خمسًا، تتحيض خمسة أيام، إذا كانت عادتها سبعًا، عادتها ثمانًا كذلك، وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13255/هل-مدة-الحيض-سبعة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56106.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14961,"question":"كيف تعرف المرأة بأنها طهرت، تقول السائلة: أفتونا في ذلك؟","title":"كيف تعرف المرأة بأنها طهرت من الحيض؟","answer":"الجواب: إذا رأت الطهارة أو إذا رأت القصة البيضاء، هذه علامة الطهارة، تغتسل وتصلي، والحمد لله، ما دام معها صفرة، أو كدرة لا تعجل حتى تكمل عادتها، ثم تغتسل وتصلي.  أما ما يحصل لها بعد الطهر صفرة أو كدرة، هذا يعتبر دم فساد، تتوضأ لكل صلاة ويكفي، تتوضأ لكل صلاة وتصلي والحمد لله، حتى تأتي العادة المعروفة، نعم. المقدم: أحسن الله إليكم، وأثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13457/كيف-تعرف-المراة-بانها-طهرت-من-الحيض","audio":"","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14966,"question":"إذا اغتسلت المرأة من الحيض في وقت المغرب، فهل تصلي الظهر والعصر مع المغرب؟","title":"حكم قضاء الظهر والعصر على من طهرت بعد الغروب","answer":"الجواب: إذا كانت الطهارة بعد غروب الشمس ليس عليها صلاة الظهر والعصر.  أما إذا طهرت في العصر فإنها تصلي الظهر والعصر، أو طهرت في الليل تصلي المغرب والعشاء.  أما إن كانت الطهارة بعد غروب الشمس غابت الشمس وهي حائض، فإنها ليس عليها أن تصلي ظهرًا ولا عصرًا، ولا يشرع لها ذلك، ولكن تصلي المغرب والعشاء، نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13462/حكم-قضاء-الظهر-والعصر-على-من-طهرت-بعد-الغروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56216.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":14987,"question":"سؤالي الأخير هو صحيح أن المرأة إذا طهرت من العادة الشهرية عليها أن تعيد الصلاة فرضًا بفرض، ووقتًا بوقت، طيلة الأيام التي قضتها بالعادة، أو تصلي الصلاة نفسها بغير مكررة؟ولكم جزيل الشكر.","title":"هل تقضي الحائض الصلاة؟","answer":"الجواب: ليس على الحائض والنفساء قضاء، قالت عائشة -رضي الله عنها-: \"كنا نؤمر بقضاء الصوم، ولا نؤمر بقضاء الصلاة\" إنما تقضي أيام رمضان التي أفطرتها الذي في حال النفاس، أو في حال الحيض.  وأما الصلاة فالله -جل وعلا- أسقطها عنهما عن الحائض والنفساء، والحكمة في ذلك -والله أعلم- أنها كثيرة تكرر، فلو أمرت بقضائها لشق عليها، فمن رحمة الله أن أسقط عنها الصلوات في حال الحيض، وفي حال النفاس، فلا تقضيها، وإنما تقضي الصوم الأيام التي أفطرتها في رمضان تقضيها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13476/هل-تقضي-الحاىض-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49211.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15020,"question":"هذه أختكم في الله (أ. أ. ع) جدة، تقول: في الحديث عن أم سلمة -رضي الله عنها- قالت: «قلت: يا رسول الله، إني امرأة أشد شعر رأسي، أفأنقضه لغسل الجنابة -وفي رواية: والحيضة- فقال: لا، إنما يكفيك أن تحثي على رأسك ثلاث حثيات رواه مسلم.هل هذا يعني: أن غسل مقدمة الرأس ثلاث حثيات دون غسل باقي الشعر من الخلف يا سماحة الشيخ؟","title":"معنى حديث: \"إنما يكفيك أن تحثي...\"","answer":"الجواب: المعنى: أنها لا تنقض، ما يلزمها النقض، أن تحثي على رأسها ثلاث حثيات، وتسيل الماء على الجدائل، تعمها بالماء الجدائل، ولا يلزمها النقض، إذا عمته بثلاث حثيات، فإن الغالب أن هذا الماء يصل إلى الجوف -جوف الشعر- ثم تفيض الماء على بقية جسدها؛ فتطهر بإذن الله -والحمد لله-. ولكن النقض في الحيض، كما جاء في رواية أخرى: «أنه أمر بعض الحيض أن ينقضن شعرهن» نقضه أولى في الحيض وأكمل، وإن لم تنقض فلا بأس، كما في حديث أم سلمة.  أما في الجنابة فلا حاجة إلى النقض، تفيض الماء على رأسها وعلى بدنها، والحمد لله، الرجل والمرأة، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13518/معنى-حديث-انما-يكفيك-ان-تحثي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56305.mp3","categories":["الحيض والنفاس","الغسل"]},{"id":15074,"question":"سماحة الشيخ هذه السائلة تقول: إذا حاضت المرأة صح لها كل شيء في العمرة أو الحج إلا الطواف، كما في الحديث، فهل إذا جاءت المرأة إلى الميقات وهي حائض، فنوت العمرة، وسعت، وبقي لها الطواف، هل تنتظر حتى تطهر، ثم تطوف وتكمل العمرة أم لا؟","title":"حكم من حاضت قبل الطواف للعمرة","answer":"الجواب: الواجب عليها أنها تنتظر، لا يجوز لها أن تطوف وهي حائض، لكن لا ينبغي لها تقديم السعي، السنة أن تؤخر السعي، النبي ﷺ طاف، ثم سعى، فالسنة لها أن تؤخر السعي مع الطواف، هذا هو السنة، فإذا طهرت طافت وسعت، والحمد لله، نعم. المقدم: سماحة الشيخ، إذا لم تستطع الانتظار في مكة حتى تطهر وسافرت هل عليها شيء؟ الشيخ: عليها أن ترجع، إذا سافرت عليها أن يمتنع زوجها -إن كان لها زوج- وعليها أن ترجع، حتى تؤدي العمرة، إذا لم يتيسر لها الانتظار، نعم.","link":"https://binbaz.org.sa/fatwas/13568/حكم-من-حاضت-قبل-الطواف-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56406.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":15077,"question":"هذه الرسالة وردتنا من إحدى المستمعات، تقول في رسالتها، الرسالة وردتنا من كركوك المرسلة أميرة محمود، تقول في رسالتها: هل يجوز زيارة الأماكن المقدسة للفتاة الحائض؟","title":"ما حكم زيارة الحائض للأماكن المقدسة؟","answer":"الجواب: إذا كان قصدها المساجد فلا يجوز، في هذه الحالة لا تدخل المسجد، النبي -عليه الصلاة والسلام- قال: إني لا أحل المسجد لحائض ولا جنب فلا تزورها لقراءة القرآن فيها، أو الجلوس فيها، لا، لكن لو مرت بالمسجد لحاجة مرور عبور لتأخذ منه حاجة مصلى، أو كتاب، أو لتنبه أحدهم في المسجد نائم تدعوه، أو ما أشبه ذلك فلا بأس؛ لأن الله قال: إلَّا عَابِرِي سَبِيلٍ[النساء:43] ولأن النبي ﷺ أمر عائشة وهي حائض أن تناوله الخمرة من المسجد، والخمرة حصير في المسجد أمرها أن تناوله إياها، قالت له عائشة: «يا رسول الله، إني حائض! قال: إن حيضتك ليست في يدك فأمرها أن تأتي بالخمرة من المسجد وهي حائض؛ لأنه مرور، عبور، فلا حرج في ذلك -إن شاء الله-. أما إن كانت تقصد أماكن أخرى غير المساجد، فلا بد من بيانها، ما هي الأماكن المقدسة؟ المقابر لا تزورها المرأة، المرأة لا تزور القبور، الرسول ﷺ: لعن زائرات القبور ولا يقال فيها: مقدسة، ولا أعلم شيئًا غير المساجد تمنع منه، إنما الممنوع المساجد، أما أي مكان تزوره المرأة لحاجة فلا بأس، ولا يقال في شيء: مقدس إلا بدليل، فالمساجد مقدسة منزهة عن النجاسات، فيقال لها: مقدسة، من هذا المعنى، وأما بيوت الناس أو المقابر فلا يقال لها: مقدسة، نعم.","link":"https://binbaz.org.sa/fatwas/13570/ما-حكم-زيارة-الحاىض-للاماكن-المقدسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66306.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15079,"question":"هذه الرسالة وردتنا من إحدى المستمعات، تقول في رسالتها، الرسالة وردتنا من كركوك المرسلة أميرة محمود، تقول في رسالتها: هل يجوز زيارة الأماكن المقدسة للفتاة الحائض؟","title":"ما حكم زيارة الحائض للأماكن المقدسة؟","answer":"الجواب: إذا كان قصدها المساجد فلا يجوز، في هذه الحالة لا تدخل المسجد، النبي -عليه الصلاة والسلام- قال: إني لا أحل المسجد لحائض ولا جنب فلا تزورها لقراءة القرآن فيها، أو الجلوس فيها، لا، لكن لو مرت بالمسجد لحاجة مرور عبور لتأخذ منه حاجة مصلى، أو كتاب، أو لتنبه أحدهم في المسجد نائم تدعوه، أو ما أشبه ذلك فلا بأس؛ لأن الله قال: إلَّا عَابِرِي سَبِيلٍ[النساء:43] ولأن النبي ﷺ أمر عائشة وهي حائض أن تناوله الخمرة من المسجد، والخمرة حصير في المسجد أمرها أن تناوله إياها، قالت له عائشة: «يا رسول الله، إني حائض! قال: إن حيضتك ليست في يدك فأمرها أن تأتي بالخمرة من المسجد وهي حائض؛ لأنه مرور، عبور، فلا حرج في ذلك -إن شاء الله-. أما إن كانت تقصد أماكن أخرى غير المساجد، فلا بد من بيانها، ما هي الأماكن المقدسة؟ المقابر لا تزورها المرأة، المرأة لا تزور القبور، الرسول ﷺ: لعن زائرات القبور ولا يقال فيها: مقدسة، ولا أعلم شيئًا غير المساجد تمنع منه، إنما الممنوع المساجد، أما أي مكان تزوره المرأة لحاجة فلا بأس، ولا يقال في شيء: مقدس إلا بدليل، فالمساجد مقدسة منزهة عن النجاسات، فيقال لها: مقدسة، من هذا المعنى، وأما بيوت الناس أو المقابر فلا يقال لها: مقدسة، نعم.","link":"https://binbaz.org.sa/fatwas/13570/ما-حكم-زيارة-الحاىض-للاماكن-المقدسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66306.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15223,"question":"أخيرًا تسأل أختنا وتقول: ما حكم الذهاب للمسجد لحضور الندوات والمحاضرات، إذا كانت المرأة حائضًا؛ وذلك للاستفادة من الدروس التي غالبًا ما تكون قيمة؟","title":"حكم جلوس الحائض في المسجد لسماع الدروس","answer":"الجواب: إذا كان لها مكان قرب المسجد تسمع منه عند المحراب، أو في جانب المسجد، أو في آخر المسجد، تسمع، فلا بأس. أما في داخل المسجد فلا؛ لأن النبي  قال: إني لا أحل المسجد لحائض ولا جنب وقال في حق الجنب: إِلَّا عَابِرِي سَبِيلٍ [النساء:43] وقال لـعائشة لما أمرها أن تأتي بالخمرة من المسجد، قالت : إني حائض، قال: إن حيضتك ليست في يدك فأمرها أن تعبر وتأخذ الخمرة الحصير من المسجد. أما الجلوس، لا، أما المرور للجنب والحائض فلا بأس، أما الجلوس لا، لكن إذا وجد مكان خارج المسجد تسمع منه الدروس، فهذا لا بأس به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13713/حكم-جلوس-الحاىض-في-المسجد-لسماع-الدروس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49702.mp3","categories":["الحيض والنفاس","المساجد ومواضع السجود","قضايا المرأة"]},{"id":15311,"question":"في ثاني أسئلة السائلة من دمشق تقول: هل يجوز للمرأة أن تقرأ القرآن أثناء دورتها الشهرية في القلب، أي: مع شريط تسجيل، الشيخ يقرأ في هذا الشريط التسجيل، وأنا أردد معه في قلبي، أو على لساني؟فأفيدوني في سؤالي.","title":"هل يجوز للمرأة أن تقرأ القرآن أثناء دورتها الشهرية؟","answer":"الجواب: سماع القرآن من الحائض والنفساء والجنب لا بأس به، كون الحائض تستمع من الشريط أو من القارئ، وهكذا النفساء وهكذا الجنب، الاستماع لا بأس به، لكن لا يقرأ الجنب حتى يغتسل، لا من المصحف، ولا عن ظهر قلب حتى يغتسل؛ لأن الرسول نهى عن هذا -عليه الصلاة والسلام-. أما الحائض والنفساء فاختلف العلماء فيهما هل تلحقان بالجنب أم لا؟ والصواب: أنهما لا تلحقان بالجنب؛ لأن مدتهما تطول، فلهما أن تقرأا عن ظهر قلب، ولهما أن تراجعا المصحف من دون حائل عند مراجعة بعض الآيات، لا حرج في هذا، هذا هو الصواب.  أما حديث: لا تقرأ الحائض ولا الجنب شيئًا من القرآن فهو حديث ضعيف، نعم.","link":"https://binbaz.org.sa/fatwas/13809/هل-يجوز-للمراة-ان-تقرا-القران-اثناء-دورتها-الشهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56606.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15312,"question":"في فقرة لها تقول -سماحة الشيخ- بالنسبة لقص الأظافر، وتمشيط الشعر أثناء الدورة الشهرية، هل فيه شيء؟","title":"جواز قص الحائض أظفارها ومشط شعرها","answer":"الجواب: لا بأس، قص الأظافر والمشط وقت الدورة لا حرج، في النفاس والدورة كل هذا لا حرج فيه، الحمد لله، نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/13810/جواز-قص-الحاىض-اظفارها-ومشط-شعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56607.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15515,"question":"من أسئلة هذه السائلة تقول سماحة الشيخ: بأنها معلمة تدرس القرآن، ولكن تقول: كما هو معروف يأتي وقت الدورة الشهرية وهي تدرس في معظم أيام الأسبوع حصص القرآن، فهل يجب عليها في كل يوم أن تلبس القفازات أو تمسك المصحف بالفاين حتى لا تمسه؟","title":"حكم مس المصحف للمدرسة وهي حائض","answer":"الجواب: إذا كانت تدرس عن ظهر قلب كفى، إذا كانت حافظة للقرآن تدرسهم عن ظهر قلب، فإذا احتاجت المصحف يكون من وراء القفازين، لا تمسه بيدها يكون من وراء القفازين، أو غير القفازين، يكون بينها وبينه حائل من قفازين، أو غيرهما، نعم.","link":"https://binbaz.org.sa/fatwas/14053/حكم-مس-المصحف-للمدرسة-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69108.mp3","categories":["الحيض والنفاس","القرآن وعلومه","قضايا المرأة"]},{"id":15548,"question":"هذه سائلة للبرنامج تقول: أسأل يا سماحة الشيخ، عن حفظ سور من القرآن الكريم، حيث أنها تحفظ عشر سور من جزء عم، وتستمر في الدوام على تحفيظ القرآن الكريم، مع العلم تقول: بأنني في وقت الحيض أمسك بالمصحف وأقرأ منه، فهل يصح ذلك؟","title":"حكم لمس المرأة الحائض للمصحف","answer":"الجواب: اجتهدي في حفظ ما تيسر من القرآن، اجتهدي في حفظ ما تيسر، حتى ينفعك ذلك في صلاتك وغير الصلاة، اجتهدي وأبشري بالخير.  وإذا قرأت القرآن من وراء حائل للحاجة فلا بأس أن يكون في اليدين قفازات من وراء حائل، فلا بأس، الصواب للحائض أن تقرأ، وللمرأة أن تمس المصحف، لكن من وراء حائل، تمسكه من وراء القفازين عند الحاجة إلى مراجعته، نعم.","link":"https://binbaz.org.sa/fatwas/14089/حكم-لمس-المراة-الحاىض-للمصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69125.mp3","categories":["الحيض والنفاس","القرآن وعلومه","قضايا المرأة"]},{"id":15654,"question":"سؤالها الثاني تقول: إذا أجهضت المرأة فما حكم دم الإجهاض؟ هل حكمه كالنفاس أم كالحيض؟ وما هي أكثر مدته وأقلها؟","title":"حكم دم الإجهاض","answer":"الجواب: إن كان الإجهاض بعدما تخلق الطفل وجد فيه علامة الإنسان من رجل أو رأس أو يد، ولو خفيًا، فإنه نفاس حكمه حكم النفاس، وعليها أن تبقى حتى تطهر، ولو إلى أربعين يومًا؛ لأن هذه نهاية النفاس أربعون يومًا، هذه النهاية. فإن طهرت قبل ذلك لعشرين أو لشهر اغتسلت وصلت وصامت، وحلت لزوجها، فإن استمر معها الدم تركت الصلاة والصوم، ولم تحل لزوجها حتى تكمل الأربعين، إذا كملت الأربعين اغتسلت وصلت وصامت وحلت لزوجها، ولو كان معها الدم؛ لأنه دم فساد حينئذٍ، فإن النفاس نهايته وأكثره أربعون يومًا، فما زاد عليه يعتبر دم فساد، تصلي وتصوم بعد الغسل، وتحل لزوجها، وتتحفظ بالقطن ونحوه، وتتوضأ لكل صلاة كالمستحاضات، وصاحب السلس.  أما لو طهرت لأقل من ذلك لعشرين أو لخمسة عشر أو لثلاثين، أو نحو ذلك، فإنها تغتسل وتصلي وتصوم ولو كانت في أثناء الأربعين، وتحل لزوجها أيضًا. أما إن كان هذا الإجهاض ما تخلق، بل أجهضته دمًا أو لحمة ليس فيها خلق إنسان بيّن، فإن هذا يعتبر دم فساد، تصلي وتصوم كصاحب السلس، وتتوضأ لوقت كل صلاة إذا دخل الوقت، وتعتبر نفسها كالمستحاضة، وكصاحب السلس وكالمريض إذا شق عليها ذلك تصلي الظهر والعصر جميع والمغرب والعشاء، جميع من أجل الدم؛ كثرة الدم. فالمقصود: أنها في هذه الحالة كالمستحاضة، وكصاحب السلس، تصلي وتصوم وتحل لزوجها؛ لأنه ليس بنفاس حتى ينقطع عنها ذلك، وتتوضأ لوقت كل صلاة كما تقدم، نعم.","link":"https://binbaz.org.sa/fatwas/14198/حكم-دم-الاجهاض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69904.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15726,"question":"يقول السائل: إذا طهرت المرأة من حيضها في أحد الأوقات الخمسة للصلاة، فماذا يلزمها أن تصلي؟الشيخ: أعد.المقدم: يقول: إذا طهرت المرأة من حيضها في أحد الأوقات الخمسة للصلاة فماذا يلزمها أن تصلي؟ وهل تقضي الصلاة التي كانت قبل طهرها مباشرة، كأن تطهر في وقت العصر، فهل تقضي الظهر، أو أن تطهر في وقت المغرب فهل تقضي العصر وهكذا؟أفتونا، مأجورين.","title":"حكم من طهرت من حيضها في أحد أوقات الصلاة","answer":"الجواب: إذا طهرت في وقت صلاة، تجمع إلى ما يليها، تصلي الثنتين، فإذا طهرت في وقت العصر صلت الظهر والعصر، وإذا طهرت في وقت العشاء صلت المغرب والعشاء، وإذا طهرت بعد طلوع الفجر صلت الفجر فقط؛ هذا هو الواجب عليها، كما أفتي بذلك جماعة من الصحابة -رضي الله عنهم وأرضاهم-؛ لأنها كالمعذور -كالمريض- يجمع بين الصلاتين. فإذا طهرت في العصر فهي كالمريض -تصلي الظهر والعصر- وإذا طهرت في الليل صلت المغرب والعشاء، أما إذا لم تطهر إلا بعد الفجر، فإنها تصلي الفجر فقط، أما إن كان طهورها -تطهرها- انقطع الدم عنها بعد طلوع الشمس، ما طهرت إلا الضحى، فليس عليها شيء؛ لأن الفجر قد زال، قد ذهب وقتها الفجر، ولم تطهر إلا بعد طلوع الشمس فليس عليها شيء إلا الفروض المستقبلة، لكن إذا طهرت في وقت صلاة، طهرت قبل طلوع الشمس تصلي الفجر، طهرت قبل الفجر تصلي المغرب والعشاء، طهرت قبل غروب الشمس تصلي العصر والظهر، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14288/حكم-من-طهرت-من-حيضها-في-احد-اوقات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57413.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15749,"question":"بعد هذا لها سؤال آخر تقول فيه: أنا طالبة في مدرسة، ويوجد في المدرسة مسجد، وتقام فيه الصلاة، وتلقى فيه المحاضرات والدروس، فهل يجوز أن أجلس للاستماع وللاستفادة وأنا معذورة، أم لا يجوز؟","title":"حكم جلوس الحائض في مصلى المدرسة","answer":"الجواب: إذا كان هذا المسجد مصلى عادي فلا بأس، تجلس فيه الحائض والنفساء والجنب لا بأس، أما إذا كان مصلى للصلوات الخمس، مسجد بني للصلوات الخمس الدائرة تدور فيه الصلوات الخمس، مسجد؛ هذا لا تجلس فيه الحائض ولا النفساء ولا الجنب.  أما المصلى العادي، غرفة يصلون فيها، أو صالة يصلون فيها؛ هذه ليس لها حكم المساجد، لا بأس أن تجلس فيها الحائض والنفساء والجنب، وليس فيها تحية مسجد، نعم. المقدم: جزاكم الله خيرًا، إذًا المصلى الذي في مدرسة البنات يقال له: مصلى أو مسجد سماحة الشيخ؟\nالشيخ: يقال له: مصلى، إلا إذا كان معدًا للصلوات الخمس، مسجد يصلى فيه الصلوات الخمس، مبني وموقوف مسجد، يصلى فيه أو للظهر فقط، المسجد؛ فهذا له حكم المساجد، أما إذا كان مصلى عادي من الغرف أو صالة من الصالات، هذا يسمى مصلى.\nالمقدم: من المعلوم أن مدارس البنات لا تبقى أربعًا وعشرين ساعة؛ فحينئذٍ يكون مصلى. الشيخ: مصلى، المعروف أنه مصلى، غرفة من الغرف، أو صالة من الصالات يصلون فيها، ليس لها حكم المساجد، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14339/حكم-جلوس-الحاىض-في-مصلى-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70706.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":15927,"question":"سماحة الشيخ، هذا السائل يقول: هل يجوز أن يذبح الإنسان وهو على جنابة؟","title":"حكم ذبح الجنب والحائض والنفساء","answer":"الجواب: لا حرج أن يذبح وهو على جنابة، وهكذا الحائض لو ذبحت وهي حائض أو نفساء لا حرج في ذلك، فالصواب لا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/14524/حكم-ذبح-الجنب-والحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57717.mp3","categories":["الحيض والنفاس"]},{"id":16013,"question":"من المعلوم أن علامة طهر المرأة القصة البيضاء تقول السائلة: ولكنني لا أدري هل هذه العلامة.. وبعد الاغتسال أرى لونًا بنيًا فاتحًا جدًا، هل يمكن اعتبار هذا اللون هو الطهر؟","title":"هل القصة البيضاء هي علامة الطهر من الحيض؟","answer":"الجواب: الطهر زوال آثار الدم، فإذا تلطفت بقطنة أو شيء آخر ولم يكن فيه أثر للدم تغتسل، ولو ما رأت القصة البيضاء، أما القصة البيضاء فهو ماء أبيض يعتري بعض النساء، عند نهاية الحيض تجد ماءً أبيض علامة أن الحيض انتهى، وبعض النساء لا يجد هذا، فالعبرة بوجود النظافة، فإذا تلطفت بقطن أو غيره ورأت النظافة، ولم يبق صفرة ولا كدرة تغتسل، ولو ما رأت القصة البيضاء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14642/هل-القصة-البيضاء-هي-علامة-الطهر-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57903.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":16170,"question":"تسأل سماحتكم -لو تكرمتم- عن المرأة إذا حاضت وهي في الحرم ماذا تفعل؟ في الحج؟","title":"ما تفعل المرأة الحائض في الحج؟","answer":"الجواب: إذا حاضت فيها تفصيل، إذا كانت حاضت بعد الطواف، طواف الإفاضة؛ حجها تام، وليس عليها طواف وداع، إذا سافرت من مكة، وبها حيض، أو نفاس يسقط عنها طواف الوداع. أما إذا حاضت قبل أن تطوف طواف الإفاضة؛ فإنها تبقى حتى تطوف للإفاضة، تبقى في مكة حتى تكمل حجها بالطواف، ولا يضرها كونها تقف بعرفة وهي حائض أو نفساء، أو ترمي الجمار وهي حائض؛ لا يضرها ذلك، أو تبيت في مزدلفة وفي منى كذلك. إنما الحيض يمنع الطواف فقط، أما بقية أعمال الحج فلها أن تفعلها وهي حائض، أو نفساء والحمد لله، لكن لا تطوف؛ لأنه صلاة،  الطواف لا تطوف حتى تطهر، ولكن يسقط عنها طواف الوداع، إذا صادفها الحيض عند السفر؛ فإنه يسقط عنها طواف الوداع؛ لقول ابن عباس -رضي الله عنهما-: \"أمر الناس أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" والنفساء في حكمها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14839/ما-تفعل-المراة-الحاىض-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80503.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":16260,"question":"تقول: هل يجوز قص أظافر المرأة، أو شيء من شعرها وهي معذورة؟","title":"حكم قص الحائض شعرها وتقليم أظافرها","answer":"الجواب: لا بأس أن تقص أظافرها، أو تنتف إبطها، أو تزيله بالأدوية، أو العانة كل ذلك لا بأس به، وإن كانت في الحيض، أو في النفاس، كالرجل له أن يزيل ذلك، وإن كان على جنابة. المقصود: أن هذه الأشياء لا يشترط لها الطهارة، للمرأة أن تقص أظافرها، وأن تزيل العانة بالحلق، أو بغيره، تزيل شعر الإبط بالنتف، أو بغيره، سواء كانت طاهرة، أو في حيض، أو في نفاس، أو على جنابة، والرجل كذلك له أن يزيل هذه الشعور، وإن كان على جنابة، كنتف الإبط، وحلق العانة، وقص الشارب، وقلم الظفر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14952/حكم-قص-الحاىض-شعرها-وتقليم-اظافرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80806.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":16372,"question":"السائلة تقول: فتاة حاضت في الطواف، وكانت قد اغتسلت من الحيض في الميقات، ومدة حيضها من أربعة أيام إلى خمسة أيام، فعاد إليها الحيض في يوم الطواف، وهو الخامس، ولكنها أكملت طوافها على أنها اعتبرت ذلك دم استحاضة، أو من شدة الحر، أو أن ذلك نهاية للطهر؟","title":"ما يجب على من طافت وهي حائض؟","answer":"الجواب: عليها أن تعيد الطواف، تستنجي، وتتوضأ وضوء الصلاة؛ لأنه دم فساد، ما دام بعد طهرها من الحيض يكون دم فساد، تستنجي، وتتوضأ وضوء الصلاة، وتعيد الطواف، والأفضل تعيد السعي أيضًا، ثم تقصر، وإن كانت عند أهلها رجعت، نعم. المقدم: إذًا ما يلزمها دم يا شيخ؟  الجواب: لا، إذا كان ما عندها زوج، إن كان عندها زوج؛ فعليها دم، ذبيحة تذبح في مكة للفقراء، وتكمل العمرة، ثم تقضيها أيضًا من ميقاتها مرة أخرى، تحرم من الميقات الذي أحرمت منه... الأولى، فعليها تمام هذه الطواف والسعي والتقصير والذبيحة، ثم ترجع إلى الميقات، وتأتي بعمرة جديدة، كما أفتى بعض الصحابة بذلك، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15071/ما-يجب-على-من-طافت-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58116.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":16541,"question":"أيضًا تسأل في سؤال آخر تقول: إنني لا أتذكر هل كنت أغتسل، أو لا؟","title":"حكم من نسيت هل اغتسلت بعد الحيض أم لا؟","answer":"الجواب: هذا أيضًا ما عليه عمل، ما دام حصل النسيان، فالأصل السلامة -إن شاء الله- ليس عليك شيء، الأصل في المسلم أنه يغتسل، ويقوم بالواجب، هذا هو الأصل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15281/حكم-من-نسيت-هل-اغتسلت-بعد-الحيض-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81511.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":16649,"question":"إحدى الأخوات تسأل سماحتكم، فتقول: هل يجوز استغلال فترة العذر الشرعي لمراجعة القرآن الكريم لمن تحفظه خوفًا من النسيان؟","title":"ما حكم قراءة الحائض للقرآن؟","answer":"الجواب: الصواب أنه لا حرج في ذلك، أن تقرأ عن ظهر قلب حال الحيض والنفاس؛ لأنها ليست مثل الجنب، فالجنب في إمكانه أن يغتسل بسهولة، إذا فرغ من حاجته؛ اغتسل، وقرأ، وصلى، أما الحائض، والنفساء فليس في إمكانهما ذلك؛ لأن المدة تطول، فإذا قرأت عن ظهر قلب؛ فلا بأس بذلك على الصحيح، وبعض أهل العلم ذهب إلى منعها من ذلك كالجنب. والصواب: أنها لا تمنع من ذلك، لكن ليس من المصحف، بل تقرأ عن ظهر قلب، وإذا دعت الحاجة إلى مراجعة المصحف من وراء حجاب، من وراء القفازين، ونحوها؛ فلا حرج عند الحاجة، وهذا هو الصواب. أما حديث لا تقرأ الحائض، ولا الجنب شيئًا من القرآن فهو حديث ضعيف، إنما الثابت في الجنب خاصة \"كان النبي ﷺ لا يحجزه شيء عن القرآن، إلا الجنابة\" ويقول ﷺ لما خرج بأصحابه ذات يوم قرأ وهو على غير طهارة، قال: هذا لمن لم يكن جنبًا، أما الجنب فلا ولا آية المقصود أن الجنب لا يقرأ حتى يغتسل. أما الحائض، والنفساء فمدتهما تطول، والصحيح من قولي العلماء أنه لا بأس أن تقرأ الحائض والجنب عن ظهر قلب؛ لأن المدة تطول، وفي ذلك مشقة، وحرج، وتفويت لمصالح كثيرة في حق الحائض، والنفساء بدون دليل، نعم. والقياس لا يصلح، قياس الحائض على الجنب لا يصلح؛ لأن الجنب مدته لا تطول، وفي إمكانه الغسل متى فرغ من حاجته، أما الحائض فليس في إمكانها الغسل إلا بعد انتهاء المدة، وهكذا النفساء ليس في إمكانها الغسل حتى ينقطع الدم، وتطهر، أو تبلغ الأربعين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15382/ما-حكم-قراءة-الحاىض-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71712.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":16657,"question":"من أسئلتها تقول سماحة الشيخ: بأنه نزل أثناء وجودهم في المدرسة مطر غزير، فاستدعى الأمر أن يدخلوا في مسجد المدرسة، تقول وهي حائض، فدخلت معهم، هل عليها شيء؟ وهل المسجد في المدرسة يأخذ حكم المصلى؟ وفقكم الله.","title":"ما حكم دخول الحائض المسجد للضرورة؟","answer":"الجواب: إذا دخلت المرأة الحائض، أو النفساء المسجد للضرورة؛ فلا بأس، كأن تخشى على نفسها إذا كانت خارج المسجد للضرورة، أو لأسباب أخرى اضطرتها إلى ذلك؛ فلا حرج. أما مسجد المدرسة إذا كان مصلى ليس له حكم المساجد، إذا كان مصلى في المدرسة لها أن تجلس فيه؛ لأنه ليس لها حكم المساجد، المصلى في المدارس ليس له حكم المساجد، فللحائض، والنفساء أن تجلس في المصلى لسماع الخطبة، أو سماع الدرس، أو الفائدة، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/15390/ما-حكم-دخول-الحاىض-المسجد-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58314.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":16658,"question":"ما حكم لمس المرأة الحائض للمصحف إذا وجدته في الأرض، وليس معها حائل، ورفعته؟","title":"حكم لمس الحائض للمصحف للضرورة","answer":"الجواب: الظاهر أنه لا حرج -إن شاء الله- لأن هذا من تعظيم المصحف، إذا وجدته في الأرض، يخشى أن يطأه الناس، لكن إذا تيسر أن يكون من وراء حائل، من وراء خمارها، أو طرف ثوبها، يكون هذا أحوط، تأخذه بخمار، أو بخرقة أخرى بين يديها وبين المصحف، هذا أفضل، حتى تضعه في المحل المناسب.","link":"https://binbaz.org.sa/fatwas/15391/حكم-لمس-الحاىض-للمصحف-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58315.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":16799,"question":"هل يجوز حمل المصحف دون وضوء؟ أو الكتب الدينية، أو التفسير؟ وكذلك في حالة الحيض هل يمكن قراءة الكتب الدينية، أو التفسير؟ وما الحكم في حمل أشرطة القرآن الكريم؟","title":"حكم حمل الحائض والنفساء للقرآن وكتب التفسير","answer":"الجواب: حمل المصحف إذا كان في جراب لا بأس، على غير وضوء في جراب من خرق، أو غيرها، أو بعلاقة، طرف العلاقة مربوط فيه فلا بأس، ينقل من محل إلى محل، أما حمله باليد من دون غلاف، ومن دون علاقة لا، إلا على وضوء. وأما كتب التفسير، وكتب الحديث فلا بأس، يحملها الجنب، والحائض، ولا حرج بأن تقرأ في ذلك، ويقرأ الجنب كتب التفسير وكتب الفقه وكتب الحديث لا حرج في ذلك. والحائض أيضًا لها أن تقرأ -عن ظهر قلب- القرآن؛ لأن مدتها تطول، والنفساء كذلك، ليستا مثل الجنب، الجنب لا يقرأ حتى يغتسل، لا عن ظهر قلب، ولا من المصحف حتى يغتسل، أما الحائض لا ما هي مثل الجنب، لا تقرأ من المصحف، لكن تقرأ عن ظهر قلبها حفظًا؛ لأن مدتها تطول، فالصواب أنه لها أن تقرأ، هذا الصواب، والنفساء كذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15570/حكم-حمل-الحاىض-والنفساء-للقران-وكتب-التفسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82308.mp3","categories":["الحيض والنفاس","القرآن وعلومه","قضايا المرأة"]},{"id":16803,"question":"تسأل سؤالًا آخر يتعلق بالطهر، تقول: هل الدم الذي يخرج من المرأة بعد غسلها من الحيض، وبعد أن ترى الطهر، وقد تراه بنفس يوم اغتسالها، أو بعده بيوم، أو يومين، هل يجزئ الوضوء فقط؟ أم الاغتسال؟ مع العلم أنه في بعض الأحيان يكون في كل الأوقات، وإذا كان يوجب الغسل، فما العمل في الصلوات التي في الماضي؟ مع العلم أن الدم قليل جدًا، أفيدوني جزاكم الله خيرًا.","title":"حكم الدم الخارج من المرأة بعد غسلها من الحيض","answer":"الجواب: إذا كان الدم صفرة، أو كدرة، ليس بالدم الصريح فهذا مثل البول، يكفي فيه الوضوء، والحمد لله. أما إذا طهرت، ثم جاءها الدم، العادة، ليس بالصفرة، ولا الكدرة؛ فهذا لا تصلي، بل تجلس، ولا تصلي حتى يزول، ثم تغتسل؛ لأن هذا تبع الحيض السابق، الحيضة تزيد، وتنقص، هذا هو الصواب، إلا إذا طال معها، زاد، أو استمر معها، هذا يسمى استحاضة، إذا كان مستمرًا معها، ليس له حد، بل يستمر معها؛ هذا تجلس للعادة، ويكفي، خمسًا، ستًا، سبعًا، عادتها في الحيض، وما زاد على ذلك ليس بشيء، تغتسل، وتصلي، وتصوم، ويأتيها زوجها. وأما إذا كان عادتها خمسًا، ثم اغتسلت، ثم جاءها الدم، دم مثل الدم الأول، دم صحيح، هذا تدع الصلاة، والصيام، وتجلس حتى ينتهي، إلا إذا زاد عليها بعد خمسة عشر يومًا فأكثر، زاد على ذلك؛ فهذا يكون استحاضة، أما ما دام في حدود خمسة عشر فأقل فإنه حيض؛ لأن الحيضة قد تبلغ خمسة عشر، وأربعة عشر، وثلاثة عشر، لكن الغالب ستًا.. سبعًا.. ثمانًا، ونحو ذلك. لكن بعض النساء إذا كانت عادتها طويلة، ثم رأت الطهر، ثم عاد الدم، فإنه يكون حيضًا، إلا كان صفرة، أو كدرة، فهذا لا تلتفت إليه، بل تصلي، وتصوم، وتتوضأ وضوء الصلاة. أما الدم ... فإنها تجلس، لا تصلي، ولا تصوم إلا إذا كان قد استمر معها أكثر من خمسة عشر يومًا، طال عليها، فهذا يكون استحاضة، ترجع إلى عادتها المعروفة سبعًا، أو خمسًا، أو أكثر من ذلك، فلا تصلي فيها، وما زاد عليها يكون استحاضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15566/حكم-الدم-الخارج-من-المراة-بعد-غسلها-من-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82306.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":16807,"question":"هل يجوز حمل المصحف دون وضوء؟ أو الكتب الدينية، أو التفسير؟ وكذلك في حالة الحيض هل يمكن قراءة الكتب الدينية، أو التفسير؟ وما الحكم في حمل أشرطة القرآن الكريم؟","title":"حكم حمل الحائض والنفساء للقرآن وكتب التفسير","answer":"الجواب: حمل المصحف إذا كان في جراب لا بأس، على غير وضوء في جراب من خرق، أو غيرها، أو بعلاقة، طرف العلاقة مربوط فيه فلا بأس، ينقل من محل إلى محل، أما حمله باليد من دون غلاف، ومن دون علاقة لا، إلا على وضوء. وأما كتب التفسير، وكتب الحديث فلا بأس، يحملها الجنب، والحائض، ولا حرج بأن تقرأ في ذلك، ويقرأ الجنب كتب التفسير وكتب الفقه وكتب الحديث لا حرج في ذلك. والحائض أيضًا لها أن تقرأ -عن ظهر قلب- القرآن؛ لأن مدتها تطول، والنفساء كذلك، ليستا مثل الجنب، الجنب لا يقرأ حتى يغتسل، لا عن ظهر قلب، ولا من المصحف حتى يغتسل، أما الحائض لا ما هي مثل الجنب، لا تقرأ من المصحف، لكن تقرأ عن ظهر قلبها حفظًا؛ لأن مدتها تطول، فالصواب أنه لها أن تقرأ، هذا الصواب، والنفساء كذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15570/حكم-حمل-الحاىض-والنفساء-للقران-وكتب-التفسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82308.mp3","categories":["الحيض والنفاس","القرآن وعلومه","قضايا المرأة"]},{"id":17148,"question":"يقول هذا السائل سماحة الشيخ: إذا طهرت المرأة من الحيض وقت الظهر، فماذا عليها أن تصلي، وإن طهرت وقت العصر، أو المغرب، أو العشاء، أو الفجر، ماذا عليها من قضاءٍ وصلاة؟","title":"إذا طهرت المرأة في العصر هل يجب عليها أن تصلي الظهر؟","answer":"الجواب: إذا طهرت في الظهر، أو العصر تصلي الظهر والعصر، وإذا طهرت في الليل تصلي المغرب والعشاء، هذا هو الواجب عليها كما أفتى بذلك جمع من الصحابة -رضي الله عنهم وأرضاهم- فإذا طهرت العصر فإن الواجب عليها أن تصلي الظهر والعصر جميعًا، وإذا طهرت بعد المغرب، أو بعد العشاء أو في وسط الليل، أو قبل الفجر تصلي المغرب، والعشاء. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15966/اذا-طهرت-المراة-في-العصر-هل-يجب-عليها-ان-تصلي-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58928.mp3","categories":["الحيض والنفاس","وقت الصلاة","قضايا المرأة"]},{"id":17189,"question":"السائلة يا سماحة الشيخ تقول: ما حكم الكدرة التي تنزل في نهاية الدورة الشهرية حيث إن البعض من الناس يرون أنها طاهرة؟","title":"حكم الكدرة في نهاية الدورة الشهرية","answer":"الجواب: هذه تختلف، إن كانت بعد رؤية الطهر فإنها تصلي، وتصوم، ولا عمل عليها، تتوضأ لكل صلاة، والكدرة ليست بحيض، إذا رأت الكدرة بعد الطهر تصلي وتصوم وتحل لزوجها وتتوضأ لكل صلاة، كالبول، تتوضأ لكل صلاة. أما إن كانت الكدرة في أثناء الحيض.. في آخر الحيض فلا تعجل حتى تزول الكدرة، ثم تغتسل، الكدرة التي متصلة بالحيض ما هي بحيض حتى ترى القصة البيضاء، أو الطهر النقي، ثم تغتسل.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16008/حكم-الكدرة-في-نهاية-الدورة-الشهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59017.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17195,"question":"السائلة: (ل. ع. ن) من الرياض، تقول: بأنها كانت حاملًا في الشهر الثالث، وسقط هذا الحمل، وقد دخل عليه شهر رمضان وكان ينزل عليها دم، ولم تصم اليوم الأول من هذا الشهر وصامت الباقي، فهل عليها صوم، أم لا؟ أفيدوني مأجورين.","title":"هل تصلي وتصوم من أسقطت في الشهر الثالث؟","answer":"الجواب: إذا كان هذا الجنين ما تخلق فهذا الدم دم فساد، تصلي وتصوم وتتوضأ لكل صلاة، أما إذا كان قد تخلق فيه رأس، أو رجل، أو يد؛ تبين يصير نفاسًا، لا تصلي، ولا تصوم حتى ترى الطهارة، أو تكمل الأربعين. أما مادام دمًا؛ فصلاتها صحيحة، وصومها صحيح، وعليها أن تتوضأ لكل صلاة مادام معها دم، تتوضأ لكل صلاة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16014/هل-تصلي-وتصوم-من-اسقطت-في-الشهر-الثالث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59023.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17328,"question":"السائلة من جمهورية مصر العربية، ومقيمة بالدمام تقول: نويت الإحرام من الميقات، ثم بعد ذلك.. هذه المرأة نوت الإحرام من الميقات، ثم بعد ذلك نزل عليها الحيض قبل الوقوف بعرفة، ثم طهرت في اليوم الحادي عشر، وسعت، وطافت بدون إعادة للإحرام أي: أنها لم تذهب مرة أخرى للميقات لتجدد إحرامها بعد أن طهرت، فهل فعلها صحيح؟","title":"حكم من أتاها الحيض بعد الإحرام","answer":"الجواب: نعم فعلها صحيح، وليس هناك حاجة للتجديد، فهي أحرمت من الميقات، ثم أصابها الحيض، تبقى على إحرامها، وتفعل أفعال الحج ما عدا الطواف، والسعي يؤجل، فتقف مع الناس بعرفة، وفي مزدلفة، وترمي الجمار، وتقص من رأسها، وتحل، فإذا طهرت؛ طافت، وسعت والحمد لله، وليس عليها أن تعيد الإحرام، إحرامها من الميقات كافٍ، والحيض لا يبطل الإحرام، الإحرام باقٍ، ولكن يمنع من الطواف. وهكذا النفاس لو ولدت في عرفة، أو بعد عرفة؛ تفعل أفعال الحج كلها، إلا الطواف، والسعي تؤجل حتى تطهر. نعم.  المقدم: سماحة الشيخ! حتى ولو لم تكن قد اشترطت؟ الشيخ: نعم؟ المقدم: حتى ولو لم تكن قد اشترطت، تقول: وهل إن اشترطت عند نيتها للإحرام، ثم جاءتها الحيضة يلزمها إعادة الإحرام بعد الطهر؟ الشيخ: إذا كانت شرطت لها الحل لها التحلل إذا كانت اشترطت، قالت: محلي حيث حبستني .... مقصودها من الحيض يعني: إذا أصابها الحيض تحل، فهذا لها الحل، أما إذا ما قصدها هذا القصد تخاف من أن يصيبها مرض، أو نحوه، فالحيض ليس بمانع، الحيض، حجت عائشة، وأصابها الحيض قبل دخول مكة، وأمرها النبي ﷺ أن تفعل ما يفعل الحجاج إلا الطواف. فالمقصود: أنها إذا قالت: محلي حيث حبستني عند الإحرام، قالت: إن حبسني حابس فمحلي حيث حبستني، هذا إذا منعها مرض، أو منعها عدو؛ لها أن تحل، أما الحيض لا يمنعها، لكن لو كانت تقصد الحيض جاءت للعمرة مثلًا، ومعها رفاق، فأحرمت بالعمرة، وقالت: إن حبسني حابس، ومقصودها حتى الحيض إذا حبسها حتى تحل، وترجع مع أصحابها، فهي على نيتها، أما الحيض ما يمنع الحج، ولو قالت: إن حبسني حابس، الحيض تمشي تمضي في حجها، وإذا طهرت تطوف، وتسعى، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16169/حكم-من-اتاها-الحيض-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76907.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":17333,"question":"السائلة من جمهورية مصر العربية، ومقيمة بالدمام تقول: نويت الإحرام من الميقات، ثم بعد ذلك.. هذه المرأة نوت الإحرام من الميقات، ثم بعد ذلك نزل عليها الحيض قبل الوقوف بعرفة، ثم طهرت في اليوم الحادي عشر، وسعت، وطافت بدون إعادة للإحرام أي: أنها لم تذهب مرة أخرى للميقات لتجدد إحرامها بعد أن طهرت، فهل فعلها صحيح؟","title":"حكم من أتاها الحيض بعد الإحرام","answer":"الجواب: نعم فعلها صحيح، وليس هناك حاجة للتجديد، فهي أحرمت من الميقات، ثم أصابها الحيض، تبقى على إحرامها، وتفعل أفعال الحج ما عدا الطواف، والسعي يؤجل، فتقف مع الناس بعرفة، وفي مزدلفة، وترمي الجمار، وتقص من رأسها، وتحل، فإذا طهرت؛ طافت، وسعت والحمد لله، وليس عليها أن تعيد الإحرام، إحرامها من الميقات كافٍ، والحيض لا يبطل الإحرام، الإحرام باقٍ، ولكن يمنع من الطواف. وهكذا النفاس لو ولدت في عرفة، أو بعد عرفة؛ تفعل أفعال الحج كلها، إلا الطواف، والسعي تؤجل حتى تطهر. نعم.  المقدم: سماحة الشيخ! حتى ولو لم تكن قد اشترطت؟ الشيخ: نعم؟ المقدم: حتى ولو لم تكن قد اشترطت، تقول: وهل إن اشترطت عند نيتها للإحرام، ثم جاءتها الحيضة يلزمها إعادة الإحرام بعد الطهر؟ الشيخ: إذا كانت شرطت لها الحل لها التحلل إذا كانت اشترطت، قالت: محلي حيث حبستني .... مقصودها من الحيض يعني: إذا أصابها الحيض تحل، فهذا لها الحل، أما إذا ما قصدها هذا القصد تخاف من أن يصيبها مرض، أو نحوه، فالحيض ليس بمانع، الحيض، حجت عائشة، وأصابها الحيض قبل دخول مكة، وأمرها النبي ﷺ أن تفعل ما يفعل الحجاج إلا الطواف. فالمقصود: أنها إذا قالت: محلي حيث حبستني عند الإحرام، قالت: إن حبسني حابس فمحلي حيث حبستني، هذا إذا منعها مرض، أو منعها عدو؛ لها أن تحل، أما الحيض لا يمنعها، لكن لو كانت تقصد الحيض جاءت للعمرة مثلًا، ومعها رفاق، فأحرمت بالعمرة، وقالت: إن حبسني حابس، ومقصودها حتى الحيض إذا حبسها حتى تحل، وترجع مع أصحابها، فهي على نيتها، أما الحيض ما يمنع الحج، ولو قالت: إن حبسني حابس، الحيض تمشي تمضي في حجها، وإذا طهرت تطوف، وتسعى، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16169/حكم-من-اتاها-الحيض-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76907.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":17376,"question":"نعم يا سماحة الشيخ، تقول الأخت: ما السر في كون الحائض إذا طهرت قبل المغرب تقضي صلاة الظهر، مع أن وقتها قد خرج؟","title":"الحكمة من قضاء الحائض الظهر إذا طهرت قبل المغرب","answer":"الجواب: لأن العصر يستمر وقتها إلى غروب الشمس، يقول النبي ﷺ: من أدرك ركعةً من العصر قبل أن تغرب الشمس فقد أدرك العصر، ومن أدرك ركعة من الصبح قبل أن تطلع الشمس فقد أدرك الصبح فإذا طهرت في آخر النهار أفتى بعض الصحابة بذلك أنها تصلي الظهر، والعصر جميعًا؛ لأنها أدركت بعض الوقت، فأشبهت المريض، تصلي الظهر، والعصر جميعًا، إذا كان طهرها قبل العصر، قبل غروب الشمس بركعة فأكثر، وهكذا إذا طهرت قبل الشمس بقليل بركعة تصلي الفجر، لو طهرت قبل طلوع الفجر في آخر الليل تصلي المغرب والعشاء. نعم. المقدم: أحسن إليك يا شيخ.","link":"https://binbaz.org.sa/fatwas/16225/الحكمة-من-قضاء-الحاىض-الظهر-اذا-طهرت-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59401.mp3","categories":["الحيض والنفاس","وقت الصلاة","قضايا المرأة"]},{"id":17383,"question":"في آخر أسئلة هذه السائلة (ن. س. ب) من الرياض تقول سماحة الشيخ: عندما تأتيها الدورة الشهرية يستمر نزول الدم حوالي أربعة أيام، ثم ينقطع، وتأتي بعد ذلك كدرة، وتستمر تقريبًا ثلاثة أيام، ثم يعاودها الدم مرةً أخرى، ولكنه دم مختلف عن الذي يأتيها في بداية الدورة، ويستمر تقريبًا، ثم ينقطع، وتأتيها بعد ذلك كدرة، ثم صفرة، وتستمر حوالي أربعة أيام، ويكون المجموع اثنا عشر يومًا، السؤال هو: هل تدع الصلاة طوال الاثني عشر يومًا كلها؟ أم ماذا تفعل؟","title":"حكم الدم الخارج بعد الحيض","answer":"الجواب: تدع الصلاة أيام الحيض أيام عادتها، فإذا انتهت، رأت الطهارة تصلي تصوم، ولا تلتفت إلى هذه الدماء الأخرى، النقط، أو الصفرة، أو ما أشبه ذلك، كل هذا دم فساد، تحفظ بشيء من القطن، وتوضأ لكل صلاة حتى تأتي الدورة الأخرى، وهذه الأشياء التي تقطعت عليها هذا دم فاسد، لا يلتفت إليه، بل عليها أن تصوم، وتصلي، وتتوضأ لكل صلاة، قالت أم عطية -رضي الله عنها-: \"كنا لا نعد الكدرة، والصفرة بعد الطهر شيئًا\" ولما اشتكى بعض النساء إليه ﷺ قال: امكثي قدر ما كانت تحبسك حيضتك، ثم اغتسلي وصلي. المقصود: أنها تمكث أيام العادة، وما بعدها تصلي، وتصوم، وإذا كان معها دم، أو قطرات، أو صفرة، أو شيء تحفظ، وتوضأ لكل صلاة، كل ما دخل الوقت تتوضأ، وتصلي. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16239/حكم-الدم-الخارج-بعد-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77013.mp3","categories":["الحيض والنفاس"]},{"id":17405,"question":"سماحة الشيخ! في آخر أسئلتها تقول السائلة: البعض من الناس يقولون: بأن المرأة طول فترة النفاس وهي أربعون يومًا بعد الولادة إذا ماتت فهي حورية أي: في الجنة، فهل هذا صحيح؟","title":"ما ثواب المرأة إذا ماتت في فترة النفاس؟","answer":"الجواب: لا، هذا ما له أصل، لكن يرجى لها الخير، جاء في بعض الأحاديث ما يدل على أنها إذا ماتت بسبب الولادة أنها شهيدة، يرجى لها خير، أما كونها حورية، ما أعلم له أصلًا، لكن يرجى لها الخير إذا ماتت بسبب الولادة، يرجى أن تكون من الشهداء، يرجى لها الخير، كصاحب الهدم، والغرق، نعم.","link":"https://binbaz.org.sa/fatwas/16264/ما-ثواب-المراة-اذا-ماتت-في-فترة-النفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77106.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17501,"question":"سماحة الشيخ! السائلة من سوريا تقول: امرأة تأتيها الدورة الشهرية بعد ثمانية أيام فينقطع عنها الدم، وترى الطهر الأبيض، ثم تغتسل وتصلي، بعد ذلك تراودها حالة لمدة خمسة أيام أو أكثر ترى الطهر الأبيض في الصباح، وفي نفس اليوم ترى أثرًا وتتكرر مثل هذه الحالة في اليوم عدة مرات، ما حكم ذلك مأجورين؟","title":"حكم خروج الصفرة من المرأة بعد الطهر","answer":"الشيخ: إذا مضت العادة وطهرت لا تلتفت إلى النقط اللي تأتيها بعد ذلك أو الصفرة أو غير ذلك حتى تأتي العادة، الحمد لله، تقول أم عطية: \"كنا لا نعد الكدرة والصفرة بعد الطهر شيئًا\"، وأم عطية صحابية من أصحاب النبي ﷺ، فإذا استكملت العادة ورأت الطهارة تغتسل وتبقى طاهرة إلى العادة الأخرى، وما يقع بينهما من رطوبات أو صفرة أو كدرة أو قطرات دم هذه ما تعتبر، لكن تستنجي منها تتحفظ منها بقطن ونحوه، وتتوضأ لكل شيء إذا حدث شيء في أوقات الصلاة تتوضأ للصلاة، وإذا استمر معها يوم أو يومين تتوضأ لكل صلاة إذا دخل الوقت. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16414/حكم-خروج-الصفرة-من-المراة-بعد-الطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77406.mp3","categories":["الحيض والنفاس"]},{"id":17657,"question":"(س. س. س) هذا السائل رمز لاسمه من مكة المكرمة، السائلة (س. س. س) تقول: ذهبت امرأة لتأدية مناسك العمرة، وطافت بالبيت وسعت وقصرت شعرها وهي حائض، ما الحكم؟ وماذا عليها مأجورين؟","title":"ما حكم من اعتمرت وهي حائض؟","answer":"الجواب: عليها أن تعيد الطواف إذا طافت وهي حائض عليها أن تعيد، أما السعي يجزي، فعليها أن تعيد الطواف، وتعيد التقصير، تقصر من رأسها بعد الطواف، والسعي يكفيها، يعني الطواف من الحائض غير صحيح لابد من الطهارة، فعليها أن ترجع إلى مكة وليس لزوجها قربانها حتى تطوف إذا كان لها زوج، ترجع وتطوف والحمد لله، ثم تـفضي إلى تقصير من جميع رأسها وتمت عمرتها. فإن كان زوجها قد وطئها؛ فعليها فدية ذبيحة تذبح في مكة للفقراء، وعليها أن تكمل العمرة وتأتي بعمرة جديدة من الميقات بدل العمرة التي أفسدتها بالجماع، تطوف لعمرتها السابقة، وتقصر، ثم تأتي بعمرة جديدة إذا كان قد جامعها الزوج، وعليها ذبيحة تذبح في مكة للفقراء.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16586/ما-حكم-من-اعتمرت-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59427.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":17666,"question":"تقول: إذا كان هناك فتاة لم تعلم بأحكام الحيض، وما يجب على المرأة أن تفعله؛ إلا بعد سنوات، فكيف تنصحونها فيما مضى من حياتها؟","title":"توجيه لمن لم تعلم بأحكام الحيض إلا بعد سنوات","answer":"الجواب: إذا كانت لا تصوم، لا، تقضي الصوم، فهذا الأحوط لها أن تصوم، ينبغي لها أن تصوم، لأنها مكلفة، وتساهلت في الأمر، وهذا شيء لا يجهل، يعرفه المسلمون، فتساهلها لا يسقط عنها الصيام، فالذي نرى لها أن تصوم، وإن طالت المدة، تقضي ولو غير متتابع، تصوم ما أوجب الله عليها من رمضانات مضت، ولو مفرقة، لا حرج في ذلك، هذا هو الأظهر، والأبين في الأدلة الشرعية.\nوأما الصلاة؛ فليس عليها صلاة، الحائض لا صلاة عليها، فإذا صلت وهي حائض، صلاتها باطلة، ليس عليها في هذا شيء؛ إلا التوبة إلى الله، كونها تصلي وهي حائض، عليها التوبة إلى الله، والصلاة باطلة، وليس عليها شيء. أما الصوم فعليها أن تقضي الصوم، ولو كانت صامت في أيام الحيض، صومها في أيام الحيض غير صحيح، فعليها أن تقضيه. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16598/توجيه-لمن-لم-تعلم-باحكام-الحيض-الا-بعد-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72710.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17671,"question":"وأخيرًا تسأل أختنا عن مدة النفاس الشرعية؟ جزاكم الله خيرًا.","title":"مدة النفاس الشرعية","answer":"الجواب: مدة النفاس أربعون يومًا، هذا أقصاها عند جمهور أهل العلم، حكاه غير واحد، حكاه ابن تيمية رحمه الله، وصاحب المغني، وغيرهما، أكثر النفاس أربعون يومًا، وقال بعض أهل العلم: خمسون، وقال بعضهم: ستون، لكنها أقوالهم ضعيفة، فهي مخالفة للدليل، وقد ثبت من حديث أم سلمة \"أن النفساء كانت تقعد في عهد النبي ﷺ أربعين يوما\"، يعني: أقصى ما تقعد، أكثر ما تقعد، وهو الذي عليه فتوى الصحابة رضي الله عنهم وأرضاهم، أنها تقعد أربعين يوماً، إلا أن ترى الطهر قبل ذلك، إن رأت الطهر وهي في العشرين، أو في الثلاثين؛ تغتسل، وتصلي، وتصوم، وتحل لزوجها، لكن إذا استمر معها الدم؛ فإنها تبقى أربعين، فإذا تمت الأربعون تغتسل وتصلي، ولو معها الدم، وتحل لزوجها، إلا إذا وافقت دم الحيض حادث الحيض؛ تجلس ولا تصوم، ولا تصلي وقت الحيض.\nأما إذا لم يصادف الزائد على الأربعين وقت الحيض؛ فإنها تغتسل، وتصلي، وتصوم، ولو معها الدم؛ لأنه دم فساد، ليس بدم نفاس، هذا هو الصواب الذي عليه أكثر أهل العلم، وهو الذي جاء عن الصحابة وأفتى به الصحابة رضي الله عنهم وأرضاهم. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16602/مدة-النفاس-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72712.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17676,"question":"هذا سائل للبرنامج يقول: سماحة الشيخ! ما حكم استعمال حبوب منع الحيض في رمضان بالنسبة للمرأة والحج؛ لتتمكن هذه المرأة من أداء عبادتها؟","title":"حكم استعمال حبوب منع الحيض في رمضان والحج","answer":"الجواب: لا حرج في ذلك، لا حرج في هذا. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16607/حكم-استعمال-حبوب-منع-الحيض-في-رمضان-والحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59505.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17685,"question":"سماحة الشيخ! يسأل عن طواف الوداع هل هو واجب؟ ولماذا سمي بطواف الوداع؟ وهل الحائض والنفساء لهما طواف وداع؟","title":"حكم طواف الوداع وخاصة للحائض والنفساء","answer":"الجواب: طواف الوداع واجب في حق الحجاج عند الخروج من مكة إلى بلادهم؛ سمي وداعًا لأنه آخر شيء؛ لأنه يطوف عند السفر كأنه يودع البيت بذلك كما يودع الإنسان أقاربه عند السفر، فإذا أراد السفر من مكة؛ فإنه يودع البيت يطوف طواف سبعة أشواط بالبيت عند السفر إلى بلاده، هذا خاص بالحجاج. أما العمرة فلا يجب لها وداع، لكن لو طاف لا بأس ولكن لا يجب، والحائض ليس عليها وداع والنفساء ليس عليها وداع يقول ابن عباس: «أمر الناس أن يكون آخر عهدهم بالبيت إلا أنه خفف عن المرأة الحائض» وهكذا النفساء ليس عليهما وداع. نعم.","link":"https://binbaz.org.sa/fatwas/16624/حكم-طواف-الوداع-وخاصة-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59514.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":17686,"question":"إذا حاضت المرأة قبل أن تبدأ بالعمرة يا شيخ فماذا تعمل بعد أن أحرمت يقول؟","title":"ما حكم من حاضت بعد إحرامها للعمرة؟","answer":"الجواب: تبقى في مكة حتى تطهر ثم تطوف وتسعى وتقصر، فإن دعت الحاجة إلى سفرها إلى الطائف أو جدة أو غيرهما سافرت وهي على إحرامها ثم ترجع حتى تؤدي طواف العمرة وسعيها، إلا أن كانت شرطت: إن حبسني حابس ثم أصابها الحيض؛ فلها التحلل إذا أرادت يعني أصابها عذر حبسني حابس يعني: عذر كالحيض، فإنها تحل ولا شيء عليها، أو أصابها مرض. نعم.","link":"https://binbaz.org.sa/fatwas/16625/ما-حكم-من-حاضت-بعد-احرامها-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59515.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":17687,"question":"هل يجوز للحائض أن تدخل الحرم؟","title":"حكم دخول الحائض الحرم","answer":"الجواب: مرور، أما الجلوس لا، المرور في المسجد أو في الحرم مرور لا بأس.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16627/حكم-دخول-الحاىض-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59516.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":17694,"question":"السائلة أختنا من القصيم (ن.ع. ح) في سؤالها الثاني تذكر بأنها أصابتها آلام الولادة وكانت صلاة العشاء قد دخلت، فمن شدة الآلام تقول: لم أستطع الصلاة، وبعد أن يسر الله عليها وانتهت من الأربعين قضت الصلاة، هل عملها هذا صحيح؟","title":"حكم من لم تصل العشاء بسبب آلام الولادة","answer":"الجواب: إذا كان الألم معه طلق ومعه دم فلا عليها صلاة هذا تبع النفاس، إذا أصابها الطلق وخرج منها الدم ولم تستطع الصلاة صار هذا من النفاس يحكم به تبع النفاس فلا قضاء عليها، أما إذا كان لا، إنما هو آلام وإلا ما فيه طلق ولا دم تقضيها، إذا كان ..... تقضيها مثلما فعلت، أما إذا كان لا، قد أحست بالطلق وخرج الدم فهذه المرأة لا قضاء عليها في تلك الصلاة التي تركتها بعد وجود الطلق وخروج الدم. نعم.","link":"https://binbaz.org.sa/fatwas/16640/حكم-من-لم-تصل-العشاء-بسبب-الام-الولادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77603.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17709,"question":"هذه سائلة رمزت لاسمها بـ (أ. أ. أ) تقول سماحة الشيخ: هل الصفرة والكدرة في بداية الدورة الشهرية من الحيض حيث إن ذلك حصل لها في أيام الدورة المعتادة وتركت الصلاة والصيام ماذا عليها؟","title":"حكم الصفرة والكدرة في بداية الدورة الشهرية","answer":"الجواب: نعم، تعتبر من العادة، الصفرة والكدرة المتصلة بالحيض قبله أو بعده من جملته تعتبر من الحيض، أما المنفصلة اللي تأتي قبل وتنقطع هذه لا تعتبر أو يأتيها بعد الطهر صفرة وكدرة ما تعتبر هذه تصلي وتصوم وتوضأ لكل صلاة، فالصفرة والكدرة التي قبل العادة أو بعدها غير متصلة تصوم وتصلي وتوضأ لكل صلاة، أما العادة تبدأ بصفرة وتنتهي بصفرة هذه من جملة العادة. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16669/حكم-الصفرة-والكدرة-في-بداية-الدورة-الشهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77619.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17746,"question":"سماحة الشيخ! تذكر هذه السائلة من سوريا وتقول في سؤالها الثاني: هل يجوز التظاهر بالصلاة والفتاة في الدورة الشهرية؟","title":"حكم تظاهر الحائض بالصلاة","answer":"الجواب: لا. لا تظاهر بالصلاة وهي في الدورة الشهرية الحمد لله معذورة، إذا كانت تخشى أنه يظن بها السوء تقول: إني الآن لا أصلي، إذا كانت تخشى أن يظن بها السوء تبين أنها لا تصلي. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16710/حكم-تظاهر-الحاىض-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77709.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":17799,"question":"هذه سائلة للبرنامج تقول سماحة الشيخ: تذكر بأنها امرأة حجت منذ أعوام، وبعد أيام وأثناء الطواف جاءتها الدورة، ولم تخبر أحدًا حتى زوجها، تقول: هي امرأة كبيرة في السن، وتود من سماحتكم الإفادة، ماذا تعمل؟","title":"حكم من حاضت أثناء الطواف ولم تخبر أحدًا","answer":"الجواب: إذا كان الطواف نافلة فلا شيء عليها، فإن كان الطواف فريضة: طواف عمرة أو حج فريضة طواف الإفاضة طواف العمرة طواف الوداع، هذا عليها إن كان طواف الوداع عليها ذبيحة تذبح بدل طواف الوداع في مكة للفقراء، توكل من يذبحها للفقراء في مكة، وإن كان طواف الإفاضة أو طواف العمرة، لابد من الرجوع، فإن كانت قد رجعت وأدت حجة أخرى أو عمرة أخرى كفى والحمد لله، فإن كان ما أدت عمرة ولا أدت حجًا؛ فعليها أن ترجع حتى تؤدي العمرة التي حاضت .. طوافها، أو تطوف للحج الذي حاضت في طواف الحج، ولو مضى عليها سنون، هي لا تزال عليها الطواف، ترجع إلى مكة وتطوف الطواف اللي عليها طواف الحج، وإن كان عمرة عليها أن تأتي تطوف طواف العمرة وتسعى وتقصر، ولو مضى عليها سنون. وإن كانت أتاها زوجها لها زوج؛ عليها تذبح ذبيحة في مكة للفقراء، في طواف العمرة، وهكذا إذا كان في طواف الحج، وإن كانت في طواف العمرة؛ عليها أن تعيد عمرة، تكمل العمرة هذه ثم تأتي بعمرة جديدة من الميقات التي أحرمت في العمرة الأولى منه. نعم.","link":"https://binbaz.org.sa/fatwas/16780/حكم-من-حاضت-اثناء-الطواف-ولم-تخبر-احدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59710.mp3","categories":["الحيض والنفاس","الطواف بالبيت","قضايا المرأة"]},{"id":17816,"question":"هل يمكن قول الأذكار والاستماع للمصحف المرتل من القرآن في أثناء فترة الحيض بالنسبة للمرأة؟","title":"حكم إتيان الحائض بالأذكار واستماع القرآن","answer":"الجواب: نعم، يستحب للمرأة النفساء والحائض أن تأتي بالأذكار الشرعية صباحًا ومساء وغيرهما، وأن تستمع للقرآن المسجل أو من غيرها الذي يقرأ، ويجوز لها القراءة بنفسها على الصحيح عن ظهر قلب؛ لئلا تنسى تقرأ عن ظهر قلب؛ لأن مدة الحيض والنفاس تطول بخلاف الجنب فإنه لا يقرأ حتى يغتسل؛ لأن مدته شيئًا يسيرًا، الجنب يستطيع أن يغتسل في الحال ويقرأ أما الحائض فمدتها تطول والنفساء مدتها تطول، ولهذا الصحيح أنه لا حرج عليهما بأن يقرأا عن ظهر قلب. نعم.","link":"https://binbaz.org.sa/fatwas/16809/حكم-اتيان-الحاىض-بالاذكار-واستماع-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77822.mp3","categories":["الحيض والنفاس","الأدعية والأذكار","قضايا المرأة"]},{"id":17859,"question":"من أسئلتها سماحة الشيخ تقول: هل يجوز لي أن أستمع إلى القرآن -وهي حائض-؟","title":"حكم استماع الحائض للقرآن","answer":"الجواب: نعم، لها أن تستمع وهي حائض أو نفساء، ولها أن تقرأ أيضًا؛ لأن الحيض والنفاس يطول، ما هو مثل الجنب، أما الجنب لا يقرأ حتى يغتسل، أما الحائض والنفساء فالصواب أن لهما القراءة عن ظهر قلب، أو من المصحف من وراء حائل، كالقفازين عند الحاجة، وإلا فتقرأ عن ظهر قلب، ولا حرج على الصحيح، أما حديث لا تقرأ الحائض شيئًا من القرآن فهو حديث ضعيف.","link":"https://binbaz.org.sa/fatwas/16866/حكم-استماع-الحاىض-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59804.mp3","categories":["الحيض والنفاس","قضايا المرأة","القرآن وعلومه"]},{"id":17893,"question":"السؤال الأخير الذي تعرضه أختنا تقول فيه: البعض من النساء تصوم في فترة حيضها خاصة في رمضان لجهل أو لغيره، فأرجو من سماحتكم التكرم ببيان ما يحرم على الحائض وما يجب عليها عند انتهاء مدة حيضتها؟ جزاكم الله خيرًا.","title":"حكم الصيام وقراءة القرآن للحائض","answer":"الجواب: الحائض لا تصوم ولا يصح منها الصوم، صومها باطل، ولا يجوز لها نية الصوم، وإذا فعلت ذلك فعليها التوبة إلى الله من ذلك، والندم والعزم أن لا تعود في ذلك، وعليها قضاء الأيام اللي وقع فيها الحيض من رمضان، عليها أن تقضيها؛ لأن صومها غير صحيح، والحائض عليها إذا رأت الدم أن تدع الصلاة وتدع الصيام، وأن لا يقربها زوجها بالجماع، وأن لا تمس المصحف، وأن لا تطوف إن كانت في مكة لحج أو عمرة حتى تطهر، ومتى طهرت تغتسل غسل الجنابة، تغتسل بالماء في بدنها كله ثم بعد الغسل تباح لزوجها وتصلي مع الناس وتصوم مع الناس؛ لأن الحيض انتهى، كل هذا مما يتعلق بالحائض. وإذا كانت في حج أو عمرة لا تطوف حتى تطهر ولا بأس أن تلبي وتذكر الله وتسبح وتهلل وتقف مع الناس في عرفات، ترمي الجمار.. تقف معهم في مزدلفة ولو كانت حائضًا لكن لا تطوف حتى تطهر.\nواختلف العلماء هل تقرأ أو ما تقرأ؟\nالصواب: أنها لها أن تقرأ عن ظهر قلب، لا تمس المصحف ولكن تقرأ المحفوظ لها عن ظهر قلبها؛ لأن مدتها تطول فعليها مشقة في ترك القراءة وقد تنسى ما حفظت، بخلاف الجنب فإنه لا يقرأ حتى يغتسل، الجنب لا يقرأ حتى يغتسل. أما الحائض والنفساء فالصواب أنهما تقرأان، لا بأس لكن مما في صدرهما، يعني: عن ظهر قلب لا تقرأان من المصحف، ولو احتاجتا إلى المصحف جاز لها مسه من دون حائل عند مراجعة بعض الآيات يكون في يديها قفازان أو شبه القفازين حتى لا تباشر المصحف وقت طلب الآية أو الآيات التي تحتاج إلى مراجعتها أو تستعين بمن تشاء من أخواتها حتى يراجعن لها المصحف فيما أشكل عليها أو غلطت فيه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16942/حكم-الصيام-وقراءة-القران-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84614.mp3","categories":["الأعذار المبيحة للفطر","الحيض والنفاس","قضايا المرأة"]},{"id":18210,"question":"أثناء العادة الشهرية، هل يجوز أن أذكر اسم الله تعالى في القلب مثل أن أقول: بسم الله الرحمن الرحيم، أو أستغفر الله، أو أستمع إلى القرآن الكريم، أو أقول بعد كل أذان: اللهم رب هذه الدعوة التامة، والصلاة القائمة آت سيدنا محمدًا ﷺ الوسيلة والفضيلة وابعثه المقام المحمود الذي وعدته، أو أدعو الله في قلبي وجهوني؟ جزاكم الله خيرًا.","title":"يشرع للحائض الأذكار والأدعية واستماع القرآن","answer":"الجواب: الحائض والنفساء يشرع لهما ما يشرع للناس من التسبيح والتهليل والتكبير والذكر والدعاء والاستغفار بالقلب واللسان، لا بالقلب وحده بل حتى باللسان، مشروع لها أن تذكر الله وتسبحه وتعظمه، وتجيب المؤذن والمقيم تجيبهما، وتقول مثل قولهما، وتقول عند الحيعلة: لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، وتصلي على النبي بعد الأذان عليه الصلاة والسلام، تقول: اللهم! رب هذه الدعوة التامة.. إلى آخره، كل هذا مشروع للجميع الحائض والنفساء وغيرهما. وإنما الخلاف في القرآن هل تقرأ أو ما تقرأ، هذا محل الخلاف، وأما الأذكار والدعوات والاستغفار فليس فيها خلاف، وتلبي إذا كانت حاجة تقول: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك، وتسمي عند الأكل وعند الشرب تحمد الله وتستغفره وتذكره كثيرًا هذا لا شيء فيه عند جميع أهل العلم. وإنما اختلف العلماء رحمة الله عليهم فيما يتعلق بالقرآن هل تقرأ أو ما تقرأ، فذهب جمع من أهل العلم وحكاه بعضهم وهو قول الأكثر أنها لا تقرأ واحتجوا بحديث روي عن رسول الله ﷺ أنه كتب إلى أهل اليمن: أن لا يمس القرآن إلا طاهر قالوا: والحائض تدخل في هذا، والجواب أن هذا إنما هو في المس لا تمسه، وأما القرآن فإنه تقرأ كما يقرأ المحدث الذي لم يتوضأ وإنما النهي عن مسه فهي لا تمسه، كما لا يمسه الجنب والمحدث، ولكن لا مانع من القراءة للمحدث حدثًا أصغر غير الجنابة يقرأ القرآن عن ظهر قلب. فهكذا الحائض تقرؤه عن ظهر قلب لا بأس، واحتج المانعون أيضًا بحديث رواه الترمذي عن النبي عليه الصلاة والسلام أنه قال: لا تقرأ الحائض ولا الجنب شيئًا من القرآن والجواب عن هذا أنه حديث ضعيف؛ لأنه من رواية إسماعيل بن عياش رحمه الله عن الحجازيين وروايته عنهم ضعيفة عند أهل العلم، فالصواب أن الحائض والنفساء لهما القراءة عن ظهر قلب من غير مس المصحف كالمحدث حدثًا أصغر يقرأ ولكن لا يمس المصحف. أما الجنب فلا يقرأ لا عن ظهر قلب ولا عن مس المصحف حتى يغتسل؛ لأن الجنب مدته قصيرة متى فرغ من حاجته اغتسل فلهذا كان أمره خاصًا، والحجة في ذلك أنه ﷺ كان إذا أصابته الجنابة لا يقرأ القرآن، كما ثبت من حديث علي  قال: \"كان النبي ﷺ لا يحجزه شيء عن القرآن إلا الجنابة\"، وفي رواية: أنه قرأ أنه لما خرج من قضاء الحاجة قرأ بعض القرآن، وقال: هذا لمن ليس جنبًا، أما الجنب فلا ولا آية. فدل ذلك على أن الجنب لا يقرأ القرآن حتى يغتسل، والحائض والنفساء لا تقاسان عليه، لأن مدتهما تطول ففي حرمانهما من القرآن مشقة عظيمة فلهذا الصواب أنهما تقرأان لكن من دون مس المصحف، ولا يجوز قياسهما على الجنب. فإن دعت الحاجة إلى القراءة من المصحف جازت من وراء حائل كأن تمسه من وراء قفازين، أو يمسه لها غيرها تمسكه عليها بنتها أو أختها الطاهرة وتقرأ بالنظر إليه من غير أن تمسه، لا بأس بهذا، ولكن مسها له لا يجوز حتى تطهر كالمحدث وكالجنب أيضًا حتى يغتسل، أما هي فإنها تقرؤه عن ظهر قلب، كالمحدث حدثًا أصغر، هذا هو الصواب. وأما التسبيح والتهليل والأذكار والدعاء والاستغفار فهذه مشروعة للجميع للجنب والحائض والنفساء والمحدثين كلهم لا يمنعون من هذا، وإنما الخلاف في القرآن فقط هذا محل الخلاف بين أهل العلم، وفق الله الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/17257/يشرع-للحاىض-الاذكار-والادعية-واستماع-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_856/nour_85603.mp3","categories":["الأدعية والأذكار","قضايا المرأة","الحيض والنفاس"]},{"id":18243,"question":"نختم هذه الحلقة برسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من العراق تقول: إني المستمعة من الجمهورية العراقية: أحلام إبراهيم محمد، تحية إسلامية من صميم القلب أرجو فيها لكم مزيدًا من التقدم إلى ما فيه الخير والأفضل للإسلام والمسلمين، مع العلم أنني أرسلت لكم رسالة مسبقة، ولم أستمع إلى الرد منكم أرجو منكم أن تردوا على أسئلتي لصالح الإسلام والمسلمين، ولكم مني جزيل الشكر.تسأل وتقول: هل يجوز دخول الحائض إلى المقبرة؟وهل يجوز أن تقرأ العزائم من سور القرآن على الغير وهي على تلكم الحال؟","title":"حكم دخول الحائض المقبرة وحكم رقيتها لغيرها","answer":"الجواب: أما ذهابها إلى المقبرة فلا، لا يشرع لها الذهاب إلى المقبرة؛ لأن الرسول ﷺ لعن زائرات القبور، سواءً كانت حائضًا أو طاهرًا، ليس للنساء زيارة القبور، لكن لو مرت بالمقبرة لحاجة، طريق فلا فرق بين كونها حائض أو غير حائض، مرورها بالمقبرة لحاجة الطريق ذاهبة إلى جهة، أو راجعة من جهة لا يضر ذلك، أما أن تزورها لقصد الزيارة فلا يجوز، سواءً كانت طاهرة أو حائضًا أو نفساء، فليس للنساء زيارة القبور مطلقًا. وأما كتب العزائم، أو قراءة العزائم من القرآن، فاختلف العلماء في ذلك: هل لها أن تقرأ القرآن وهي حائض أو نفساء، على قولين: ذكر بعضهم التحريم وأنه قول الأكثر من أهل العلم؛ لأنها محدثة حدثًا أكبر، يلزمها فيه الغسل إذا طهرت فهي مثل الجنب، والجنب لا يجوز أن يقرأ القرآن ولا يمس المصحف الجنب حتى يغتسل، شبهوها بالجنب، وهكذا النفساء. وقال آخرون من أهل العلم: لا، ليست مثل الجنب، الجنب يستطيع أن يغتسل في الحال ويقرأ، أما الحائض فليست تشبهه؛ لأنها تبقى مدة وهكذا النفساء هي في حاجة إلى أن تقرأ القرآن. فالصواب أنه يجوز لها أن تقرأ عن ظهر قلب، وهكذا من طريق لمس المصحف من وراء حائل، كأن يكون عليها قفازان أو رداء أو غيره تمسك مصحف به يكون من وراء الحائل، للحاجة إلى ذلك، أما مسه مباشرة فليس لها مس المصحف كالمحدث حدثًا أصغر ليس لهما مس المصحف. وأما ما ورد أن النبي ﷺ قال: لا تقرأ الحائض ولا الجنب شيئًا من القرآن، فهو حديث ضعيف عند أهل العلم لا تقوم به الحجة، والصواب أن لها أن تقرأ وهكذا النفساء؛ لأن مدتهما تطول، فليستا مثل الجنب، أما الجنب فليس له أن يقرأ لا من المصحف ولا عن ظهر قلب حتى يغتسل، هذا هو الصواب، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/17291/حكم-دخول-الحاىض-المقبرة-وحكم-رقيتها-لغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_908/nour_90807.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":18342,"question":"هل المرأة إذا حنت شعرها أو كفيها في وقت العادة الشهرية، هل هذا يعتبر حرامًا؟","title":"حكم استعمال الحائض للحناء","answer":"الجواب: ليس في ذلك حرج كونها تستعمل الحناء في حال الحيض، أو في حال النفاس في يديها، أو في رجليها أو في شعرها كل ذلك لا بأس به، ولو كانت في حال الحيض والنفاس. نعم.","link":"https://binbaz.org.sa/fatwas/17403/حكم-استعمال-الحاىض-للحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86102.mp3","categories":["الحيض والنفاس"]},{"id":18444,"question":"رسالة بتوقيع فتاة الجنوب (ع. ح. ع) أختنا لها مجموعة من الأسئلة في سؤال لها تقول: عندنا بعض النساء الكبيرات في السن يقلن: إذا حاضت المرأة فإنه يحرم عليها مس بعض أنواع الرياحين، ومس شجرة الحناء، فهل هذا القول صحيح؟","title":"حكم القول بعدم مس الريحان والحناء للحائض","answer":"الجواب: ليس بصحيح، هي مثل غيرها من النساء، لها مس الرياحين ولها مس شجرة الحناء، ولها غير ذلك مما يباح للنساء، ماعدا الصلاة فإنها لا تصلي حتى تطهر، وما عدا الصوم فإنها لا تصوم أيضًا حتى تطهر، وماعدا مس المصحف فإنها لا تمس المصحف حتى تطهر. أما قراءة القرآن عن ظهر قلب ففيها خلاف بين أهل العلم، والصواب أنه لا حرج عليها أن تقرأ عن ظهر قلب وليست مثل الجنب، الجنب مدته قصيرة يغتسل متى فرغ من حاجته، أما الحائض والنفساء فمدتهما تطول فلا حرج عليهن في القراءة عن ظهر قلب من دون مس المصحف في أصح قولي أهل العلم. وأما كون الحائض تمس الرياحين أو تمس شجرة الحناء أو تمس شيئًا آخر مما يمسه الناس مما يباح كمس الحبوب أو الفواكه أو اللبن أو غير ذلك؛ لا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17549/حكم-القول-بعدم-مس-الريحان-والحناء-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86509.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":18633,"question":"في آخر أسئلة هذه السائلة تقول: سماحة الشيخ، بالنسبة للمرأة إذا وضعت حملها قبل رمضان بعشرة أيام، وانقطع عنها الحيض، فهل يجوز لها أن تصوم؟","title":"حكم صيام رمضان لمن انقطعنفاسها بعد عشرة أيام","answer":"الجواب: نعم، إذا وضعت حملها، وانقطع عنها دم النفاس تصوم، ولو ما مضى عليها إلا عشرة أيام، أو خمسة عشر يوم، متى انقطع الدم، ورأت الطهارة؛ تغتسل وتصلي، وتصوم ولو ما مضى إلا عشرة أيام، أو خمسة عشر يومًا، أو عشرين يومًا، لكن إذا استمر معها الدم تبقى لا تصلي ولا تصوم حتى تكمل أربعين يومًا، فإذا كملت الأربعين تغتسل، وتصلي، وتصوم، ولا يمنعها الدم الذي بعد الأربعين دم فساد يصير بعد الأربعين دم فساد، فإذا تمت الأربعين، أكملت الأربعين، ولم تطهر فإنها تغتسل، وتصلي، وتحفظ بشيء من الدم بقطن ونحوه، وتوضأ لكل صلاة؛ لأن نهاية النفاس أربعون هذه نهايته، فالدم بعد الأربعين يكون دم فساد، إلا إذا وافق عادة الحيض، إذا وافق العادة تجلس كما العادة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17741/حكم-صيام-رمضان-لمن-انقطع-نفاسها-بعد-عشرة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78711.mp3","categories":["من يجب عليه الصوم","الحيض والنفاس","قضايا المرأة"]},{"id":18684,"question":"أختنا تسأل أيضًا وتقول: هل يجوز وضع الحناء على الشعر أو اليدين والمرأة حائض؟ وأيضًا ما حكم خلط الحناء مع البنزين؟","title":"حكم استعمال المرأة الحائض للحناء","answer":"الجواب: ليس في هذا شيء، سواء كانت حائضًا أو نفساء، أو في حالة طهارة، كونها تتحنى في رأسها، أو في يديها لا بأس، وإذا كان في خلطه بالبنزين شيء من المصلحة والفائدة؛ فلا نعلم بأسًا في ذلك، نعم. المقدم: جزاكم الله خيرًا. إذًا: إذا تحنت المرأة وهي حائض أو كانت نفساء لا يؤثر هذا على الطهر؟ الشيخ: نعم، ما يؤثر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17805/حكم-استعمال-المراة-الحاىض-للحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87304.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":18750,"question":"هذه السائلة مريم من المنطقة الشمالية تقول: بأنها امرأة متزوجة تبلغ من العمر الثامنة والثلاثين، تصلي وتصوم، وقامت بالتعلم في كيفية تغسيل النساء المتوفيات، ولقد قامت امرأة كبيرة وقالت لها: بأنه لا يجوز لها بأن تغسل الميت؛ كونها ما زالت امرأة تأتيها أو يأتيها العذر الشرعي، وحلفت يمين بأن لا تغسل أحدًا، ثم اضطرت لتغسيل ميتة؛ لأن أهلها لم يجدوا من يقوم بتغسيلها فقامت بذلك، هل هذا صحيح بأن المرأة لا تغسل النساء كونها يأتيها العذر الشهري؟","title":"حكم تغسيل الحائض للموتى من النساء","answer":"الجواب: هذا الكلام باطل، لها أن تغسل ولو أن تأتيها العادة، فالمقصود: أن المرأة تغسل النساء، أو تغسل زوجها، ولا بأس سواء كانت تأتيها العادة أو ما تأتيها العادة، والأمر في هذا واسع، والحمد لله، سواء شابة أو كبيرة تأتيها العادة أو ما تأتيها العادة. أما هذه التي حلفت فعليها كفارة يمين، أنها ما تغسل ثم غسلت عليها كفارة يمين عن يمينها، وهي إطعام عشرة مساكين، أو كسوتهم، لكل مسكين نصف صاع من قوت البلد كيلو ونصف من قوت البلد، من تمر أو غيره، أو كسوتهم كل واحد له قميص أو إزار ورداء عن يمينها. وأما هذه التي قالت لها: لا تغسلي وأنت تأتيك العادة هذا غلط، فالمرأة تغسل النساء، وتغسل زوجها مطلقًا سواء كانت شابة تأتيها العادة، أو عجوزًا، نعم.","link":"https://binbaz.org.sa/fatwas/17883/حكم-تغسيل-الحاىض-للموتى-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79009.mp3","categories":["غسل الميت وتجهيزه","الحيض والنفاس","قضايا المرأة"]},{"id":18789,"question":"هل يباح للحائض أن تقرأ الكتب الدينية أو الصحف الإسلامية؟","title":"حكم قراءة الحائض الكتب الدينية","answer":"الجواب: نعم، لا بأس عليها أن تقرأ الصحف الدينية، والكتب الإسلامية، كمثل كتب الحديث، كتب الفقه، كتب التفسير، حتى ولو التفسير، ولو فيها القرآن، لا بأس بذلك؛ لأن الكتاب كتاب تفسير ليس مصحفًا، والصحيح أيضًا أنها لها أن تقرأ القرآن في حال الحيض والنفاس، من دون مس المصحف؛ لأن حدثها يطول، بخلاف الجنب. أما الجنب فلا يقرأ حتى يغتسل؛ لأن مدته لا تطول، متى فرغ من حاجته أمكنه الغسل؛ ولهذا كان -عليه الصلاة والسلام- لا يقرأ القرآن حال كونه جنبًا، ويقول: أما الجنب فلا ولا آية. أما الحائض والنفساء فمدتهما تطول، وقد تنسى حفظها، ويشق عليها ترك القرآن في هذه المدة الطويلة، فلهذا كان الصحيح من قولي العلماء في هذا الجواز، وبعض أهل العلم منعها من ذلك، وقاسها على الجنب، والصواب أنها لا، ليست مثل الجنب، والقياس غير صحيح؛ لأن الجنب مدته قصيرة، والمرأة الحائض مدتها طويلة، والنفاس أطول، فلا يقاس الطويل على القصير، ولا يقاس ما فيه مضرة كبيرة على ما لا مضرة فيه. أما ما روي عنه ﷺ أنه قال: لا تقرأ الحائض، ولا الجنب شيئًا من القرآن فهو حديث ضعيف، لا تقوم به الحجة عند أهل العلم؛ لأنه من رواية إسماعيل بن عياش عن الحجازيين، وروايته عنهم ضعيفة، لا يحتج بها عند أهل العلم؛ ولأن الرسول ﷺ قال لـعائشة لما حاضت في حجة الوداع: دعي العمرة وأحرمي بالحج، واغتسلي، وافعلي ما يفعله الحجاج، غير أن لا تطوفي بالبيت حتى تطهري ولم يمنعها من القرآن، ولم يقل لها: لا تقرئي، وإنما منعها من الطواف والصلاة، فدل ذلك على أن القرآن لا حرج فيه للحائض والنفساء، من دون مس المصحف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17922/حكم-قراءة-الحاىض-الكتب-الدينية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87603.mp3","categories":["الحيض والنفاس"]},{"id":19026,"question":"تقول في سؤال آخر: إذا اغتسلت من الحيض، وبعد أن أرى الطهر ينزل مني دم، وذلك يكون في يوم الغسل أو بعد الغسل بيوم أو يومين، وأحيانًا ثلاثة، وهذا وراثة بيننا، وأنا عند كل صلاة أغتسل لهذا الدم؛ لأنه ينزل مني بين الوقتين، هل إذا رأيت الطهر ثم نزل مني هذا الدم أغتسل عندما أراه؟ أم يكفي الوضوء؟ أفيدوني جزاكم الله خيرًا.","title":"حكم خروج الدم من المرأة بعد رؤية الطهر","answer":"الجواب: إذا كان النازل دمًا واضحًا فهو من تبع الحيض؛ لقول أم عطية رضي الله عنها وهي من أصحاب النبي ﷺ \"كنا لا نعد الكدرة والصفرة بعد الطهر شيئًا\" هذا يدل على أن غير الكدرة والصفرة تعد من الحيض، وتمنع الصلاة، والصيام، والجماع من الزوج. وأما إذا كان النازل ليس بدم صحيح بل كدرة أو صفرة شيء ملتبس هذا لا يلتفت إليه، ولا مانع من الصلاة، بل عليك أن تصلي وتصومي، وتباحين لزوجك، ولا حرج في ذلك، مثلما في الحديث المتقدم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18197/حكم-خروج-الدم-من-المراة-بعد-روية-الطهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79602.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":19056,"question":"هل يجب الصوم قضاء الصوم إذا أتت المرأة الدورة الشهرية بعد صلاة المغرب أو قبل الصلاة بعد الإفطار؟","title":"حكم من جاءها الحيض بعد غروب الشمس وهي صائمة","answer":"الجواب: ليس عليها شيء؛ لأنها أكملت الصيام، يعني: إذا جاء الحيض بعد غروب الشمس، ولو قبل الصلاة فلا شيء عليها، أو بعد الصلاة ما في قضاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18231/حكم-من-جاءها-الحيض-بعد-غروب-الشمس-وهي-صاىمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92811.mp3","categories":["الحيض والنفاس","ما لا يفسد الصيام","قضايا المرأة"]},{"id":19084,"question":"تسأل في سؤالها الثاني: هل يجب قضاء الصلاة إذا حاضت المرأة وقت .........","title":"حكم من جاءها الحيض وقد دخل وقت صلاة ولم تصلها","answer":"الجواب: .........\nالدخول فلا قضاء لأنها: ما أدركت الوقت، وأما بعد الدخول فلا حرج عليها ولا تفريط فلا قضاء عليها، ولكن إذا طهرت في الوقت تقضي الصلاة التي طهرت في وقتها، طهرت في وقت الظهر تصلي الظهر والعصر، طهرت في وقت المغرب أو العشاء تصلي المغرب والعشاء، طهرت في وقت الفجر تصلي الفجر. أما لو جاءها الحيض بعد الزوال فإنها لا تقضي الظهر، وكذلك لو جاءها الحيض بعد أذان الفجر وبعد طلوع الفجر لا يلزمها بعد الطهر قضاء صلاة الفجر، وبعض أهل العلم قالوا: عليها أن تقضي هذا الوقت، ولكن ليس عليه دليل، وإن قضت فلا بأس، إن قضته فلا حرج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18228/حكم-من-جاءها-الحيض-وقد-دخل-وقت-صلاة-ولم-تصلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92810.mp3","categories":["الحيض والنفاس","قضاء الفوائت","قضايا المرأة"]},{"id":19099,"question":"تسأل أختنا في سؤالها الثاني وتقول: هل صحيح أنه لا يجوز وضع الحناء على الرأس والمرأة حائض؟","title":"حكم وضع المرأة الحناء على الرأس وهي حائض","answer":"الجواب: ليس به بأس، ليس هذا بصحيح، الصواب أنه لا حرج في ذلك، لها أن تضع الحناء على رأسها أو في يديها، أو رجليها وإن كانت في حال حيض أو نفاس، لا بأس بذلك. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18301/حكم-وضع-المراة-الحناء-على-الراس-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88408.mp3","categories":["الحيض والنفاس"]},{"id":19111,"question":"تسأل أختنا فتقول: هل يجوز للمرأة أن تستعمل دواءً يمنع عنها الدورة الشهرية، ولاسيما في الحج ورمضان والعمرة؟","title":"حكم استعمال ما يمنع الحيض للحج أو الصوم","answer":"الجواب: نعم، إذا دعت الحاجة إلى ذلك فلا بأس في رمضان أو في أيام الحج أو العمرة لا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18290/حكم-استعمال-ما-يمنع-الحيض-للحج-او-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73705.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":19121,"question":"كيف تفرق المرأة بين دم العادة المتبعة أو المستمرة ودم الاستحاضة؟","title":"كيفية تفريق المرأة بين دم الحيض ودم الاستحاضة","answer":"الجواب: إذا طهرت من حيضتها وأصابها صفرة أو كدرة فهذا هو الاستحاضة، وإذا كان الدم في وقت العادة؛ فهذا حيض ولو صفرة أو كدرة إذا جاء في وقت الحيض، وإذا استمر بها الحيض، عادتها سبعًا كانت عادتها سبعًا فاستمر بها إلى عشر فلا بأس أن تجلس، يجب عليها أن تجلس ولا تصلي ولا تصوم تترك الصلاة؛ لأن العادة تزيد وتنقص إلى خمسة عشر يومًا، أكثرها خمسة عشر يومًا؛ فهي تزيد وتنقص، فإذا صارت عادتها سبعًا ثم زادت في بعض الأحيان ورأت الدم ثمانًا تسعًا عشرًا فلا بأس، لا تصلي ولا تصوم ولا يقربها الزوج. أما إذا طهرت من حيضتها ثم رأت صفرة أو كدرة في أيام الطهر؛ فإنه لا عمل عليها تصلي وتصوم ولا عمل عليها، لكن تتوضأ لكل صلاة، لقول النبي ﷺ للمستحاضة: توضئي لكل صلاة، ولقول أم عطية رضي الله عنها: \"كنا لا نعد الكدرة والصفرة بعد الطهر شيئًا\"، أم عطية صحابية تقول: \"كنا لا نعد الكدرة والصفرة بعد الطهر شيئًا\"، يعني: فيها الوضوء فقط. نعم. المقدم: الحمد لله، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18298/كيفية-تفريق-المراة-بين-دم-الحيض-ودم-الاستحاضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73707.mp3","categories":["الحيض والنفاس"]},{"id":19125,"question":"تسأل أختنا كم مدة الطهر؟","title":"مدة الطهر والحيض","answer":"الجواب: الصحيح ليس للطهر حد محدود، ولا للحيض حد محدود، لكن الغالب أن الحيض يكون ستة أيام، سبعة أيام، والغالب أن يكون الطهر ثلاث وعشرون يومًا أو أربع وعشرون يومًا هذا هو الأغلب، فإن حاضت ستة أيام صار الطهر أربعًا وعشرين وإن حاضت سبعًا صار الطهر ثلاثًا وعشرين هذا هو الأغلب؛ لأنه قد يزيد وينقص. فليس هناك حد محدود، فإذا كانت عادتها عشرًا وطهرها شهرًا فلا بأس أو أكثر، بعض النساء قد تأتيها العادة في الشهرين والثلاثة مرة، أو في السنة مرة، فليس لهذا حد محدود. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18293/مدة-الطهر-والحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73706.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":19145,"question":"أخت لنا من أبها بعثت برسالة تقول فيها (ع.ش.ش)، أختنا تسرد أيضًا قصة مطولة كعادة بعض المستمعين ملخصها: أن عذرها زادت أيامه من أربعة أيام إلى ثمانية أيام مما جعلها تضطرب في أدائها للعمرة، وتسأل سماحة الشيخ: كيف تتصرف لو تكرر ذلكم الحال معها؟","title":"كيفية التصرف لمن زادت أيام عادتها على المعتاد","answer":"الجواب: العادة تزيد وتنقص أيها الأخت في الله، فإذا كانت العادة أربعة أيام أو خمسة وزادت ستة، سبعة، ثمانية، تسعة، فلا بأس، لا تصلين ولا تصومين، اجلسي، دعي الصلاة والصيام؛ لأن العادة تزيد وتنقص، وإذا كنت في حج أو عمرة لا تطوفي حتى تطهري؛ لقول النبي ﷺ لعائشة رضي الله عنها: افعلي ما يفعل الحاج غير أن لا تطوفي بالبيت حتى تطهري فالحائض والنفساء تمتنعان من الطواف حتى تطهرا، وهكذا الصلاة؛ لأن العادة تزيد وتنقص. وأكثر مدة الحيض خمسة عشر يومًا عند جمهور أهل العلم، فإذا استمر معك الحيض إلى خمسة عشر يومًا فهذا حيض، فإن زاد على ذلك صار استحاضة، ترجعين إلى عادتك الأولى، وما زاد عليها تصلي فيه، وتصومين، وتحلين لزوجك؛ لأنه علم أنه استحاضة، وترجعين إلى عادتك الأولى التي هي أربع أو خمس أو نحو ذلك، إذا جاءت دعي الصلاة والصيام، وإذا ذهبت تغتسلين، ويكون الدم الذي معك المستمر هذا دم استحاضة، يعني: دم فساد، لا يمنع الصلاة ولا يمنع الصوم ولا يمنع الزوج، ولكنك تتوضئين لكل صلاة، يعني: تستنجين وتتوضئين لكل صلاة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18336/كيفية-التصرف-لمن-زادت-ايام-عادتها-على-المعتاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88606.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":19288,"question":"نعود إلى رسالة الأخت المستمعة هدى، أختنا عرضنا جزءًا كبيرًا من أسئلتها، وفي هذه الحلقة تسأل وتقول: هل يجوز أن تفسر المرأة القرآن حتى وإن كانت معذورة ؟","title":"حكم تفسير المرأة القرآن وهي حائض","answer":"الجواب: نعم، لها أن تفسر القرآن إذا كان عندها علم، تنقل من كلام المفسرين وتفسر من كلام أهل التفسير المعروفين كـابن كثير أو ابن جرير والبغوي وغيرهم من أهل العلم، إذا كانت على بصيرة وعلى علم فلها أن تفسر ولو كانت في حالة الدورة الشهرية، أو في حال النفاس؛ لأن الصحيح من أقوال العلماء أن لها أن تقرأ عن ظهر قلب، ليست مثل الجنب، الجنب مدته قصيرة، فليس له القراءة حتى يغتسل، أما الحائض والنفساء فمدتهما طويلة، فلا بأس أن تقرأا عن ظهر قلب وإن كانتا في مدة الحيض والنفساء على الصحيح. وأما حديث ابن عمر المعروف: أن الرسول ﷺ نهى أن تقرأ الحائض والجنب شيئًا من القرآن، فهو عند أهل العلم ضعيف؛ لأنه من رواية إسماعيل بن عياش عن الحجازيين وهو عندهم ضعيف، إذا روى عنهم ضعيف عند أهل العلم، وإنما تعتبر روايته عن الشاميين . نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18486/حكم-تفسير-المراة-القران-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89304.mp3","categories":["الحيض والنفاس"]},{"id":19389,"question":"تسأل أختنا وتقول: ما حكم قراءة الحائض للقرآن بدون أن تمس المصحف؟","title":"حكم قراءة الحائض للقرآن دون مس المصحف","answer":"الجواب: في هذه المسألة خلاف بين العلماء والأقرب والأظهر أنه لا حرج؛ لأن مدتها تطول ليست مثل الجنب، الجنب مدته قصيرة يغتسل ثم يقرأ، أما الحائض والنفساء فإن مدتهما تطول؛ فالأرجح والأصوب أنه لا حرج عليهما في القراءة عن ظهر قلب، هذا هو الأصل، ولا يجوز أن يقاس الحيض على الجنابة، فالحيض مدته تطول والنفاس أطول، أما حديث: لا تقرأ الحائض ولا الجنب شيئًا من القرآن، فهو حديث ضعيف عند أهل العلم لا تقوم به الحجة، فالراجح أنه لا حرج عليها -يعني: الحائض- أن تقرأ القرآن عن ظهر قلب، لا من المصحف بل عن ظهر قلب، وهكذا النفساء، من باب أولى. أما الجنب فلا، الجنب لا يقرأ القرآن لا عن ظهر قلب ولا من المصحف؛ للحديث الصحيح أن النبي عليه السلام كان لا يمنعه شيء من القرآن إلا الجنابة، وفي رواية أخرى: أنه ﷺ قرأ بعض الآيات ثم قال: هذا لمن ليس جنباً، أما الجنب ولا آية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18610/حكم-قراءة-الحاىض-للقران-دون-مس-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74004.mp3","categories":["الحيض والنفاس","قضايا المرأة"]},{"id":19457,"question":"هذه أخت سائلة أرسلت بمجموعة من الأسئلة تقول يا سماحة الشيخ: هل أستطيع أن أقرأ الآيات التي أحفظها وهي حائض، وطبعًا دون مس القرآن الكريم؟","title":"حكم قراءة الحائض والنفساء القرآن عن ظهر قلب","answer":"الجواب: الصواب لا حرج في ذلك عن ظهر قلب، ليست كالجنب، الجنب مدته يسيرة ويغتسل، أما الحائض مدتها طويلة، والنفساء كذلك. فإذا قرأت من دون مس المصحف فلا حرج إن شاء الله، أو من وراء حائل.","link":"https://binbaz.org.sa/fatwas/18702/حكم-قراءة-الحاىض-والنفساء-القران-عن-ظهر-قلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93902.mp3","categories":["الحيض والنفاس"]},{"id":19504,"question":"هذه سائلة تقول سماحة الشيخ: فتاة بلغها في النصف من رمضان الحيض، ولم تخبر الأهل، فهل عليها قضاء أو قضاء مع كفارة؟","title":"الواجب على المرأة التي أتاها الحيض في رمضان","answer":"الجواب: عليها القضاء، وإذا كان القضاء تأخر بعد رمضان آخر عليها القضاء مع إطعام مسكين عن كل يوم زيادة، إذا تأخر القضاء إلى رمضان آخر، وعليها التوبة إلى الله أيضًا من تساهلها وعدم صيامها. نعم.","link":"https://binbaz.org.sa/fatwas/18763/الواجب-على-المراة-التي-اتاها-الحيض-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93930.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":19575,"question":"هذه السائلة من أبها رمزت لاسمها بـ (ف. ف) تقول: سماحة الشيخ -حفظكم الله- سؤالها عن الحيض تقول: إذا أتى موعد الحيض وسبق ذلك آلام في البطن ثم كدرة، هذه الكدرة تبدأ مثلًا من الفجر حتى الليل، ثم بعد ذلك ينزل الدم هل تصلي فترة الكدرة أم لا، علمًا بأنها لا تستعمل حبوب مانع الحمل؟","title":"حكم الكدرة قبل وبعد الحيض","answer":"الجواب: هذه الكدرة تبع الحيض ما دام أنها عادة لها تبدأ الكدرة ثم الحيض، فهي من تبع الحيض قبله أو بعده، لا تصلي ولا تصوم ما خرج منها من الكدرة هذا حكمه حكم الحيض، وما بعد الحيض كذلك إذا كان متصلًا به حكمه حكم الحيض إذا كان عادة لها، يكون من العادة الكدرة في أوله أو الكدرة في آخره تابعة له. نعم.","link":"https://binbaz.org.sa/fatwas/18834/حكم-الكدرة-قبل-وبعد-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94722.mp3","categories":["الحيض والنفاس"]},{"id":19592,"question":"هل الحائض والنفساء عليهما طواف الإفاضة؟","title":"حكم طواف الإفاضة للحائض والنفساء","answer":"الجواب: عليهما طواف الإفاضة نعم بعد الطهر، إذا جاءها الحيض قبل يوم العيد عليهما أن تمسكا حتى تطهرا، فإذا طهرتا طافتا للإفاضة ولو بعد أيام منى، ولو في الخامس عشر والرابع عشر والسادس عشر، عليهما الإمساك عن الطواف حتى تطهرا فإذا طهرتا اغتسلتا وطافتا، طواف الإفاضة لابد منه ركن، طواف الإفاضة ركن الحج لابد منه.","link":"https://binbaz.org.sa/fatwas/18853/حكم-طواف-الافاضة-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94909.mp3","categories":["الحيض والنفاس","الطواف بالبيت"]},{"id":19607,"question":"تقول السائلة يا سماحة الشيخ: أرجو فتوى منكم في طلاق المرأة وهي حائض، هل يقع الطلاق والمرأة حائض أثابكم الله؟","title":"هل يقع الطلاق والمرأة حائض؟","answer":"الجواب: هذا الموضوع فيه خلاف بين العلماء، أكثر العلماء يرون أنه يقع الطلاق في الحيض، هذا الذي عليه أكثر أهل العلم، وذهب بعض أهل العلم إلى أنه لا يقع، إذا كان يعلم الزوج أنها في الحيض، إذا طلقها في الحيض فقد أثم ولا يقع إذا كان يعلم، أما إذا كان ما يعلم إلا بعد الطلاق منها فالطلاق يقع إذا كان لا يعلم. أما إذا كان يعلم أنها حائض قبل أن يطلق، ثم أقدم على الطلاق فالصواب أنه لا يقع، وعليه التوبة لأنه لا يجوز، أما إذا كان لا يعلم حالها وطلقها، ثم أخبرته أنها حائض فالطلاق يقع، طلاقه يقع إذا كان لا يعلم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18875/هل-يقع-الطلاق-والمراة-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94917.mp3","categories":["الطلاق","الحيض والنفاس","قضايا المرأة"]},{"id":19632,"question":"السائلة تقول: امرأة أسقطت أربع مرات، وعمر الجنين أقل من شهرين، ولم تصل حتى تطهر، هل عليها قضاء؟","title":"حكم صلاة من أسقطت جنينًا أقل من شهرين","answer":"الجواب: إذا كان فيه بيان، إذا كان فيه علامة إنسان: رأس، أو يد، أو رجل؛ فهو نفاس، تترك الصلاة أربعين ليلة إلا أن تطهر قبل الأربعين، أما إذا كان دم ما فيه رأس، ولا رجل؛ فالواجب عليها الصلاة، وقضاء الصلاة التي تركت؛ لأنه ما هو بنفاس مجرد الدم ليس بنفاس، إلا إذا كان فيه علامة إنسان إما يد، أو رجل، أو رأس؛ شيء يبين أنه طفل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18901/حكم-صلاة-من-اسقطت-جنينا-اقل-من-شهرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94832.mp3","categories":["الحيض والنفاس","قضاء الفوائت","قضايا المرأة"]},{"id":19654,"question":"سماحة الشيخ تقول هذه الأخت السائلة: (أ. م. ش) المملكة العربية السعودية المدينة النبوية، تقول: هل للحائض أو النفساء أن تقرأ شطر آية، مثل أن تقول: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ[البقرة: 156]، أو حَسْبِيَ اللَّهُ لا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ[التوبة: 129] بنية الذكر، أو إذا كانت تطلب العلم فتقرأ على شخص جهرًا أو مرت بآية فتقرأ هذه الآية سردًا، فهل يجوز لها ذلك؟ وهل يجوز لها أن تقرأ القرآن قراءة قلبية دون التلفظ باللسان؟","title":"حكم قراءة الحائض والنفساء والجنب بعض الآيات في الدعاء","answer":"الجواب: إذا قرأ الإنسان بعض الآيات على سبيل الدعاء مثل: ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة، وعند المصيبة: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ[البقرة:156] ولو كان جنبًا، أو حائضًا، أو نفساء؛ لا حرج في ذلك، ليس لقصد القراءة بل لقصد أن المقام يناسب ذلك. والحائض على الصحيح لها أن تقرأ؛ لأن مدتها تطول، لها أن تقرأ من غير مس المصحف، بخلاف الجنب؛ فإنه ليس له أن يقرأ حتى يغتسل؛ لأن مدته قصيرة يمكن أن يغتسل في الحال. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18938/حكم-قراءة-الحاىض-والنفساء-والجنب-بعض-الايات-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95008.mp3","categories":["الحيض والنفاس","الأدعية والأذكار"]},{"id":19655,"question":"يا سماحة الشيخ! تقول: ما هي الأعمال التي تقوم بها الحائض والنفساء من الذكر والدعاء وغير ذلك؟","title":"الأذكار والأدعية التي تجوز للحائض","answer":"الجواب: تعمل.... مثل غيرها من الذكر والدعاء وغير ذلك، النفساء والحائض، إلا القرآن هو محل الخلاف بين العلماء، والصواب: أنها لها أن تقرأ عن ظهر قلب أيضًا لأن مدتها تطول، لكن لا تمس المصحف فإذا دعت الحاجة إلى مراجعة المصحف يكون من وراء حائل من وراء القفازين مع الطهارة. نعم.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18939/الاذكار-والادعية-التي-تجوز-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95009.mp3","categories":["الأدعية والأذكار","قضايا المرأة","الحيض والنفاس"]}]
